// Dealify — Marketplace flip-anything deal sniper
// Schema mirrors Flipify's reverse-engineered data model:
// FbSession -> Watchlist (saved search) -> Listing (marketplace item) -> deal scoring.
// Every watchlist is scoped to a flip vertical (lib/verticals.ts — vehicles,
// electronics, furniture, fashion, …) and every listing is classified into one;
// vehicles keep the full ML pricing pipeline, other verticals run the generic
// comp engine (lib/comps.ts) + per-vertical flip economics.

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

// App account — everyone signs up before entering the deal finder
model User {
  id           String   @id @default(cuid())
  email        String   @unique
  name         String?
  passwordHash String
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt

  // ---- Firebase Auth bridge (lib/firebase/) ----
  // Google/other federated identities sign in through Firebase on the
  // client; the server verifies the ID token (zero-dep JWKS check) and
  // links it to this account. Null = email/password-only account.
  firebaseUid String? @unique

  // ---- Email verification ----
  // Null = the address is not confirmed. The free trial only STARTS once the
  // address is verified (fake accounts gain nothing to abuse), except
  // federated accounts whose provider already verified the email.
  emailVerifiedAt DateTime?

  // ---- Push notifications (Firebase Cloud Messaging) ----
  // Web push tokens registered by the browser; the scanner fires FCM
---ENV REFS---
