const tab = await tools.browser.tabs.open({ url: "http://localhost:3001", focus: true });
await new Promise(r => setTimeout(r, 4000));
const list = await tools.browser.tabs.list();
const msgs = await tools.browser.console({ tabID: tab.id, level: "error", limit: 20 });
return JSON.stringify({ tab: list.tabs.find(t => t.id === tab.id), errors: msgs.messages }, null, 2);

const tab = await tools.browser.tabs.open({ url: "http://localhost:3001", focus: true });
const msgs = await tools.browser.console({ tabID: tab.id, level: "error", limit: 20 });
return JSON.stringify({ tab, errors: msgs.messages }, null, 2);

