659: /* Liquid Glass buttons — Apple-style translucent glass. The material is
660:  * built from layers, top to bottom:
661:  *   - a specular 1px rim along the top edge (light source above)
662:  *   - a soft inner sheen across the upper half (the "liquid" body)
663:  *   - a darker inner edge at the bottom (glass thickness / refraction)
664:  *   - a translucent tinted core with backdrop blur + saturation so the
665:  *     surface behind is genuinely refracted, not just dimmed
666:  *   - an ambient colored glow beneath (blue for primary, none for quiet)
667:  * On hover a skewed band of light sweeps across the button (::after),
668:  * like sunlight sliding over curved glass. Two strengths:
669:  *   .liquid-glass        — electric-blue tinted primary action
670:  *   .liquid-glass-quiet  — clear frosted glass secondary action
671:  * Apply via <Button variant="glass" | "glass-quiet" />. */
672: .liquid-glass,
673: .liquid-glass-quiet {
674:   position: relative;
675:   isolation: isolate;
676:   overflow: hidden;
677:   border: 1px solid rgb(255 255 255 / 16%);
678:   /* NOTE: the backdrop blur/saturation is applied via Tailwind utilities
679:    * (backdrop-blur-md backdrop-saturate-150) in the Button variant —
680:    * literal backdrop-filter declarations here get stripped by the dev
681:    * CSS pipeline, while the @property-based utilities survive. */
682:   transition-property: box-shadow, border-color, transform, filter;
683:   transition-duration: 220ms;
684: }
