687:   color: #ffffff;
688:   background-image:
689:     linear-gradient(180deg, rgb(255 255 255 / 22%), rgb(255 255 255 / 2%) 46%, rgb(9 30 66 / 18%)),
690:     linear-gradient(180deg, rgb(56 137 245 / 58%), rgb(23 106 222 / 46%));
691:   box-shadow:
692:     inset 0 1px 0 rgb(255 255 255 / 38%),
693:     inset 0 10px 16px -12px rgb(255 255 255 / 30%),
694:     inset 0 -2px 6px -2px rgb(3 16 40 / 45%),
695:     0 1px 2px rgb(0 0 0 / 24%),
696:     0 10px 30px -10px rgb(35 133 255 / 48%);
697: }
