699:   border-color: rgb(255 255 255 / 24%);
700:   box-shadow:
701:     inset 0 1px 0 rgb(255 255 255 / 46%),
702:     inset 0 10px 18px -12px rgb(255 255 255 / 38%),
703:     inset 0 -2px 6px -2px rgb(3 16 40 / 40%),
704:     0 1px 2px rgb(0 0 0 / 24%),
705:     0 14px 38px -10px rgb(35 133 255 / 66%);
