function MarketStrip() {
  const markets = ['Facebook Marketplace', 'eBay', 'OfferUp', 'Vinted', 'Gumtree', 'Kijiji']
  return (
    <section aria-label="Marketplaces Dealify scans" className="relative border-y border-white/[0.06] bg-[#07080b]">
      <div className={cn(SHELL, 'flex flex-col items-center justify-between gap-4 py-6 sm:flex-row')}>
        <p className="text-[10px] font-semibold uppercase tracking-[.2em] text-white/35">
          Scanning the marketplaces you already use
        </p>
        <ul className="flex flex-wrap items-center justify-center gap-x-6 gap-y-2.5">
          {markets.map((market) => (
            <li
              key={market}
              className="text-[13px] font-semibold tracking-tight text-white/45 transition-colors hover:text-white/80"
            >
              {market}
            </li>
          ))}
        </ul>
      </div>
    </section>
  )
}

