/* ------------------------------ interactive deal lab ------------------------------ */

function DealLab({ stats }: { stats: LandingStats | null }) {
  const liveDeal = stats?.topDeals?.find((deal) => deal.fairValue != null && deal.fairValue > 0)
  const marketValue = liveDeal?.fairValue ?? EXAMPLE_DEAL.fairValue ?? 6440
