import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { requireUser } from '@/lib/auth'
import { getPlanState, watchlistCount } from '@/lib/billing'
import { isVerticalId } from '@/lib/verticals'
import { normalizeMarket, MARKET_META } from '@/lib/marketplaces'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function GET() {
  const auth = await requireUser()
  if (auth.response) return auth.response
  const plan = await getPlanState(auth.user.id)
  const watchlists = await db.watchlist.findMany({
    where: { userId: auth.user.id },
    orderBy: { createdAt: 'desc' },
    include: {
      _count: { select: { listings: true } },
      scanRuns: {
        orderBy: { startedAt: 'desc' },
        take: 1,
      },
    },
  })

  const counts = await db.watchlistListing.groupBy({
    by: ['watchlistId'],
    where: { isNew: true },
    _count: { _all: true },
  })
  const newCounts = new Map(counts.map((c) => [c.watchlistId, c._count._all]))

