/** Per-IP+email request budget — blunts link-bombing and mailbox spam. */
const RATE_LIMIT = { max: 5, windowMs: 60 * 60 * 1000 }
const rateBuckets = new Map<string, number[]>()

function rateLimited(key: string): boolean {
  const now = Date.now()
  const hits = (rateBuckets.get(key) ?? []).filter((t) => now - t < RATE_LIMIT.windowMs)
  if (hits.length >= RATE_LIMIT.max) return true
  hits.push(now)
  rateBuckets.set(key, hits)
  // opportunistic global sweep so the map can't grow unbounded
  if (rateBuckets.size > 5000) {
