export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function PATCH(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const auth = await requireUser()
  if (auth.response) return auth.response
  const { id } = await params
  let body: any
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const existing = await db.watchlist.findUnique({ where: { id } })
  if (!existing || existing.userId !== auth.user.id) {
    return NextResponse.json({ error: 'Watchlist not found' }, { status: 404 })
  }

  const num = (v: any): number | null | undefined => {
    if (v === null || v === undefined) return undefined
    if (v === '' || v === 'any') return null
    const n = Number(v)
    return isFinite(n) ? n : undefined
  }

  const data: any = {}
  if (typeof body.name === 'string' && body.name.trim()) data.name = body.name.trim()
  if (typeof body.vertical === 'string' && isVerticalId(body.vertical)) data.vertical = body.vertical
  if (typeof body.marketplace === 'string') {
    const market = normalizeMarket(body.marketplace)
    // Only live markets are selectable — dead upstreams fall back to Facebook
    data.marketplace = MARKET_META[market].live ? market : 'FacebookMarketplace'
  }
  if (typeof body.query === 'string') data.query = body.query.trim() || null
  if (typeof body.categoryId === 'string') data.categoryId = body.categoryId.trim() || null
  if (typeof body.categorySlug === 'string') data.categorySlug = body.categorySlug.trim() || null
  if (typeof body.method === 'string' && ['query', '1', '2'].includes(body.method)) data.method = body.method
  if (body.minPrice !== undefined) data.minPrice = num(body.minPrice)
  if (body.maxPrice !== undefined) data.maxPrice = num(body.maxPrice)
  if (body.radiusKm !== undefined) data.radiusKm = Math.min(Math.max(num(body.radiusKm) ?? 60, 1), 500)
  if (body.lat !== undefined) data.lat = num(body.lat)
  if (body.lng !== undefined) data.lng = num(body.lng)
  if (typeof body.locationName === 'string') data.locationName = body.locationName
  if (typeof body.sortBy === 'string') data.sortBy = body.sortBy === 'suggested' ? 'suggested' : 'newest'
  if (body.minYear !== undefined) data.minYear = num(body.minYear)
  if (body.maxYear !== undefined) data.maxYear = num(body.maxYear)
  if (body.minOdometer !== undefined) data.minOdometer = num(body.minOdometer)
  if (body.maxOdometer !== undefined) data.maxOdometer = num(body.maxOdometer)
  if (typeof body.transmission === 'string') {
    data.transmission = ['automatic', 'manual'].includes(body.transmission) ? body.transmission : null
  }
  if (typeof body.sellerType === 'string' && ['both', 'private', 'dealer'].includes(body.sellerType)) {
    data.sellerType = body.sellerType
  }
  if (body.intervalSeconds !== undefined) {
    // Plan gate: the cadence never drops below this plan's floor; the
    // scanner service applies the same clamp at runtime.
    const plan = await getPlanState(auth.user.id)
    if (plan?.tier === 'locked') {
      return NextResponse.json(
        {
          error:
            'Your free trial has ended — choose a paid plan to keep tracking.',
          code: 'subscription_required',
        },
        { status: 402 }
      )
    }
    const floor = plan?.limits.minIntervalSeconds ?? 600
    data.intervalSeconds = Math.min(Math.max(num(body.intervalSeconds) ?? floor, floor), 21600)
    data.nextScanAt = computeNextScanAt(existing.lastScanAt, data.intervalSeconds)
  }
  if (body.maxListingAgeMinutes !== undefined) data.maxListingAgeMinutes = num(body.maxListingAgeMinutes)
  if (typeof body.active === 'boolean') data.active = body.active
  if (typeof body.paused === 'boolean') data.paused = body.paused
  if (body.markSeen === true) {
    await db.watchlistListing.updateMany({ where: { watchlistId: id }, data: { isNew: false } })
  }

  const watchlist = await db.watchlist.update({ where: { id }, data })
  return NextResponse.json({ watchlist })
}

export async function DELETE(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const auth = await requireUser()
  if (auth.response) return auth.response
  const { id } = await params
  const existing = await db.watchlist.findUnique({ where: { id } })
  if (!existing || existing.userId !== auth.user.id) {
    return NextResponse.json({ error: 'Watchlist not found' }, { status: 404 })
  }
  await db.watchlist.delete({ where: { id } })
  return NextResponse.json({ deleted: true })
}
