/**
 * DELETE — permanently delete the signed-in account.
 *
 * The privacy policy (/legal/privacy §7) promises in-app deletion, so this
 * must hold no matter which FK actions the SQLite database enforces: we
 * delete leaf-first in one transaction, then the user row itself. What goes:
 * watchlists (+ their scan runs and match edges), personal listing states,
 * alerts, push tokens, personal scan-engine sessions and login sessions.
 * Shared marketplace research rows (Listing) stay — they are not about the
 * user and power every other account's feed.
 *
 * Body: { confirm: 'DELETE' } — a typed confirmation, mirroring the dialog.
 */
export async function DELETE(req: NextRequest) {
  const auth = await requireUser()
  if (auth.response) return auth.response

  const body = await req.json().catch(() => ({}))
  if (body?.confirm !== 'DELETE') {
    return NextResponse.json(
      { error: 'Type DELETE to confirm account deletion' },
      { status: 400 }
    )
  }

  const userId = auth.user.id

  // Receipt numbers for the client toast (captured before the wipe)
  const [watchlists, engines, devices] = await Promise.all([
    db.watchlist.count({ where: { userId } }),
    db.fbSession.count({ where: { ownerUserId: userId } }),
    db.fcmToken.count({ where: { userId } }),
  ])

  try {
    await db.$transaction([
      // Leaf rows that hang off the user's watchlists
      db.scanRun.deleteMany({ where: { watchlist: { userId } } }),
      db.watchlistListing.deleteMany({ where: { watchlist: { userId } } }),
      db.watchlist.deleteMany({ where: { userId } }),
      // Per-user edges and events
      db.userListing.deleteMany({ where: { userId } }),
      db.alertEvent.deleteMany({ where: { userId } }),
      // Devices, personal scan engines, login sessions
      db.fcmToken.deleteMany({ where: { userId } }),
      db.fbSession.deleteMany({ where: { ownerUserId: userId } }),
      db.authSession.deleteMany({ where: { userId } }),
      // The account itself
      db.user.delete({ where: { id: userId } }),
    ])
  } catch (err: any) {
    console.error('[profile:delete]', err)
    return NextResponse.json(
      { error: err?.message ?? 'Could not delete the account — try again or contact support' },
      { status: 500 }
    )
  }

  // Every session row (cookie and Bearer) died with the transaction above;
  // clearing the cookie here just stops the browser replaying a dead token.
  const res = NextResponse.json({
    ok: true,
    deleted: { watchlists, engines, devices },
  })
  res.headers.append('Cache-Control', 'no-store')
  clearSessionCookie(res)
  return res
}
