input.content:
'use client'

/**
 * Settings — the profile menu's account tab. Account identity (including an
 * editable display name), scan controls, notification opt-in, security, data
 * export/privacy links, and the DANGER ZONE: permanent account deletion
 * (the flow the Privacy Policy §7 promises). Deletion requires typing the
 * word DELETE in the confirm dialog, then the server wipes the account in
 * one transaction and the session dies with it.
 */

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import {
  BadgeCheck,
  Bell,
  CheckCircle2,
  CreditCard,
  Database,
  Download,
  ExternalLink,
  FileText,
  KeyRound,
  Loader2,
  LogOut,
  Mail,
  Pause,
  Play,
  Radar,
  RefreshCw,
  Settings as SettingsIcon,
  ShieldAlert,
  ShieldCheck,
  UserRound,
} from 'lucide-react'
import { api, clearStoredAuthToken, storedAuthTokenHeader, timeAgo } from '@/lib/api'
import { useAppStore } from '@/lib/store'
import type { AuthUserView } from '@/lib/auth-view'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { PushOptIn } from '@/components/app/push-opt-in'

export function SettingsPanel({ user }: { user: AuthUserView }) {
  const router = useRouter()
  const setView = useAppStore((s) => s.setView)
  const queryClient = useQueryClient()
  const [deleteOpen, setDeleteOpen] = useState(false)
  const [confirmText, setConfirmText] = useState('')
  const [deleting, setDeleting] = useState(false)
  const [signingOut, setSigningOut] = useState(false)
  const [nameDraft, setNameDraft] = useState(user.name ?? '')
  const [savingName, setSavingName] = useState(false)
  const [bulkBusy, setBulkBusy] = useState<'pause' | 'resume' | null>(null)
  const [sendingReset, setSendingReset] = useState(false)
  const [exporting, setExporting] = useState(false)
  const [refreshing, setRefreshing] = useState(false)

  const { data: billing } = useQuery({
    queryKey: ['billing'],
    queryFn: api.billing.get,
    refetchInterval: 30000,
  })

  const { data: watchlistData, isLoading: watchlistsLoading } = useQuery({
    queryKey: ['watchlists'],
    queryFn: api.watchlists.list,
    refetchInterval: 60000,
  })

  const plan = billing?.plan
  const planLabel = !plan
    ? null
    : plan.tier === 'locked'
      ? plan.isTrial
        ? 'Trial ended'
        : 'No active plan'
      : plan.isTrial
        ? 'Pro trial'
        : plan.tier.toUpperCase()
  const displayName = user.name?.trim() || user.email.split('@')[0]
  const initials = displayName.slice(0, 1).toUpperCase()
  const emailVerified = Boolean(user.emailVerifiedAt)

  const watchlists = watchlistData?.watchlists ?? []
  const activeCount = watchlists.filter((w) => w.active && !w.paused).length
  const pausedCount = watchlists.filter((w) => w.paused).length
  const cadenceMinutes = plan?.limits.minIntervalMinutes ?? null
  const nextScanAt =
    watchlists
      .filter((w) => w.active && !w.paused && w.nextScanAt)
      .map((w) => w.nextScanAt as string)
      .sort()[0] ?? null

  async function signOut() {
    if (signingOut) return
    setSigningOut(true)
    // Same dance as the header: kill cookieless (Bearer) sessions too, then
    // wipe both mechanisms and re-enter through the public gate.
    const token = storedAuthTokenHeader()
    try {
      await fetch('/api/auth/logout', {
        method: 'POST',
        headers: token ? { Authorization: token } : undefined,
      })
    } catch {
      /* best-effort */
    }
    clearStoredAuthToken()
    queryClient.clear()
    window.location.assign('/')
  }

  async function saveName() {
    if (savingName) return
    const next = nameDraft.trim()
    if (next === (user.name ?? '')) {
      toast('No changes to save')
      return
    }
    setSavingName(true)
    try {
      await api.profile.updateName(next)
      setNameDraft(next)
      await queryClient.invalidateQueries({ queryKey: ['profile'] })
      // The header gets the name from the server-rendered user prop.
      router.refresh()
      toast.success(next ? 'Display name updated' : 'Display name cleared', {
        description: next
          ? 'Your header and account menu now show this name.'
          : 'We’ll use the first part of your email instead.',
      })
    } catch (e: any) {
      toast.error(e?.message ?? 'Could not update your name')
    } finally {
      setSavingName(false)
    }
  }

  async function setAllPaused(paused: boolean) {
    if (bulkBusy || watchlists.length === 0) return
    setBulkBusy(paused ? 'pause' : 'resume')
    try {
      await Promise.all(watchlists.map((w) => api.watchlists.update(w.id, { paused })))
      await queryClient.invalidateQueries({ queryKey: ['watchlists'] })
      toast.success(paused ? 'Scanning paused' : 'Scanning resumed', {
        description: paused
          ? `All ${watchlists.length} watchlist${watchlists.length === 1 ? '' : 's'} will stop until you resume.`
          : `All ${watchlists.length} watchlist${watchlists.length === 1 ? '' : 's'} are scanning again on your plan cadence.`,
      })
    } catch (e: any) {
      toast.error(e?.message ?? `Could not ${paused ? 'pause' : 'resume'} scanning`)
    } finally {
      setBulkBusy(null)
    }
  }

  async function sendResetLink() {
    if (sendingReset) return
    setSendingReset(true)
    try {
      await api.auth.forgotPassword(user.email)
      toast.success('Reset link sent', {
        description: `Check ${user.email} for a link to choose a new password. It expires in 60 minutes.`,
      })
    } catch (e: any) {
      toast.error(e?.message ?? 'Could not send the reset link')
    } finally {
      setSendingReset(false)
    }
  }

  async function exportData() {
    if (exporting) return
    setExporting(true)
    try {
      const [profile, wl, alerts, bill, scan] = await Promise.all([
        api.profile.get(),
        api.watchlists.list(),
        api.alerts.list(),
        api.billing.get(),
        api.session.get(),
      ])
      const payload = {
        exportedAt: new Date().toISOString(),
        account: {
          id: user.id,
          email: user.email,
          name: user.name,
          emailVerifiedAt: user.emailVerifiedAt ?? null,
        },
        profile,
        watchlists: wl.watchlists,
        alerts: alerts.alerts,
        billing: bill,
        scanEngine: scan,
      }
      const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `dealify-export-${new Date().toISOString().slice(0, 10)}.json`
      document.body.appendChild(a)
      a.click()
      a.remove()
      URL.revokeObjectURL(url)
      toast.success('Export ready', {
        description: 'Your account, profile, watchlists, alerts and billing data were downloaded as JSON.',
      })
    } catch (e: any) {
      toast.error(e?.message ?? 'Could not build your export')
    } finally {
      setExporting(false)
    }
  }

  async function refreshCachedData() {
    if (refreshing) return
    setRefreshing(true)
    try {
      await queryClient.invalidateQueries()
      await queryClient.refetchQueries({ type: 'active' })
      toast.success('Everything refreshed', {
        description: 'Feed, watchlists, alerts and billing were reloaded from the server.',
      })
    } catch {
      toast.error('Could not refresh cached data')
    } finally {
      setRefreshing(false)
    }
  }

  async function deleteAccount() {
    if (deleting) return
    setDeleting(true)
    try {
      const r = await api.profile.remove(confirmText)
      toast.success('Account deleted', {
        description:
          r.deleted.watchlists > 0 || r.deleted.engines > 0
            ? `${r.deleted.watchlists} watchlist${r.deleted.watchlists === 1 ? '' : 's'}, ${r.deleted.engines} scan engine${r.deleted.engines === 1 ? '' : 's'} and all personal data removed.`
            : 'All personal data has been removed.',
      })
      // The session died server-side with the account — leave nothing cached.
      clearStoredAuthToken()
      queryClient.clear()
      window.location.assign('/')
    } catch (e: any) {
      toast.error(e?.message ?? 'Could not delete the account')
      setDeleting(false)
    }
  }

  return (
    <div className="max-w-3xl space-y-6">
      {/* heading */}
      <div>
        <h1 className="flex items-center gap-2.5 text-2xl font-bold tracking-tight">
          <SettingsIcon className="h-6 w-6 text-primary" aria-hidden />
          Settings
        </h1>
        <p className="mt-1 text-sm text-muted-foreground">
          Your account, scanning, notifications and data — all in one place.
        </p>
      </div>

      {/* account identity */}
      <Card className="p-5 sm:p-6">
        <h2 className="flex items-center gap-2 text-[15px] font-semibold">
          <UserRound className="h-4 w-4 text-primary" aria-hidden />
          Account
        </h2>
        <div className="mt-4 flex items-start justify-between gap-4 flex-wrap">
          <div className="flex items-center gap-3.5 min-w-0">
            <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground text-lg font-bold">
              {initials}
            </span>
            <div className="min-w-0">
              <div className="truncate text-[15px] font-semibold">{displayName}</div>
              <div className="truncate text-[13px] text-muted-foreground">{user.email}</div>
              <div className="mt-1.5 flex flex-wrap items-center gap-1.5">
                {plan && planLabel && (
                  <Badge
                    className={
                      plan.tier === 'locked'
                        ? 'border-red-400/40 bg-red-400/10 text-red-300'
                        : plan.isTrial
                          ? 'border-amber-400/40 bg-amber-400/10 text-amber-300'
                          : 'bg-primary/15 text-primary'
                    }
                    variant="outline"
                  >
                    {planLabel}
                  </Badge>
                )}
                {emailVerified ? (
                  <Badge variant="outline" className="border-emerald-400/40 bg-emerald-400/10 text-emerald-300">
                    <BadgeCheck className="mr-1 h-3 w-3" aria-hidden />
                    Verified
                  </Badge>
                ) : (
                  <Badge variant="outline" className="border-amber-400/40 bg-amber-400/10 text-amber-300">
                    Email not verified
                  </Badge>
                )}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" onClick={() => setView('billing')} className="gap-2">
              <CreditCard className="h-4 w-4" aria-hidden />
              Manage plan
            </Button>
            <Button variant="ghost" onClick={signOut} disabled={signingOut} className="gap-2">
              <LogOut className="h-4 w-4" aria-hidden />
              {signingOut ? 'Signing out…' : 'Sign out'}
            </Button>
          </div>
        </div>
        {billing === undefined && <Skeleton className="mt-4 h-5 w-24" />}

        {/* display name */}
        <div className="mt-5 border-t border-border pt-4">
          <label htmlFor="display-name" className="text-[13px] font-medium">
            Display name
          </label>
          <div className="mt-1.5 flex gap-2">
            <Input
              id="display-name"
              value={nameDraft}
              onChange={(e) => setNameDraft(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') saveName()
              }}
              placeholder={user.email.split('@')[0]}
              maxLength={80}
              disabled={savingName}
              className="max-w-sm"
            />
            <Button
              onClick={saveName}
              disabled={savingName || nameDraft.trim() === (user.name ?? '')}
              className="gap-2 shrink-0"
            >
              {savingName ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden /> : <CheckCircle2 className="h-4 w-4" aria-hidden />}
              {savingName ? 'Saving…' : 'Save'}
            </Button>
          </div>
          <p className="mt-1.5 text-[11.5px] text-muted-foreground">
            Shown in the header and account menu. Leave it blank to use the first part of your email.
          </p>
        </div>
      </Card>

      {/* scanning */}
      <Card className="p-5 sm:p-6">
        <h2 className="flex items-center gap-2 text-[15px] font-semibold">
          <Radar className="h-4 w-4 text-primary" aria-hidden />
          Scanning
        </h2>
        <p className="mt-1.5 text-[13px] leading-relaxed text-muted-foreground">
          {cadenceMinutes
            ? `Your ${plan?.tier === 'pro' ? 'Pro' : plan?.tier === 'starter' ? 'Starter' : 'current'} plan re-checks every watchlist every ${cadenceMinutes} minutes.`
            : 'Every watchlist is re-checked on your plan cadence.'}
        </p>

        {watchlistsLoading ? (
          <div className="mt-4 grid gap-2 sm:grid-cols-3">
            <Skeleton className="h-20 rounded-lg" />
            <Skeleton className="h-20 rounded-lg" />
            <Skeleton className="h-20 rounded-lg" />
          </div>
        ) : watchlists.length === 0 ? (
          <div className="mt-4 rounded-lg border border-border bg-surface/60 p-4">
            <p className="text-[13px] text-muted-foreground">
              You don’t have any watchlists yet. Create one and Dealify will start scanning it automatically.
            </p>
            <Button variant="outline" onClick={() => setView('watchlists')} className="mt-3 gap-2">
              <Radar className="h-4 w-4" aria-hidden />
              Create a watchlist
            </Button>
          </div>
        ) : (
          <>
            <div className="mt-4 grid gap-2 sm:grid-cols-3">
              <div className="rounded-lg border border-border bg-surface/60 p-3">
                <div className="text-[11px] uppercase tracking-wide text-muted-foreground">Cadence</div>
                <div className="mt-0.5 text-lg font-semibold">
                  {cadenceMinutes ? `Every ${cadenceMinutes} min` : '—'}
                </div>
              </div>
              <div className="rounded-lg border border-border bg-surface/60 p-3">
                <div className="text-[11px] uppercase tracking-wide text-muted-foreground">Scanning</div>
                <div className="mt-0.5 text-lg font-semibold">{activeCount}</div>
                <div className="text-[11px] text-muted-foreground">
                  of {watchlists.length} watchlist{watchlists.length === 1 ? '' : 's'}
                </div>
              </div>
              <div className="rounded-lg border border-border bg-surface/60 p-3">
                <div className="text-[11px] uppercase tracking-wide text-muted-foreground">Paused</div>
                <div className="mt-0.5 text-lg font-semibold">{pausedCount}</div>
                <div className="text-[11px] text-muted-foreground">
                  {nextScanAt ? `Next scan ${new Date(nextScanAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}` : 'No scan scheduled'}
                </div>
              </div>
            </div>

            <div className="mt-4 flex flex-wrap items-center gap-2">
              <Button
                variant="outline"
                onClick={() => setAllPaused(true)}
                disabled={bulkBusy !== null || activeCount === 0}
                className="gap-2"
              >
                {bulkBusy === 'pause' ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden /> : <Pause className="h-4 w-4" aria-hidden />}
                Pause all
              </Button>
              <Button
                variant="outline"
                onClick={() => setAllPaused(false)}
                disabled={bulkBusy !== null || pausedCount === 0}
                className="gap-2"
              >
                {bulkBusy === 'resume' ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden /> : <Play className="h-4 w-4" aria-hidden />}
                Resume all
              </Button>
              <Button variant="ghost" onClick={() => setView('watchlists')} className="gap-2">
                Manage watchlists
                <ExternalLink className="h-3.5 w-3.5" aria-hidden />
              </Button>
            </div>
            <p className="mt-2 text-[11.5px] text-muted-foreground">
              Pausing keeps your watchlists and their history — scanning resumes from the normal cadence when you turn it back on.
            </p>
          </>
        )}
      </Card>

      {/* notifications */}
      <Card className="p-5 sm:p-6">
        <h2 className="flex items-center gap-2 text-[15px] font-semibold">
          <Bell className="h-4 w-4 text-primary" aria-hidden />
          Notifications
        </h2>
        <p className="mt-1.5 text-[13px] leading-relaxed text-muted-foreground">
          Push alerts fire the moment a watchlist surfaces a good-ROI listing or a price drop.
        </p>
        <div className="mt-3 rounded-lg border border-border bg-surface/60 p-3">
          <PushOptIn />
        </div>
      </Card>

      {/* security */}
      <Card className="p-5 sm:p-6">
        <h2 className="flex items-center gap-2 text-[15px] font-semibold">
          <ShieldCheck className="h-4 w-4 text-primary" aria-hidden />
          Security
        </h2>
        <div className="mt-3 space-y-2">
          <div className="flex items-center justify-between gap-3 rounded-lg border border-border px-3.5 py-3 flex-wrap">
            <div className="flex items-center gap-3 min-w-0">
              <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border border-border bg-secondary text-primary">
                <KeyRound className="h-4 w-4" aria-hidden />
              </span>
              <div className="min-w-0">
                <div className="text-sm font-medium">Password</div>
                <p className="text-[12px] text-muted-foreground">
                  We’ll email a one-time link to choose a new password.
                </p>
              </div>
            </div>
            <Button
              variant="outline"
              onClick={sendResetLink}
              disabled={sendingReset}
              className="gap-2 shrink-0"
            >
              {sendingReset ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden /> : <Mail className="h-4 w-4" aria-hidden />}
              {sendingReset ? 'Sending…' : 'Send reset link'}
            </Button>
          </div>
          <div className="flex items-center justify-between gap-3 rounded-lg border border-border px-3.5 py-3 flex-wrap">
            <div className="flex items-center gap-3 min-w-0">
              <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border border-border bg-secondary text-primary">
                <BadgeCheck className="h-4 w-4" aria-hidden />
              </span>
              <div className="min-w-0">
                <div className="text-sm font-medium">Email address</div>
                <p className="truncate text-[12px] text-muted-foreground">{user.email}</p>
              </div>
            </div>
            {emailVerified ? (
              <Badge variant="outline" className="border-emerald-400/40 bg-emerald-400/10 text-emerald-300">
                Verified
              </Badge>
            ) : (
              <Badge variant="outline" className="border-amber-400/40 bg-amber-400/10 text-amber-300">
                Not verified
              </Badge>
            )}
          </div>
        </div>
      </Card>

      {/* data & privacy */}
      <Card className="p-5 sm:p-6">
        <h2 className="flex items-center gap-2 text-[15px] font-semibold">
          <Database className="h-4 w-4 text-primary" aria-hidden />
          Data &amp; privacy
        </h2>
        <p className="mt-1.5 text-[13px] leading-relaxed text-muted-foreground">
          Take a copy of everything we store about you, or refresh what this browser has cached.
        </p>
        <div className="mt-3 flex flex-wrap gap-2">
          <Button variant="outline" onClick={exportData} disabled={exporting} className="gap-2">
            {exporting ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden /> : <Download className="h-4 w-4" aria-hidden />}
            {exporting ? 'Building export…' : 'Export my data'}
          </Button>
          <Button variant="outline" onClick={refreshCachedData} disabled={refreshing} className="gap-2">
            {refreshing ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden /> : <RefreshCw className="h-4 w-4" aria-hidden />}
            {refreshing ? 'Refreshing…' : 'Refresh cached data'}
          </Button>
        </div>
        <p className="mt-2 text-[11.5px] text-muted-foreground">
          The export includes your profile, watchlists, alerts and billing state as a JSON file.
        </p>
      </Card>

      {/* legal */}
      <Card className="p-5 sm:p-6">
        <h2 className="flex items-center gap-2 text-[15px] font-semibold">
          <FileText className="h-4 w-4 text-primary" aria-hidden />
          Legal
        </h2>
        <div className="mt-3 grid gap-2 sm:grid-cols-2">
          <a
            href="/legal/terms"
            target="_blank"
            rel="noopener"
            className="flex items-center justify-between rounded-lg border border-border px-3.5 py-2.5 text-sm transition-colors hover:border-primary/40 hover:bg-surface-hover"
          >
            Terms of Service
            <ExternalLink className="h-3.5 w-3.5 text-muted-foreground" aria-hidden />
          </a>
          <a
            href="/legal/privacy"
            target="_blank"
            rel="noopener"
            className="flex items-center justify-between rounded-lg border border-border px-3.5 py-2.5 text-sm transition-colors hover:border-primary/40 hover:bg-surface-hover"
          >
            Privacy Policy
            <ExternalLink className="h-3.5 w-3.5 text-muted-foreground" aria-hidden />
          </a>
        </div>
        <p className="mt-2.5 text-[11.5px] text-muted-foreground">
          How Dealify handles your data, what we never do with it, and how to reach us.
        </p>
      </Card>

      {/* danger zone */}
      <Card className="border-red-400/30 p-5 sm:p-6">
        <h2 className="flex items-center gap-2 text-[15px] font-semibold text-red-300">
          <ShieldAlert className="h-4 w-4" aria-hidden />
          Danger zone
        </h2>
        <div className="mt-3 flex items-start justify-between gap-4 flex-wrap">
          <div className="min-w-0 max-w-md">
            <div className="text-sm font-semibold">Delete account</div>
            <p className="mt-1 text-[13px] leading-relaxed text-muted-foreground">
              Permanently deletes your account, watchlists, alerts, saved listings, push tokens,
              connected scan engines and profile answers. This cannot be undone and your email
              frees up for anyone to sign up with. Anonymised marketplace research (the listings
              database) is kept — it isn&rsquo;t about you.
            </p>
          </div>
          <Button
            variant="destructive"
            onClick={() => {
              setConfirmText('')
              setDeleteOpen(true)
            }}
            className="gap-2 shrink-0"
          >
            <ShieldAlert className="h-4 w-4" aria-hidden />
            Delete account
          </Button>
        </div>
      </Card>

      {/* typed confirmation — the same pattern as the Privacy Policy promises */}
      <AlertDialog open={deleteOpen} onOpenChange={setDeleteOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete your account?</AlertDialogTitle>
            <AlertDialogDescription asChild>
              <div className="space-y-2">
                <p>
                  This permanently removes{' '}
                  <span className="font-semibold text-foreground">{user.email}</span> and all of
                  its data — watchlists, alerts, saved listings, push tokens, connected scan
                  engines and personalisation answers.
                </p>
                <p className="text-[12.5px]">
                  If your plan is still active there&rsquo;s no need to delete it — cancelling
                  from Billing keeps access until the period you paid for ends.
                </p>
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="space-y-1.5">
            <label htmlFor="delete-confirm" className="text-[13px] font-medium">
              Type <span className="font-mono font-semibold text-red-300">DELETE</span> to confirm
            </label>
            <Input
              id="delete-confirm"
              value={confirmText}
              onChange={(e) => setConfirmText(e.target.value)}
              placeholder="DELETE"
              autoComplete="off"
              disabled={deleting}
            />
          </div>
          <AlertDialogFooter>
