// CDP helper: sign in via #st token, open Settings, screenshot top + bottom.
const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'
const { spawn } = require('node:child_process')
const fs = require('node:fs')
const path = require('node:path')

const token = process.argv[2]
const outDir = process.argv[3] ?? '/tmp'
const width = Number(process.argv[4] ?? 1440)
const height = Number(process.argv[5] ?? 1600)
const port = 9533 + Math.floor(Math.random() * 200)
const profile = path.join('/tmp', `cdp-settings-${port}`)

const chrome = spawn(CHROME, [
  '--headless=new', '--disable-gpu', '--no-first-run', '--hide-scrollbars',
  `--remote-debugging-port=${port}`, `--user-data-dir=${profile}`,
  `--window-size=${width},${height}`, 'about:blank',
], { stdio: 'ignore' })

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

async function main() {
  let targets
  for (let i = 0; i < 60; i++) {
    try {
      targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json()
      if (targets.length) break
    } catch {}
    await sleep(250)
  }
  const page = targets.find((t) => t.type === 'page')
  const ws = new WebSocket(page.webSocketDebuggerUrl)
  let id = 0
  const pending = new Map()
  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data)
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id)
      pending.delete(msg.id)
      msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result)
    }
  }
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const msgID = ++id
    pending.set(msgID, { resolve, reject })
    ws.send(JSON.stringify({ id: msgID, method, params }))
  })
  const evalJs = async (expression) => {
    const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true })
    return r?.result?.value
  }
  const shot = async (name) => {
    const { data } = await send('Page.captureScreenshot', { format: 'png' })
    fs.writeFileSync(path.join(outDir, name), Buffer.from(data, 'base64'))
    console.log('wrote', name)
  }
  await new Promise((r) => { ws.onopen = r })

  await send('Page.enable')
  await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: false })
  await send('Page.navigate', { url: `http://localhost:3001/app#st=${encodeURIComponent(token)}` })
  await sleep(5000)

  const state = await evalJs(`document.body.innerText.slice(0, 160)`)
  console.log('page:', JSON.stringify(state))

  // open account menu, then Settings
  console.log('menu click:', await evalJs(`(() => { const b = document.querySelector('button[aria-label="Account menu"]'); if (!b) return 'no-menu'; b.click(); return 'ok' })()`))
  await sleep(900)
  console.log('settings click:', await evalJs(`(() => { const items = [...document.querySelectorAll('[role="menuitem"]')]; const el = items.find(e => e.textContent.trim() === 'Settings'); if (!el) return 'missing:' + items.map(e=>e.textContent.trim()).join('|'); el.click(); return 'ok' })()`))
  await sleep(2000)

  await evalJs(`document.documentElement.style.scrollBehavior = 'auto'; window.scrollTo(0, 0)`)
  await sleep(600)
  await shot('settings-top.png')

  // scroll to the bottom (danger zone / legal)
  await evalJs(`window.scrollTo(0, document.body.scrollHeight)`)
  await sleep(900)
  await shot('settings-bottom.png')

  ws.close()
  chrome.kill('SIGKILL')
  try { fs.rmSync(profile, { recursive: true, force: true }) } catch {}
  process.exit(0)
}

main().catch((err) => {
  console.error(err)
  chrome.kill('SIGKILL')
  process.exit(1)
})

