  const stats = await getLandingStats().catch(() => null)
  return <OnboardingFunnel initialStats={stats} startAtPersonalisation />
}
--- signup page ---
import { Suspense } from 'react'
import { headers } from 'next/headers'
import { redirect } from 'next/navigation'
import { getAuthUser } from '@/lib/auth'
import { getLandingStats } from '@/lib/landing-stats'
import { isFirebaseAuthEnabled } from '@/lib/firebase/config'
import { ensureFirebaseAuthorizedDomain } from '@/lib/firebase/admin-config'
import { AuthPage } from '@/components/landing/auth-page'

export const dynamic = 'force-dynamic'

/** Account creation / sign-in. Signed-in visitors go straight into the app. */
export default async function SignupPage({
  searchParams,
}: {
  searchParams: Promise<{ mode?: string; personalised?: string }>
}) {
  const [user, stats, headerList, params] = await Promise.all([
    getAuthUser(),
    getLandingStats().catch(() => null),
    headers(),
    searchParams,
  ])
  // An explicit sign-in link should show the sign-in screen, even if this
  // browser has an existing session. The auth page can then let the user
  // choose which account to continue with.
  if (user && params.mode !== 'login' && params.personalised !== '1') redirect('/app')
  // New accounts now go through personalisation first; the account form is
  // deliberately the final step after the visitor tunes their Dealify feed.
  if (!user && params.mode !== 'login' && params.personalised !== '1') redirect('/personalise')

  // Google sign-in only works on domains listed in the Firebase project's
  // authorized domains, and the hosting platform rotates the public subdomain
  // on every container boot. Register the host this page is being served from
  // (trusted *.space-z.ai suffixes only) so the popup is never rejected with
  // auth/unauthorized-domain after a reboot. Best-effort: never blocks render.
  const requestHost =
    headerList.get('x-forwarded-host') ?? headerList.get('host') ?? ''
  const domainCheck = await ensureFirebaseAuthorizedDomain(requestHost)
  if (!domainCheck.ok && domainCheck.reason) {
    console.warn(`[firebase] could not ensure authorized domain "${domainCheck.host}": ${domainCheck.reason}`)
  }

  return (
    <Suspense>
      {/* Google sign-in appears only when the Firebase env config is present */}
      <AuthPage initialStats={stats} googleEnabled={isFirebaseAuthEnabled()} />
    </Suspense>
  )
}
