import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { db } from '@/lib/db'
import {
  createAuthSession,
  hashPassword,
  requestIsHttps,
  applySessionCookie,
} from '@/lib/auth'
import { appPublicOrigin } from '@/lib/app-url'
import { issueEmailVerificationToken } from '@/lib/email-verification'
import { sendVerifyEmail } from '@/lib/email'

const signupSchema = z.object({
  name: z.string().trim().max(80).optional().or(z.literal('')),
  email: z.string().trim().toLowerCase().email('Enter a valid email address'),
  password: z.string().min(8, 'Password must be at least 8 characters').max(200),
})

export async function POST(req: NextRequest) {
  try {
    const body = await req.json().catch(() => ({}))
    const parsed = signupSchema.safeParse(body)
    if (!parsed.success) {
      return NextResponse.json(
        { error: parsed.error.issues[0]?.message ?? 'Invalid sign-up details' },
        { status: 400 }
      )
    }
    const { name, email, password } = parsed.data

    const existing = await db.user.findUnique({ where: { email } })
    if (existing) {
      return NextResponse.json(
        { error: 'An account with that email already exists — sign in instead' },
        { status: 409 }
      )
    }

    const user = await db.user.create({
      data: {
        email,
        name: name && name.length > 0 ? name : null,
        passwordHash: hashPassword(password),
        // NO trial here — the 7-day Pro trial only starts once the email
        // is verified (EmailVerificationToken). Until then the account sits
        // in the locked plan state, so fake accounts gain nothing to abuse.
      },
    })

    const { token, expiresAt } = await createAuthSession(user.id)

    // Verification email — fire-and-forget: a mail hiccup must never block
    // signup (the app shows a confirm-email gate with a resend button).
    // Link origin = APP_URL (request Host is rewritten by hosting proxies).
    void (async () => {
      const verifyUrl = `${appPublicOrigin(req)}/verify-email?token=${await issueEmailVerificationToken(user.id)}`
      await sendVerifyEmail(user.email, verifyUrl)
    })().catch(() => {})

    const res = NextResponse.json({
      user: { id: user.id, email: user.email, name: user.name },
      // Raw session token: the client stores it as a Bearer fallback for
      // embedded-iframe contexts where third-party cookies are blocked.
      token,
    })
    res.headers.append('Cache-Control', 'no-store')
    applySessionCookie(res, token, expiresAt, requestIsHttps(req))
    return res
  } catch (err) {
    console.error('[auth/signup]', err)
    return NextResponse.json({ error: 'Could not create your account. Try again.' }, { status: 500 })
  }
}

