/** Personalization profile — CLIENT-SAFE shared module.
 *
 *  Types, option catalogs and label helpers for the onboarding questionnaire.
 *  NO zod / db imports here so client components (the quiz UI, the feed) can
 *  import the catalogs without dragging server-only code into the bundle.
 *  Validation + scoring live in lib/profile.ts, which re-exports this module.
 */

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

import { getVertical } from '@/lib/verticals'

export type FlipGoal = 'quick_flip' | 'value_hunter' | 'personal' | 'project' | 'other'
export type Experience = 'first' | 'some' | 'pro'
/** body-style keys — matched against listing bodyStyle + title keywords */
export type StyleKey = 'ute' | '4x4' | 'suv' | 'sedan' | 'hatch' | 'wagon' | 'coupe' | 'van' | 'convertible'
export type AvoidKey = 'high_kms' | 'dealer' | 'older' | 'salvage'

export interface UserProfile {
  goal: FlipGoal
  /** flip verticals this user hunts (lib/verticals.ts ids); ['vehicles']
   *  for legacy profiles + car-only flippers */
  verticals: string[]
  /** buy-in window in dollars (0 = no floor) */
  budgetMin: number
  budgetMax: number
  styles: StyleKey[]
  /** favourite makes/brands (per-vertical — Nike, LEGO, Toyota…) — empty means "any" */
  makes: string[]
  /** marketplace city slug (e.g. "sydney", "london") + display name */
  locationSlug: string | null
  locationName: string | null
  /** chosen city coordinates — scans centre their radius search here
   *  (any city on earth; null = legacy profile, scanner falls back) */
  lat: number | null
  lng: number | null
  /** ISO-2 country of the chosen city ("AU", "GB"… display + context) */
  country: string | null
  radiusKm: number
  /** preferred marketplace for the starter radar (lib/marketplaces.ts MarketId);
   *  null = no preference (scanner default applies) */
  preferredMarket: string | null
  avoid: AvoidKey[]
  experience: Experience
  /** free-text goal when goal === 'other' — informational (chips, review) */
  goalNote?: string | null
  /** free-text dealbreakers beyond the fixed scoring hooks — informational */
  avoidNote?: string | null
  /** the watchlist auto-tuned from these answers (id), if one exists */
  starterWatchlistId?: string
}

