export function budgetLabel(p: Pick<UserProfile, 'budgetMin' | 'budgetMax'>): string {
  const fmt = (n: number) => (n >= 1000 ? `$${Math.round(n / 1000)}k` : `$${n}`)
  if (p.budgetMin <= 0 && p.budgetMax >= 500_000) return 'any budget'
  if (p.budgetMin <= 0) return `under ${fmt(p.budgetMax)}`
  if (p.budgetMax >= 500_000) return `${fmt(p.budgetMin)}+`
  return `${fmt(p.budgetMin)}–${fmt(p.budgetMax)}`
}

/** `StyleKey` keeps autocomplete for the known keys; the `& {}` intersection
 *  also accepts raw strings (stored profiles are plain JSON) — unknown values
 *  fall through to the key itself in the lookup below. */
export function styleLabel(key: StyleKey | (string & {})): string {
  return STYLE_OPTIONS.find((s) => s.key === key)?.label ?? key
}

export function avoidLabel(key: AvoidKey): string {
  return AVOID_OPTIONS.find((a) => a.key === key)?.label ?? key
}

export function experienceLabel(key: Experience): string {
  return EXPERIENCE_OPTIONS.find((e) => e.key === key)?.label ?? key
}

export function goalLabel(key: FlipGoal): string {
  return GOAL_OPTIONS.find((g) => g.key === key)?.label ?? key
}

/** One-line profile summary for the feed strip, e.g.
 *  "Toyota & Mazda · utes, SUVs · $5k–$15k · Sydney · 60 km".
 *  Structural input — the client's UserProfileInfo passes without dragging
 *  the server-only zod types into client bundles. */
export interface ProfileSummaryInput {
  makes: string[]
  styles: string[]
  budgetMin: number
  budgetMax: number
  locationName: string | null
  radiusKm: number
  verticals?: string[]
}
export function profileSummaryLine(p: ProfileSummaryInput): string {
  const parts: string[] = []
  // verticals first when the profile hunts beyond cars
  const vs = (p.verticals ?? []).filter((v) => v !== 'vehicles')
  if (vs.length > 0 && (p.verticals ?? []).includes('vehicles')) {
    parts.push('Cars + ' + vs.length + ' more categor' + (vs.length === 1 ? 'y' : 'ies'))
  } else if (vs.length > 0) {
    parts.push(vs.slice(0, 3).map((v) => getVertical(v).short).join(', '))
  }
  parts.push(p.makes.length ? p.makes.slice(0, 3).join(', ') + (p.makes.length > 3 ? ` +${p.makes.length - 3}` : '') : 'Any brand')
  if (p.styles.length) parts.push(p.styles.slice(0, 3).map((s) => styleLabel(s as StyleKey).toLowerCase()).join(', ') + (p.styles.length > 3 ? '…' : ''))
  parts.push(budgetLabel(p))
  if (p.locationName) parts.push(`${p.locationName} · ${p.radiusKm} km`)
  return parts.join(' · ')
}

