input.content:
'use client'

/**
 * Onboarding funnel — the site's new front door (replaces the marketing
 * landing page).
 *
 * Visitors enter straight into a guided flow:
 *   1. three benefit screens (what Dealify does, the live flip-stories reel,
 *      instant alerts) — no account needed to watch;
 *   2. eight personalisation prompts — the same questions the in-app quiz
 *      asks, asked up-front so the app is tuned before the first visit
 *      (this is the "valuable personalisable data" that powers the starter
 *      watchlist, the For-you feed ranking and the app's tone);
 *   3. a review screen that shows the assembled radar;
 *   4. account creation — starts the 7-day free trial on Pro,
 *      no credit card required. When the trial ends the app locks until a
 *      paid plan is chosen (paywall).
 *
 * Skippable steps stay skippable; anyone who bails on the prompts can still
 * create an account and gets the in-app questionnaire as the fallback.
 *
 * UX details that make this feel like a product, not a form:
 *   - three-phase rail (preview → personalise → account) + segmented progress
 *   - answers and the current step persist in localStorage, so a refresh or a
 *     closed tab never loses progress ("Progress saved" in the header)
 *   - a live radar preview that reacts to every answer, with jump-to-edit rows
 *   - a review step before the account handoff
 *   - Enter advances, Escape-free back navigation, reduced-motion-safe motion
 */

import { useEffect, useMemo, useRef, useState } from 'react'
import { AnimatePresence, motion } from 'framer-motion'
import {
  ArrowLeft, ArrowRight, Bell, BellRing, CalendarClock, Check, CheckCircle2,
  ChevronRight, CircleDollarSign, Clock3, Gauge, Heart, Home, Layers, Loader2,
  MapPin, Pencil, Plus, Radar, Search, ShieldCheck, Sparkles, Store, Target,
  Timer, TrendingUp, Wallet, Wrench, X, Zap, type LucideIcon,
} from 'lucide-react'
import {
  AVOID_OPTIONS, BUDGET_OPTIONS, EXPERIENCE_OPTIONS, GOAL_OPTIONS, MAKE_OPTIONS,
  RADIUS_OPTIONS, STYLE_OPTIONS,
  type AvoidKey, type Experience, type FlipGoal, type StyleKey, type UserProfile,
} from '@/lib/profile-shared'
import { BRAND_SUGGESTIONS, PICKER_VERTICALS, getVertical } from '@/lib/verticals'
import { MARKET_META, marketSupportsCountry, normalizeMarket } from '@/lib/marketplaces'
import { MarketDropdown } from '@/components/market-dropdown'
import { CITY_BY_SLUG, type WorldCity } from '@/lib/world-cities'
import { api, formatPrice, hasAccountMarker } from '@/lib/api'
import type { LandingStats } from '@/lib/landing-stats'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Progress } from '@/components/ui/progress'
import { FlipStoriesPlayer } from '@/components/signup/flip-stories'

const GOAL_ICONS = { zap: Zap, trending: TrendingUp, heart: Heart, wrench: Wrench, sparkles: Sparkles } as const

/** Per-goal icon tints — gives the first question colour variety, matching
 *  the in-app quiz so both halves of personalisation feel like one product. */
const GOAL_TINT: Record<keyof typeof GOAL_ICONS, string> = {
  zap: 'from-amber-400/25 to-orange-500/10 text-amber-300',
  trending: 'from-emerald-400/25 to-green-500/10 text-emerald-300',
  heart: 'from-rose-400/25 to-pink-500/10 text-rose-300',
  wrench: 'from-sky-400/25 to-blue-500/10 text-sky-300',
  sparkles: 'from-violet-400/25 to-purple-500/10 text-violet-300',
}

/** Per-vertical icon-tile tints — same hues as the in-app quiz's market wall. */
const VERT_TINT: Record<string, string> = {
  vehicles: 'from-amber-400/25 to-orange-500/10 text-amber-300',
  electronics: 'from-sky-400/25 to-blue-500/10 text-sky-300',
  furniture: 'from-rose-400/25 to-pink-500/10 text-rose-300',
  fashion: 'from-fuchsia-400/25 to-purple-500/10 text-fuchsia-300',
  collectibles: 'from-violet-400/25 to-indigo-500/10 text-violet-300',
  bikes: 'from-teal-400/25 to-cyan-500/10 text-teal-300',
  gaming: 'from-indigo-400/25 to-violet-500/10 text-indigo-300',
  appliances: 'from-emerald-400/25 to-green-500/10 text-emerald-300',
  tools: 'from-yellow-400/25 to-amber-500/10 text-yellow-300',
  other: 'from-slate-400/25 to-zinc-500/10 text-slate-300',
}

/** Category picker list — the nine specific markets plus the “Other”
 *  escape hatch, which the user explicitly asked for. */
const CATEGORY_CHOICES = [...PICKER_VERTICALS, getVertical('other')]
const PENDING_PROFILE_KEY = 'dealify.pending-signup-profile.v1'
const DRAFT_KEY = 'dealify.personalise-draft.v2'

/** Copy under each goal card — tells the user what the answer actually changes. */
const GOAL_WEIGHT_COPY: Record<FlipGoal, string> = {
  quick_flip: 'We’ll favour fast-moving listings with strong turnover and clean margins.',
  value_hunter: 'We’ll wait for the outliers — the few listings with serious upside.',
  personal: 'We’ll score the things you actually want to keep, not just pure profit.',
  project: 'We’ll surface fixer-uppers where the work still leaves room for profit.',
  other: 'We’ll tune the feed around your own description of a good flip.',
}

/** Short descriptors for the budget presets. */
const BUDGET_BLURB: Record<string, string> = {
  b1: 'Weekend flips',
  b1k5: 'Everyday finds',
  b5: 'Under five grand',
  b15: 'Serious inventory',
  b30: 'High-ticket stock',
  b60: 'Premium inventory',
  b60plus: 'Anything goes',
  custom: 'Set your own range',
}

const QUICK_CITIES: WorldCity[] = ['sydney', 'melbourne', 'brisbane', 'london', 'newyork', 'losangeles', 'toronto']
  .map((slug) => CITY_BY_SLUG.get(slug))
  .filter((city): city is WorldCity => Boolean(city))

const POPULAR_CATEGORIES = new Set(['vehicles', 'electronics'])

const SAMPLE_DEALS = [
  { emoji: '🚗', title: '2013 Audi A4', meta: 'Sydney · 12 km', price: 4990, currency: 'AUD', roi: 38, vertical: 'vehicles' },
  { emoji: '👟', title: 'Nike Dunk Low', meta: 'Melbourne · 8 km', price: 120, currency: 'AUD', roi: 52, vertical: 'fashion' },
  { emoji: '🎮', title: 'PS5 + 2 games', meta: 'Brisbane · 20 km', price: 380, currency: 'AUD', roi: 31, vertical: 'gaming' },
]

/* ------------------------------ wizard state ------------------------------ */

interface Answers {
  goal: FlipGoal | null
  /** flip verticals (lib/verticals.ts ids) — drives which questions follow */
  verticals: string[]
  budgetKey: string | null
  customMin: string
  customMax: string
  styles: StyleKey[]
  makes: string[]
  locationSlug: string | null
  locationName: string | null
  lat: number | null
  lng: number | null
  country: string | null
  radiusKm: number
  /** preferred marketplace for the starter radar (MarketId) — null = no preference */
  preferredMarket: string | null
  avoid: AvoidKey[]
  experience: Experience | null
  /** free-text wording for the "Something else" goal pick */
  goalNote: string
  /** free-text dealbreakers beyond the fixed scoring hooks */
  avoidNote: string
}

const DEFAULT_ANSWERS: Answers = {
  goal: null,
  verticals: [],
  budgetKey: null,
  customMin: '',
  customMax: '',
  styles: [],
  makes: [],
  // no auto-city — the visitor picks their own patch (or "Anywhere")
  locationSlug: null,
  locationName: null,
  lat: null,
  lng: null,
  country: null,
  radiusKm: 60,
  preferredMarket: null,
  avoid: [],
  experience: null,
  goalNote: '',
  avoidNote: '',
}

type StepId =
  | 'benefit-scan' | 'benefit-stories' | 'benefit-alerts'
  | 'goal' | 'categories' | 'budget' | 'styles' | 'makes' | 'location' | 'avoid' | 'experience'
  | 'review' | 'account'

const STEPS: Array<{ id: StepId; optional?: boolean }> = [
  { id: 'benefit-scan' },
  { id: 'benefit-stories' },
  { id: 'benefit-alerts' },
  { id: 'goal' },
  { id: 'categories' },
  { id: 'budget' },
  { id: 'styles', optional: true },
  { id: 'makes', optional: true },
  { id: 'location', optional: true },
  { id: 'avoid', optional: true },
  { id: 'experience' },
  { id: 'review' },
  { id: 'account' },
]

const PROMPT_IDS = new Set<StepId>(['goal', 'categories', 'budget', 'styles', 'makes', 'location', 'avoid', 'experience'])

const STEP_LABELS: Record<StepId, string> = {
  'benefit-scan': 'How it works',
  'benefit-stories': 'Live proof',
  'benefit-alerts': 'Instant alerts',
  goal: 'Your goal',
  categories: 'Your markets',
  budget: 'Your budget',
  styles: 'Body styles',
  makes: 'Favourite brands',
  location: 'Hunting ground',
  avoid: 'Dealbreakers',
  experience: 'Experience',
  review: 'Review',
  account: 'Create account',
}

const PHASES: Array<{ label: string; short: string }> = [
  { label: 'See the edge', short: 'Preview' },
  { label: 'Tune your radar', short: 'Personalise' },
  { label: 'Create account', short: 'Account' },
]

function phaseIndex(id: StepId): 0 | 1 | 2 {
  if (id.startsWith('benefit')) return 0
  if (id === 'account') return 2
  return 1
}

/** Assemble the profile payload from wizard answers — null when incomplete. */
function buildProfile(a: Answers): UserProfile | null {
  if (!a.goal || !a.experience) return null
  let budgetMin = 0
  let budgetMax = 500_000
  if (a.budgetKey === 'custom') {
    budgetMin = Math.max(0, parseInt(a.customMin || '0', 10) || 0)
    budgetMax = parseInt(a.customMax || '0', 10) || 0
    if (budgetMax <= 0 || budgetMin > budgetMax) return null
  } else {
    const preset = BUDGET_OPTIONS.find((b) => b.key === a.budgetKey)
    if (!preset) return null
    budgetMin = preset.min
    budgetMax = preset.max
  }
  return {
    goal: a.goal,
    verticals: a.verticals.length > 0 ? a.verticals : ['vehicles'],
    budgetMin,
    budgetMax,
    styles: a.verticals.includes('vehicles') ? a.styles : [],
    makes: a.makes,
    locationSlug: a.locationSlug,
    locationName: a.locationName,
    lat: a.lat,
    lng: a.lng,
    country: a.country,
    radiusKm: a.radiusKm,
    preferredMarket: a.preferredMarket,
    avoid: a.avoid,
    experience: a.experience,
    goalNote: a.goalNote.trim() ? a.goalNote.trim().slice(0, 120) : null,
    avoidNote: a.avoidNote.trim() ? a.avoidNote.trim().slice(0, 120) : null,
  }
}

const fmtInt = (n: number) => new Intl.NumberFormat('en-AU').format(n)

/** Budget label used in the preview/review/account recap. */
function budgetText(a: Answers): string {
  if (!a.budgetKey) return 'Choose a budget'
  if (a.budgetKey === 'custom') {
    if (!a.customMax) return 'Set a custom range'
    return `${formatPrice(parseInt(a.customMin || '0', 10) || 0)} – ${formatPrice(parseInt(a.customMax, 10) || 0)}`
  }
  return BUDGET_OPTIONS.find((b) => b.key === a.budgetKey)?.label ?? 'Choose a budget'
}

/** A believable (deterministic) match estimate so the preview feels alive. */
function estimateMatches(a: Answers, stats: LandingStats | null): number {
  const base = Math.max(18, Math.round((stats?.goodDealsLive ?? 130) / 2.4))
  const categoryFactor = a.verticals.length ? Math.min(3.2, 0.85 + a.verticals.length * 0.42) : 1
  const budgetFactor = a.budgetKey ? 1.15 : 1
  const locationFactor = a.locationName ? 1 : 0.68
  const makeFactor = a.makes.length ? 1.08 : 1
  return Math.round(base * categoryFactor * budgetFactor * locationFactor * makeFactor)
}

interface PreviewDeal {
  emoji: string
  title: string
  meta: string
  price: number
  currency: string
  roi: number | null
  vertical: string
}

function previewDeals(stats: LandingStats | null, verticals: string[]): PreviewDeal[] {
  const live = (stats?.topDeals ?? []).map((deal) => ({
    emoji: getVertical(deal.vertical).emoji,
    title: [deal.year, deal.make, deal.model].filter(Boolean).join(' ') || deal.title,
    meta: [deal.city, deal.state].filter(Boolean).join(', ') || 'Live marketplace',
    price: deal.price,
    currency: deal.currency,
    roi: deal.roiPct,
    vertical: deal.vertical,
  }))
  const pool = live.length > 0 ? live : SAMPLE_DEALS
  const filtered = verticals.length > 0 ? pool.filter((deal) => verticals.includes(deal.vertical)) : pool
  return (filtered.length > 0 ? filtered : pool).slice(0, 3)
}

/* -------------------------------- component ------------------------------- */

export function OnboardingFunnel({
  initialStats = null,
  startAtPersonalisation = false,
}: {
  initialStats?: LandingStats | null
  startAtPersonalisation?: boolean
}) {
  const [step, setStep] = useState(0)
  const [dir, setDir] = useState<1 | -1>(1)
  const [answers, setAnswers] = useState<Answers>(DEFAULT_ANSWERS)
  const [restored, setRestored] = useState(false)
  const mainRef = useRef<HTMLElement>(null)
  const headingRef = useRef<HTMLDivElement>(null)

  // Returning visitors to the public landing funnel go straight into the
  // app. The explicit /personalise route is a signup path, so it stays open
  // even when another account is signed in; signup will replace that session
  // after the visitor finishes tuning their new profile.
  useEffect(() => {
    let cancelled = false
    api.auth
      .me()
      .then((r) => {
        if (cancelled) return
        if (r.user && !startAtPersonalisation) window.location.replace('/app')
        else if (!startAtPersonalisation && hasAccountMarker()) window.location.replace('/signup?mode=login')
      })
      .catch(() => {})
    return () => {
      cancelled = true
    }
  }, [startAtPersonalisation])

  // Restore a saved draft once, after mount (localStorage is client-only).
  useEffect(() => {
    try {
      const raw = window.localStorage.getItem(DRAFT_KEY)
      if (raw) {
        const parsed = JSON.parse(raw) as { answers?: Partial<Answers>; step?: number }
        if (parsed?.answers && typeof parsed.answers === 'object') {
          setAnswers({ ...DEFAULT_ANSWERS, ...parsed.answers })
        }
        if (typeof parsed.step === 'number' && parsed.step >= 0 && parsed.step < STEPS.length) {
          setStep(parsed.step)
        }
      }
    } catch {
      // corrupt/blocked storage — start fresh
    }
    setRestored(true)
  }, [])

  // Persist answers + the current step so a refresh never loses progress.
  useEffect(() => {
    if (!restored) return
    try {
      window.localStorage.setItem(DRAFT_KEY, JSON.stringify({ answers, step }))
    } catch {
      // storage blocked (private mode / sandboxed iframe) — the flow still works
    }
  }, [answers, step, restored])

  const update = (patch: Partial<Answers>) =>
    setAnswers((a) => {
      const locationChanged = (['lat', 'lng', 'country'] as const).some(
        (key) => key in patch && patch[key] !== a[key]
      )
      return {
        ...a,
        ...patch,
        ...(locationChanged ? { preferredMarket: null } : {}),
      }
    })

  /** Steps that actually apply — the body-styles question is car-only, so it
   *  only exists when Cars is one of the picked categories (the user asked
   *  for questions that follow from each other, not a fixed car gauntlet). */
  const steps = useMemo(
    () => STEPS.filter((s) => s.id !== 'styles' || answers.verticals.includes('vehicles')),
    [answers.verticals]
  )
  const currentStep = Math.min(step, steps.length - 1)
  const stepDef = steps[currentStep]
  const total = steps.length
  const phase = phaseIndex(stepDef.id)
  const isPrompt = PROMPT_IDS.has(stepDef.id)
  const isReview = stepDef.id === 'review'
  const isAccount = stepDef.id === 'account'
  const showPreview = isPrompt

  const totalQuestions = useMemo(() => steps.filter((s) => PROMPT_IDS.has(s.id)).length, [steps])
  const questionsBefore = useMemo(
    () => steps.slice(0, currentStep).filter((s) => PROMPT_IDS.has(s.id)).length,
    [steps, currentStep]
  )
  const questionNumber = questionsBefore + 1
  const minutesLeft = Math.max(1, Math.ceil(((totalQuestions - questionsBefore) * 0.35)))

  // Keep the step index inside bounds if the visible list shrank (e.g. the
  // user removed Cars while further ahead — only possible via review edits).
  useEffect(() => {
    if (step > steps.length - 1) setStep(steps.length - 1)
  }, [steps.length, step])

  // Every new step starts at the top of its own scroll area.
  useEffect(() => {
    mainRef.current?.scrollTo({ top: 0 })
  }, [currentStep])

  const canContinue = useMemo(() => {
    switch (stepDef.id) {
      case 'goal':
        return answers.goal != null
      case 'categories':
        return answers.verticals.length > 0
      case 'budget': {
        if (answers.budgetKey == null) return false
        if (answers.budgetKey === 'custom') {
          const min = parseInt(answers.customMin || '0', 10) || 0
          const max = parseInt(answers.customMax || '0', 10) || 0
          return max > 0 && min <= max
        }
        return true
      }
      case 'experience':
        return answers.experience != null
      default:
        return true
    }
  }, [stepDef.id, answers])

  const blockedHint = useMemo(() => {
    if (canContinue) return ''
    switch (stepDef.id) {
      case 'goal':
        return 'Pick the goal that fits you best to continue.'
      case 'categories':
        return 'Choose at least one category to continue.'
      case 'budget':
        return answers.budgetKey === 'custom'
          ? 'Set a maximum higher than your minimum to continue.'
          : 'Pick a budget to continue.'
      case 'experience':
        return 'Pick your experience level to continue.'
      default:
        return ''
    }
  }, [canContinue, stepDef.id, answers.budgetKey])

  function go(delta: 1 | -1) {
    const next = Math.min(total - 1, Math.max(0, currentStep + delta))
    if (next === currentStep) return
    setDir(delta)
    setStep(next)
  }

  function jumpTo(id: StepId) {
    const index = steps.findIndex((s) => s.id === id)
    if (index < 0 || index === currentStep) return
    setDir(index > currentStep ? 1 : -1)
    setStep(index)
  }

  function resetAll() {
    setAnswers(DEFAULT_ANSWERS)
    setStep(0)
    setDir(1)
    try {
      window.localStorage.removeItem(DRAFT_KEY)
    } catch {
      // best-effort
    }
  }

  /** Wheel forwarding — the page scrolls inside <main> only; wheeling over
   *  the header, progress strip or action bar used to be a dead zone (body
   *  is overflow-hidden). Forward those gestures to main so the whole page
   *  feels scrollable, not just the middle band. */
  function handlePageWheel(e: React.WheelEvent) {
    const m = mainRef.current
    if (!m) return
    if (m.contains(e.target as Node)) return // native scrolling owns this region
    if (m.scrollHeight <= m.clientHeight) return // content fits — nothing to scroll
    m.scrollTop += e.deltaY
  }

  /** Enter advances from anywhere that isn't a text field or a button. */
  function handleKeyDown(e: React.KeyboardEvent) {
    if (e.key !== 'Enter' || e.shiftKey) return
    const tag = (e.target as HTMLElement)?.tagName
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || tag === 'BUTTON' || tag === 'A') return
    if (!canContinue || isAccount) return
    e.preventDefault()
    go(1)
  }

  const continueLabel = (() => {
    switch (stepDef.id) {
      case 'benefit-scan':
        return 'See the proof'
      case 'benefit-stories':
        return 'Next: instant alerts'
      case 'benefit-alerts':
        return 'Tune my radar'
      case 'review':
        return 'Create my account'
      default:
        return 'Continue'
    }
  })()

  const hasDraft =
    restored &&
    Boolean(answers.goal || answers.verticals.length || answers.budgetKey || answers.locationName || answers.experience)

  return (
    <div
      className="personalise-funnel relative flex h-[100dvh] flex-col overflow-hidden"
      onWheel={handlePageWheel}
      onKeyDown={handleKeyDown}
    >
      <div aria-hidden className="personalise-glow personalise-glow-blue pointer-events-none absolute -left-40 -top-48 h-[34rem] w-[34rem] rounded-full" />
      <div aria-hidden className="personalise-glow personalise-glow-orange pointer-events-none absolute -bottom-64 -right-40 h-[38rem] w-[38rem] rounded-full" />
      <div aria-hidden className="grain-overlay pointer-events-none absolute inset-0" />

      {/* header — brand, three-phase rail, saved state, sign-in */}
      <header className="personalise-header relative z-10 flex items-center justify-between gap-3 px-4 py-3 sm:px-6 sm:py-4">
        <div className="flex min-w-0 items-center gap-2.5">
          <a href="/" aria-label="Dealify home" className="shrink-0">
            <img src="/logo.png" alt="Dealify" className="h-9 w-auto" />
          </a>
          <span className="hidden text-[10px] text-muted-foreground xl:block">Marketplace deal sniper</span>
        </div>

        {/* phase rail */}
        <div className="hidden items-center gap-1.5 md:flex" aria-label="Onboarding progress">
          {PHASES.map((p, i) => {
            const done = i < phase
            const active = i === phase
            return (
              <div key={p.label} className="flex items-center gap-1.5">
                <span
                  className={cn(
                    'flex h-6 w-6 items-center justify-center rounded-full border text-[10px] font-bold transition-colors',
                    done
                      ? 'border-primary/50 bg-primary/15 text-primary'
                      : active
                        ? 'border-primary bg-primary text-primary-foreground shadow-[0_0_18px_-6px] shadow-primary/70'
                        : 'border-white/10 bg-white/[0.03] text-white/35'
                  )}
                  aria-hidden
                >
                  {done ? <Check className="h-3 w-3" strokeWidth={3} /> : i + 1}
                </span>
                <span
                  className={cn(
                    'text-[11px] font-semibold transition-colors',
                    active ? 'text-foreground' : done ? 'text-muted-foreground' : 'text-white/35'
                  )}
                >
                  {p.label}
                </span>
                {i < PHASES.length - 1 && (
                  <span aria-hidden className={cn('mx-1 h-px w-6', done ? 'bg-primary/40' : 'bg-white/10')} />
                )}
              </div>
            )
          })}
        </div>

        <div className="flex shrink-0 items-center gap-2">
          {hasDraft && (
            <span className="hidden items-center gap-1.5 rounded-full border border-emerald-500/25 bg-emerald-500/10 px-2.5 py-1 text-[10px] font-semibold text-emerald-200 sm:inline-flex">
              <CheckCircle2 className="h-3 w-3" aria-hidden />
              Progress saved
            </span>
          )}
          {!isAccount && !isReview && (
            <button
              type="button"
              onClick={() => jumpTo('account')}
              className="hidden rounded-full px-2.5 py-1.5 text-[11px] font-medium text-muted-foreground transition-colors hover:text-foreground sm:block"
            >
              Skip setup
            </button>
          )}
          <a
            href="/signup?mode=login"
            className="rounded-full border border-border bg-card/60 px-3.5 py-1.5 text-xs font-medium text-muted-foreground backdrop-blur transition-colors hover:text-foreground"
          >
            <span className="hidden sm:inline">Already have an account? </span>
            <span className="text-primary">Sign in</span>
          </a>
        </div>
      </header>

      {/* progress — phase, step name, question counter, segmented bar */}
      <div className="personalise-progress relative z-10 mx-auto mt-3 w-full max-w-6xl px-4 sm:px-6">
        <div className="mb-2 flex items-center justify-between gap-3 text-[10px] font-semibold uppercase tracking-[.16em] text-muted-foreground">
          <span className="flex min-w-0 items-center gap-2">
            <span className="text-primary">{PHASES[phase].short}</span>
            <span aria-hidden className="h-1 w-1 rounded-full bg-white/20" />
            <span className="truncate text-foreground/75">{STEP_LABELS[stepDef.id]}</span>
          </span>
          <span className="flex shrink-0 items-center gap-2 text-foreground/75">
            {isPrompt ? (
              <>
                <span className="tabular-nums">{questionNumber} / {totalQuestions}</span>
                <span aria-hidden className="hidden h-1 w-1 rounded-full bg-white/20 sm:block" />
                <span className="hidden items-center gap-1 sm:flex">
                  <Clock3 className="h-3 w-3" aria-hidden /> ~{minutesLeft} min left
                </span>
              </>
            ) : isReview ? (
              'Review'
            ) : isAccount ? (
              'Final step'
            ) : (
              `${currentStep + 1} / ${total}`
            )}
          </span>
        </div>
        <div className="flex gap-1" aria-hidden>
          {steps.map((s, i) => (
            <span
              key={s.id}
              className={cn(
                'h-1.5 flex-1 rounded-full transition-colors duration-300',
                i < currentStep
                  ? 'bg-primary/70'
                  : i === currentStep
                    ? 'bg-gradient-to-r from-primary via-orange-400 to-blue-400 shadow-[0_0_14px_-4px] shadow-primary/70'
                    : 'bg-white/[0.08]'
              )}
            />
          ))}
        </div>
        <p className="sr-only" aria-live="polite">
          {isPrompt
            ? `Question ${questionNumber} of ${totalQuestions}: ${STEP_LABELS[stepDef.id]}`
            : `${PHASES[phase].label}: ${STEP_LABELS[stepDef.id]}`}
        </p>
      </div>

      {/* content */}
      <main ref={mainRef} className="relative z-10 min-h-0 flex-1 overflow-y-auto">
        <div
          className={cn(
            'mx-auto w-full px-4 pb-8 sm:px-6',
            stepDef.id === 'benefit-stories'
              ? 'max-w-2xl'
              : stepDef.id === 'benefit-scan' || stepDef.id === 'benefit-alerts'
                ? 'max-w-5xl'
                : isAccount
                  ? 'max-w-3xl'
                  : isReview
                    ? 'max-w-4xl'
                    : 'max-w-6xl'
          )}
        >
          <div className={cn(showPreview && 'personalise-layout')}>
            <AnimatePresence mode="wait" custom={dir} initial={false}>
              <motion.div
                key={stepDef.id}
                custom={dir}
                variants={{
                  enter: (d: 1 | -1) => ({ opacity: 0, x: 20 * d, y: 6 }),
                  center: { opacity: 1, x: 0, y: 0 },
                  exit: (d: 1 | -1) => ({ opacity: 0, x: -20 * d, y: -4 }),
                }}
                initial="enter"
                animate="center"
                exit="exit"
                transition={{ duration: 0.28, ease: [0.22, 1, 0.36, 1] }}
                className={cn(
                  'pt-4 sm:pt-6',
                  (isPrompt || isReview || isAccount) && 'personalise-step-shell rounded-[28px] border p-5 sm:p-7 lg:p-8'
                )}
              >
                <div ref={headingRef} />
                <StepBody
                  id={stepDef.id}
                  answers={answers}
                  update={update}
                  stats={initialStats}
                  onEdit={jumpTo}
                  onReset={resetAll}
                />
              </motion.div>
            </AnimatePresence>
            {showPreview && (
              <PersonalisationPreview answers={answers} stats={initialStats} onEdit={jumpTo} />
            )}
          </div>
        </div>
      </main>

      {/* action bar — the account handoff has its own primary action in the panel */}
      {!isAccount && (
        <footer className="personalise-footer relative z-10 border-t px-4 pb-[max(0.75rem,env(safe-area-inset-bottom))] pt-3 sm:px-6">
          <div className={cn('mx-auto w-full', isPrompt ? 'personalise-layout max-w-6xl' : 'max-w-xl')}>
            <div className="flex w-full items-center gap-2.5">
              {currentStep > 0 ? (
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  onClick={() => go(-1)}
                  aria-label="Back"
                  className="h-11 w-11 shrink-0 rounded-full"
                >
                  <ArrowLeft className="h-4.5 w-4.5" aria-hidden />
                </Button>
              ) : (
                <a
                  href="/"
                  aria-label="Back to the homepage"
                  className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-white/[0.04] hover:text-foreground"
                >
                  <Home className="h-4.5 w-4.5" aria-hidden />
                </a>
              )}

              {stepDef.optional && (
                <button
                  type="button"
                  onClick={() => go(1)}
                  className="ml-auto mr-1 rounded-full px-3 py-2 text-xs text-muted-foreground transition-colors hover:text-foreground"
                >
                  Skip
                </button>
              )}

              <Button
                type="button"
                size="lg"
                disabled={!canContinue}
                onClick={() => go(1)}
                className={cn(
                  'dealify-cta h-12 flex-1 rounded-xl text-[15px] font-bold',
                  !stepDef.optional && 'ml-auto'
                )}
              >
                {continueLabel}
                {stepDef.id === 'benefit-alerts' ? (
                  <Sparkles className="ml-1.5 h-4 w-4" aria-hidden />
                ) : stepDef.id === 'review' ? (
                  <ChevronRight className="ml-1 h-4 w-4" aria-hidden />
                ) : (
                  <ArrowRight className="ml-1.5 h-4 w-4" aria-hidden />
                )}
              </Button>
            </div>

            {blockedHint && (
              <p className="mt-2 text-center text-[11px] text-muted-foreground lg:hidden" aria-live="polite">
                {blockedHint}
              </p>
            )}
            <BlueprintLine answers={answers} />
          </div>
        </footer>
      )}
    </div>
  )
}

/* -------------------------------- step body ------------------------------- */

function StepBody({
  id,
  answers,
  update,
  stats,
  onEdit,
  onReset,
}: {
  id: StepId
  answers: Answers
  update: (patch: Partial<Answers>) => void
  stats: LandingStats | null
  onEdit: (id: StepId) => void
  onReset: () => void
}) {
  switch (id) {
    case 'benefit-scan':
      return <BenefitScan stats={stats} />
    case 'benefit-stories':
      return <BenefitStories stats={stats} />
    case 'benefit-alerts':
      return <BenefitAlerts />
    case 'goal':
      return <GoalStep answers={answers} update={update} />
    case 'categories':
      return <CategoriesStep answers={answers} update={update} />
    case 'budget':
      return <BudgetStep answers={answers} update={update} />
    case 'styles':
      return <StylesStep answers={answers} update={update} />
    case 'makes':
      return <MakesStep answers={answers} update={update} />
    case 'location':
      return <LocationStep answers={answers} update={update} />
    case 'avoid':
      return <AvoidStep answers={answers} update={update} />
    case 'experience':
      return <ExperienceStep answers={answers} update={update} />
    case 'review':
      return <ReviewStep answers={answers} onEdit={onEdit} onReset={onReset} />
    case 'account':
      return <AccountStep answers={answers} />
  }
}

