    </div>
  )
}

function BlueprintLine({ answers }: { answers: Answers }) {
  const parts: string[] = []
  if (answers.verticals.length) {
    parts.push(`${answers.verticals.length} categor${answers.verticals.length === 1 ? 'y' : 'ies'}`)
  }
  if (answers.budgetKey) parts.push(budgetText(answers))
  if (answers.locationName) parts.push(answers.locationName)
  if (parts.length === 0) return null
  return (
    <p className="mt-2 flex items-center justify-center gap-1.5 text-[10.5px] text-muted-foreground lg:hidden">
      <Radar className="h-3 w-3 text-primary" aria-hidden />
      Your radar: {parts.join(' · ')}
    </p>
  )
}

function PreviewDealRow({ deal }: { deal: PreviewDeal }) {
  return (
    <div className="flex items-center gap-2 rounded-xl border border-white/[0.06] bg-white/[0.025] px-2.5 py-2">
      <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg bg-white/[0.04] text-sm" aria-hidden>
        {deal.emoji}
      </span>
      <span className="min-w-0 flex-1">
        <span className="block truncate text-[10.5px] font-semibold text-white/85">{deal.title}</span>
        <span className="block truncate text-[9px] text-white/40">{deal.meta}</span>
      </span>
      <span className="shrink-0 text-right">
        <span className="block text-[10.5px] font-semibold tabular-nums text-white/85">{formatPrice(deal.price, deal.currency)}</span>
        {deal.roi != null && deal.roi > 0 && (
          <span className="block text-[8.5px] font-semibold tabular-nums text-blue-200">+{Math.round(deal.roi)}% ROI</span>
        )}
      </span>
    </div>
  )
}

/* ------------------------------ live preview ------------------------------ */

function PersonalisationPreview({
  answers,
  stats,
  onEdit,
}: {
  answers: Answers
  stats: LandingStats | null
  onEdit: (id: StepId) => void
}) {
  const goal = GOAL_OPTIONS.find((option) => option.key === answers.goal)?.label ?? 'Choose your goal'
  const categories = answers.verticals
    .map((id) => getVertical(id)?.label)
    .filter((label): label is string => Boolean(label))
  const location = answers.locationName ? `${answers.locationName} · ${answers.radiusKm} km` : 'Anywhere'
  const brands = answers.makes.length
    ? `${answers.makes.slice(0, 2).join(', ')}${answers.makes.length > 2 ? ` +${answers.makes.length - 2}` : ''}`
    : 'Any brand'
  const experience = answers.experience
    ? EXPERIENCE_OPTIONS.find((option) => option.key === answers.experience)?.label
    : null
  const dealbreakers = answers.avoid.length + (answers.avoidNote.trim() ? 1 : 0)
  const preferences = [brands, experience, dealbreakers ? `${dealbreakers} dealbreaker${dealbreakers === 1 ? '' : 's'}` : null]
    .filter(Boolean)
    .join(' · ')
  const market = answers.preferredMarket
    ? MARKET_META[normalizeMarket(answers.preferredMarket)].label
    : 'Best available'
  const matches = estimateMatches(answers, stats)
  const deals = previewDeals(stats, answers.verticals)
  const orbit = answers.verticals.slice(0, 5).map((id) => getVertical(id).emoji)
  const orbitPositions = [
    { left: '14%', top: '18%' },
    { left: '72%', top: '14%' },
    { left: '84%', top: '56%' },
    { left: '54%', top: '82%' },
    { left: '8%', top: '62%' },
  ]

  const summary: Array<{ label: string; value: string; Icon: LucideIcon; ready: boolean; step: StepId }> = [
    { label: 'Goal', value: goal, Icon: Target, ready: Boolean(answers.goal), step: 'goal' },
    {
      label: 'Markets',
      value: categories.length ? categories.join(', ') : 'Choose your markets',
      Icon: Store,
      ready: categories.length > 0,
      step: 'categories',
    },
    { label: 'Budget', value: budgetText(answers), Icon: Wallet, ready: Boolean(answers.budgetKey), step: 'budget' },
    { label: 'Hunting ground', value: location, Icon: MapPin, ready: Boolean(answers.locationName), step: 'location' },
    { label: 'Preferences', value: preferences || 'Optional filters', Icon: Heart, ready: Boolean(preferences), step: 'makes' },
  ]

  return (
    <motion.aside
      key="radar-preview"
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3, ease: 'easeOut' }}
      className="personalise-preview hidden lg:block"
      aria-label="Your live radar preview"
    >
      <div className="personalise-preview-card relative max-h-[calc(100dvh-10.5rem)] overflow-y-auto rounded-[26px] border p-5 xl:p-6">
        <div aria-hidden className="personalise-preview-orbit absolute -right-16 -top-20 h-52 w-52 rounded-full" />
        <div className="relative flex items-center justify-between">
          <p className="section-kicker section-kicker-blue">Your radar</p>
          <span className="inline-flex items-center gap-1.5 rounded-full border border-blue-300/15 bg-blue-400/[0.07] px-2.5 py-1 text-[9px] font-semibold uppercase tracking-[.12em] text-blue-100">
            <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-blue-300" /> Live build
          </span>
        </div>

        {/* radar visual with the picked categories orbiting it */}
        <div className="relative mt-5 flex h-36 items-center justify-center overflow-hidden rounded-2xl border border-white/[0.06] bg-[#090c12]/80">
          <span className="personalise-radar-ring absolute h-28 w-28 rounded-full" />
          <span className="personalise-radar-ring absolute h-20 w-20 rounded-full" />
          <span className="personalise-radar-ring absolute h-12 w-12 rounded-full" />
          <span className="personalise-radar-sweep absolute h-28 w-28 rounded-full" />
          <span className="relative flex h-11 w-11 items-center justify-center rounded-2xl border border-primary/30 bg-primary/10 text-primary shadow-[0_0_36px_-12px_rgba(255,106,26,.8)]">
            <Radar className="h-5 w-5" aria-hidden />
          </span>
          {orbit.map((emoji, i) => (
            <motion.span
              key={`${emoji}-${i}`}
              initial={{ scale: 0, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ delay: 0.1 + i * 0.06, type: 'spring', stiffness: 380, damping: 22 }}
              className="absolute flex h-6 w-6 items-center justify-center rounded-full border border-white/10 bg-[#0d1119] text-[11px] shadow-lg"
              style={orbitPositions[i]}
              aria-hidden
            >
              {emoji}
            </motion.span>
          ))}
          <span className="absolute left-[22%] top-[26%] h-1.5 w-1.5 rounded-full bg-blue-300 shadow-[0_0_9px_rgba(77,145,255,.8)]" />
          <span className="absolute bottom-[24%] right-[25%] h-1.5 w-1.5 rounded-full bg-primary shadow-[0_0_9px_rgba(255,106,26,.8)]" />
          <span className="absolute bottom-2.5 left-3 text-[8px] font-medium uppercase tracking-[.16em] text-white/30">Personalised search</span>
          <span className="absolute bottom-2.5 right-3 text-[8px] font-semibold tabular-nums text-blue-200/80">~{fmtInt(matches)} matches</span>
        </div>

        {/* live match estimate */}
        <div className="relative mt-4 flex items-end justify-between gap-3 rounded-2xl border border-primary/15 bg-gradient-to-r from-primary/[0.09] to-blue-400/[0.06] px-3.5 py-3">
          <div>
            <p className="text-[8px] font-semibold uppercase tracking-[.15em] text-white/40">Estimated potential</p>
