          </div>
          <span className="rounded-full border border-white/10 bg-white/[0.04] px-2 py-1 text-[8.5px] font-semibold uppercase tracking-wide text-white/50">
            {answers.verticals.length || 1} market{(answers.verticals.length || 1) === 1 ? '' : 's'}
          </span>
        </div>

        {/* example deals that follow the picked categories */}
        <div className="relative mt-4">
          <div className="flex items-center justify-between">
            <p className="text-[9px] font-semibold uppercase tracking-[.16em] text-muted-foreground">What could land</p>
            <span className="text-[8.5px] text-white/35">live examples</span>
          </div>
          <div className="mt-2 space-y-1.5">
            {deals.slice(0, 2).map((deal) => (
              <PreviewDealRow key={`${deal.title}-${deal.price}`} deal={deal} />
            ))}
          </div>
        </div>

        {/* blueprint rows — click to jump back and edit */}
        <div className="relative mt-4">
          <p className="text-[9px] font-semibold uppercase tracking-[.16em] text-muted-foreground">Wishlist blueprint</p>
          <div className="mt-2 space-y-1.5">
            {summary.map(({ label, value, Icon, ready, step }) => (
              <button
                key={label}
                type="button"
                onClick={() => onEdit(step)}
                className="group flex w-full items-center gap-2.5 rounded-xl border border-white/[0.05] bg-white/[0.025] px-2.5 py-2 text-left transition-colors hover:border-primary/30 hover:bg-white/[0.04]"
              >
                <span className={cn('flex h-6 w-6 shrink-0 items-center justify-center rounded-lg', ready ? 'bg-blue-400/10 text-blue-200' : 'bg-white/[0.04] text-white/35')}>
                  <Icon className="h-3.5 w-3.5" aria-hidden />
                </span>
                <span className="min-w-0 flex-1">
                  <span className="block text-[8px] font-semibold uppercase tracking-[.12em] text-white/35">{label}</span>
                  <span className={cn('mt-0.5 block truncate text-[10.5px] font-medium', ready ? 'text-white/85' : 'text-white/40')}>{value}</span>
                </span>
                {ready ? (
                  <Check className="h-3.5 w-3.5 shrink-0 text-blue-300" aria-hidden />
                ) : (
                  <Pencil className="h-3 w-3 shrink-0 text-white/25 transition-colors group-hover:text-primary" aria-hidden />
                )}
              </button>
            ))}
          </div>
        </div>

        <div className="relative mt-4 rounded-2xl border border-primary/15 bg-gradient-to-r from-primary/[0.09] to-blue-400/[0.06] p-3.5">
          <div className="flex items-center justify-between gap-3">
            <div>
              <p className="text-[8px] font-semibold uppercase tracking-[.15em] text-white/40">Trial unlocks</p>
              <p className="mt-1 text-xs font-semibold text-white">7-day Pro trial</p>
            </div>
            <div className="text-right">
              <p className="text-[11px] font-bold tabular-nums text-primary">5 min</p>
              <p className="text-[8px] text-white/40">scan cadence</p>
            </div>
          </div>
          <div className="mt-2.5 flex items-center gap-1.5 border-t border-white/[0.07] pt-2.5 text-[9px] text-white/50">
            <Check className="h-3 w-3 text-blue-300" aria-hidden /> Up to 5 wishlists · no card required
          </div>
        </div>

        {answers.preferredMarket && (
          <p className="relative mt-3 flex items-center gap-1.5 text-[9px] leading-relaxed text-white/40">
            <Store className="h-3 w-3 shrink-0 text-blue-200/70" aria-hidden />
            First marketplace: {market}
          </p>
        )}
      </div>
    </motion.aside>
  )
}

