function MakesStep({ answers, update }: { answers: Answers; update: (patch: Partial<Answers>) => void }) {
  const [draft, setDraft] = useState('')
  const toggle = (make: string) =>
    update({
      makes: answers.makes.includes(make)
        ? answers.makes.filter((m) => m !== make)
        : [...answers.makes, make],
    })
  const addCustom = () => {
    const v = draft.trim().replace(/\s+/g, ' ').slice(0, 40)
    if (!v) return
    if (answers.makes.length >= 12) return
    if (!answers.makes.some((m) => m.toLowerCase() === v.toLowerCase())) toggle(v)
    setDraft('')
  }
  const known = new Set([...MAKE_OPTIONS, ...Object.values(BRAND_SUGGESTIONS).flat()].map((b) => b.toLowerCase()))
  const customPicks = answers.makes.filter((m) => !known.has(m.toLowerCase()))

  const groups = answers.verticals
    .filter((v) => v !== 'vehicles')
    .map((v) => ({ vertical: v, brands: BRAND_SUGGESTIONS[v] ?? [] }))
    .filter((g) => g.brands.length > 0)

  const carBrands = answers.verticals.includes('vehicles') ? MAKE_OPTIONS : []

  return (
    <section aria-label="Favourite brands">
      <PromptHeading
        icon={Heart}
        title="Any favourite brands?"
        hint="Your feed and alerts boost these brands — from Toyota to Nike to LEGO. Pick as many as you like."
        aside={
          answers.makes.length > 0 ? (
            <span className="inline-flex items-center gap-1 rounded-full border border-primary/30 bg-primary/10 px-2.5 py-1 text-[10px] font-bold text-primary">
              {answers.makes.length} selected
            </span>
          ) : undefined
        }
      />

      {answers.makes.length > 0 && (
        <div className="mb-4 flex flex-wrap gap-2">
          {answers.makes.map((b) => (
            <span
              key={b}
              className="flex items-center gap-1.5 rounded-full border border-primary/40 bg-primary/10 px-3 py-1.5 text-[12.5px] font-semibold text-primary"
            >
              {b}
              <button
                type="button"
                onClick={() => toggle(b)}
                aria-label={`Remove ${b}`}
                className="rounded-full p-0.5 transition-colors hover:bg-primary/20"
              >
                <X className="h-3 w-3" aria-hidden />
              </button>
            </span>
          ))}
        </div>
      )}

      {carBrands.length > 0 && (
        <BrandGroup label="Car makes" emoji="🚗" brands={carBrands} selected={answers.makes} onToggle={toggle} />
      )}
      {groups.map((group) => {
        const vertical = getVertical(group.vertical)
        return (
          <BrandGroup
            key={group.vertical}
            label={vertical.label}
            emoji={vertical.emoji}
            brands={group.brands.filter((b) => !MAKE_OPTIONS.includes(b))}
            selected={answers.makes}
            onToggle={toggle}
          />
        )
      })}

      {/* free-text “Other” — any brand the suggestions miss */}
      <form
        onSubmit={(e) => {
          e.preventDefault()
          addCustom()
        }}
        className="mt-4 flex gap-2.5"
      >
        <Input
          value={draft}
          onChange={(e) => setDraft(e.target.value.slice(0, 40))}
          placeholder="Other — type any brand we missed…"
          className="h-11"
          aria-label="Add your own brand"
        />
        <Button
          type="submit"
          variant="outline"
          disabled={!draft.trim() || answers.makes.length >= 12}
          className="h-11 shrink-0 rounded-xl px-4 font-semibold"
        >
          <Plus className="mr-1 h-4 w-4" aria-hidden />
          Add
        </Button>
      </form>
      {customPicks.length > 0 && (
        <p className="mt-2.5 text-[11.5px] text-muted-foreground">
          {customPicks.length} custom brand{customPicks.length === 1 ? '' : 's'} added.
        </p>
      )}

      {answers.makes.length > 3 && (
        <p className="mt-3 text-[12px] text-muted-foreground">
          Your radar scans your top 3 — the rest still get a boost in your feed.
        </p>
      )}
    </section>
  )
}

function BrandGroup({
  label,
  emoji,
  brands,
  selected,
  onToggle,
}: {
  label: string
  emoji: string
  brands: string[]
  selected: string[]
  onToggle: (brand: string) => void
}) {
  if (brands.length === 0) return null
  return (
    <div className="mb-4">
      <p className="mb-2 flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-[.14em] text-muted-foreground">
        <span aria-hidden>{emoji}</span>
        {label}
      </p>
      <div className="flex flex-wrap gap-2">
        {brands.map((brand) => {
          const active = selected.includes(brand)
          return (
            <button
              key={brand}
              type="button"
              aria-pressed={active}
              onClick={() => onToggle(brand)}
              className={cn(
                'flex min-h-10 items-center gap-1.5 rounded-full border px-3.5 text-[13px] font-semibold transition-all',
                active
                  ? 'border-transparent bg-gradient-to-r from-primary to-orange-500 text-primary-foreground shadow-[0_8px_26px_-6px] shadow-primary/55'
                  : 'border-border bg-card/60 text-foreground/80 hover:border-primary/40 hover:bg-card'
              )}
            >
              {active && <Check className="h-3 w-3" strokeWidth={3} aria-hidden />}
              {brand}
            </button>
          )
        })}
      </div>
    </div>
  )
}

function LocationStep({ answers, update }: { answers: Answers; update: (patch: Partial<Answers>) => void }) {
  const [q, setQ] = useState('')

  const results = useMemo(() => {
    const needle = q.trim().toLowerCase()
    if (!needle) return []
    const out: WorldCity[] = []
    for (const c of CITY_BY_SLUG.values()) {
      if (
        c.name.toLowerCase().includes(needle) ||
        c.countryName.toLowerCase().includes(needle) ||
        (c.state && c.state.toLowerCase().includes(needle))
      ) {
        out.push(c)
      }
      if (out.length >= 30) break
    }
    return out.slice(0, 6)
  }, [q])

  const pickCity = (city: WorldCity) => {
    update({
      locationSlug: city.slug,
      locationName: city.name,
      lat: city.lat,
      lng: city.lng,
      country: city.country,
    })
    setQ('')
  }

  return (
    <section aria-label="Your hunting ground">
      <PromptHeading
        icon={MapPin}
        title="Where do you hunt?"
        hint="Pick your city and travel radius — then choose the marketplace you hunt first."
        aside={
          answers.locationName ? (
            <span className="inline-flex items-center gap-1 rounded-full border border-blue-400/25 bg-blue-400/[0.08] px-2.5 py-1 text-[10px] font-bold text-blue-200">
              <MapPin className="h-3 w-3" aria-hidden /> {answers.locationName}
            </span>
          ) : undefined
        }
      />

      <div className="mb-3 flex flex-wrap gap-2">
        {QUICK_CITIES.map((city) => {
          const active = answers.locationSlug === city.slug
          return (
            <button
              key={city.slug}
              type="button"
              aria-pressed={active}
              onClick={() => pickCity(city)}
              className={cn(
                'flex min-h-9 items-center gap-1.5 rounded-full border px-3 text-[12px] font-semibold transition-all',
                active
                  ? 'border-transparent bg-gradient-to-r from-primary to-orange-500 text-primary-foreground'
                  : 'border-border bg-card/60 text-foreground/75 hover:border-primary/40 hover:bg-card'
              )}
            >
              {active && <Check className="h-3 w-3" strokeWidth={3} aria-hidden />}
              {city.name}
            </button>
          )
        })}
        <button
          type="button"
          aria-pressed={!answers.locationName}
          onClick={() => update({ locationSlug: null, locationName: null, lat: null, lng: null, country: null })}
          className={cn(
            'flex min-h-9 items-center gap-1.5 rounded-full border px-3 text-[12px] font-semibold transition-all',
            !answers.locationName
              ? 'border-blue-400/40 bg-blue-400/10 text-blue-200'
              : 'border-border bg-card/60 text-foreground/75 hover:border-primary/40 hover:bg-card'
          )}
        >
          {!answers.locationName && <Check className="h-3 w-3" strokeWidth={3} aria-hidden />}
          Anywhere
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" aria-hidden />
        <Input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Search any city — London, Toronto, Tokyo…"
          className="h-11 pl-9"
          aria-label="Search marketplace city"
        />
      </div>

      {q.trim() && results.length === 0 && (
        <p className="mt-2 text-[12px] text-muted-foreground">No preset match — try a bigger city nearby.</p>
      )}

      {results.length > 0 && (
        <div className="mt-2.5 max-h-56 overflow-y-auto rounded-2xl border border-border" role="listbox" aria-label="City results">
          {results.map((r) => {
            const active = answers.locationSlug === r.slug
            return (
              <button
                key={r.slug}
                type="button"
                role="option"
                aria-selected={active}
                onClick={() => pickCity(r)}
                className={cn(
                  'flex w-full items-center gap-2.5 border-b border-border px-4 py-3 text-left text-sm transition-colors last:border-b-0',
                  active ? 'bg-primary/10 font-semibold text-primary' : 'hover:bg-surface-hover'
                )}
              >
                <MapPin className="h-4 w-4 shrink-0" aria-hidden />
                <span className="truncate">{r.name}</span>
                <span className="ml-auto text-[11px] text-muted-foreground">
                  {r.state ? `${r.state}, ` : ''}
                  {r.countryName}
                </span>
                {active && <Check className="h-4 w-4 shrink-0" aria-hidden />}
              </button>
            )
          })}
        </div>
      )}

      {answers.locationName && (
        <div className="mt-4 space-y-3">
          <div className="flex items-center gap-2 text-[13px]">
            <span className="text-muted-foreground">Hunting around</span>
            <span className="font-semibold">{answers.locationName}</span>
            <button
              type="button"
              onClick={() => update({ locationSlug: null, locationName: null, lat: null, lng: null, country: null })}
              className="text-muted-foreground transition-colors hover:text-foreground"
              aria-label="Clear location"
            >
              <X className="h-3.5 w-3.5" aria-hidden />
            </button>
          </div>
          <div>
            <p className="mb-1.5 text-[12px] text-muted-foreground">How far will you drive?</p>
            <div className="flex flex-wrap gap-2" role="radiogroup" aria-label="Search radius">
              {RADIUS_OPTIONS.map((r) => {
                const active = answers.radiusKm === r
                return (
                  <button
                    key={r}
                    type="button"
                    role="radio"
                    aria-checked={active}
                    onClick={() => update({ radiusKm: r })}
                    className={cn(
                      'flex min-h-11 items-center gap-1.5 rounded-full border px-4 text-sm font-semibold transition-all',
                      active
                        ? 'border-transparent bg-gradient-to-r from-primary to-orange-500 text-primary-foreground shadow-[0_8px_26px_-6px] shadow-primary/55'
                        : 'border-border bg-card/60 hover:bg-card'
                    )}
                  >
                    {active && <Check className="h-3.5 w-3.5" strokeWidth={3} aria-hidden />}
                    {r} km
                  </button>
                )
              })}
            </div>
          </div>
        </div>
      )}

      {/* preferred marketplace — offered once the location answer is settled
          (city picked or “Anywhere” chosen). latlng markets need a city to
          search near; country-scoped markets only serve their countries. */}
      <div className="mt-5">
        <p className="mb-2 flex items-center gap-1.5 text-[12px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">
          <Store className="h-3.5 w-3.5" aria-hidden />
          Preferred marketplace
        </p>
        <MarketDropdown
          value={answers.preferredMarket}
          country={answers.country}
          hasCity={answers.lat != null && answers.lng != null}
          onChange={(v) => update({ preferredMarket: v })}
        />
        <p className="mt-2.5 text-[12px] leading-relaxed text-muted-foreground">
          {answers.preferredMarket
            ? `${MARKET_META[normalizeMarket(answers.preferredMarket)].hint} Your starter radar gets created here.`
            : 'No preference and your radar starts on the best market for your patch — watchlists on any market can be added any time.'}
        </p>
      </div>
    </section>
  )
}

const AVOID_ICONS: Record<AvoidKey, LucideIcon> = {
  dealer: Store,
  high_kms: Gauge,
  older: CalendarClock,
  salvage: Wrench,
}

function AvoidStep({ answers, update }: { answers: Answers; update: (patch: Partial<Answers>) => void }) {
  const toggle = (key: AvoidKey) =>
    update({
      avoid: answers.avoid.includes(key)
        ? answers.avoid.filter((a) => a !== key)
        : [...answers.avoid, key],
    })
  return (
    <section aria-label="Dealbreakers">
      <PromptHeading
        icon={ShieldCheck}
        title="Any dealbreakers?"
        hint="We'll push these to the bottom of your feed. Pick as many as you like — or add your own below."
        aside={
          answers.avoid.length > 0 ? (
            <span className="inline-flex items-center gap-1 rounded-full border border-primary/30 bg-primary/10 px-2.5 py-1 text-[10px] font-bold text-primary">
              {answers.avoid.length} active
            </span>
          ) : undefined
        }
      />
      <div className="space-y-2.5">
        {AVOID_OPTIONS.map((a) => {
          const active = answers.avoid.includes(a.key)
          const Icon = AVOID_ICONS[a.key]
          return (
            <button
              key={a.key}
              type="button"
              role="switch"
              aria-checked={active}
              onClick={() => toggle(a.key)}
              className={cn(
                'flex w-full items-center gap-3 rounded-2xl border p-4 text-left transition-all',
                active ? 'border-primary bg-primary/10' : 'border-border bg-card/60 hover:border-primary/40 hover:bg-card'
              )}
            >
              <span
                className={cn(
                  'flex h-9 w-9 shrink-0 items-center justify-center rounded-xl border',
                  active ? 'border-primary/40 bg-primary/15 text-primary' : 'border-white/[0.08] bg-white/[0.03] text-muted-foreground'
                )}
              >
                <Icon className="h-4 w-4" aria-hidden />
              </span>
              <span className="min-w-0 flex-1">
                <span className="block text-[15px] font-semibold">{a.label}</span>
                <span className="mt-0.5 block text-[13px] leading-snug text-muted-foreground">{a.blurb}</span>
              </span>
              <span
                className={cn(
                  'ml-auto flex h-6 w-11 shrink-0 items-center rounded-full border px-0.5 transition-colors',
                  active ? 'border-primary bg-primary/80' : 'border-border bg-secondary'
                )}
                aria-hidden
              >
                <span
                  className={cn(
                    'h-4.5 w-4.5 rounded-full bg-background shadow transition-transform',
                    active ? 'translate-x-[20px]' : 'translate-x-0'
                  )}
                />
              </span>
            </button>
          )
        })}
