      <div className="mt-4">
        <label htmlFor="avoid-note" className="mb-1.5 block text-[12px] text-muted-foreground">
          Anything else we should avoid? <span className="text-white/30">(optional)</span>
        </label>
        <Input
          id="avoid-note"
          value={answers.avoidNote}
          onChange={(e) => update({ avoidNote: e.target.value.slice(0, 120) })}
          placeholder="e.g. no missing parts, no cracked screens, no imports…"
          className="h-11"
        />
      </div>
    </section>
  )
}

