/* -------------------------------- review --------------------------------- */

function ReviewStep({
  answers,
  onEdit,
  onReset,
}: {
  answers: Answers
  onEdit: (id: StepId) => void
  onReset: () => void
}) {
  const categories = answers.verticals.map((id) => getVertical(id))
  const optionalFilled = [
    answers.verticals.length > 0,
    Boolean(answers.budgetKey),
    Boolean(answers.locationName),
    answers.makes.length > 0,
    answers.avoid.length > 0 || Boolean(answers.avoidNote.trim()),
  ].filter(Boolean).length
  const readiness = Math.round(50 + (optionalFilled / 5) * 50)

  const rows: Array<{ label: string; value: string; Icon: LucideIcon; step: StepId; ready: boolean }> = [
    {
      label: 'Goal',
      value: GOAL_OPTIONS.find((g) => g.key === answers.goal)?.label ?? 'Not set',
      Icon: Target,
      step: 'goal',
      ready: Boolean(answers.goal),
    },
    {
      label: 'Markets',
      value: categories.length ? categories.map((c) => `${c.emoji} ${c.label}`).join(' · ') : 'Not set',
      Icon: Store,
      step: 'categories',
      ready: categories.length > 0,
    },
    { label: 'Budget', value: budgetText(answers), Icon: Wallet, step: 'budget', ready: Boolean(answers.budgetKey) },
    {
      label: 'Hunting ground',
      value: answers.locationName ? `${answers.locationName} · ${answers.radiusKm} km` : 'Anywhere',
      Icon: MapPin,
      step: 'location',
      ready: Boolean(answers.locationName),
    },
    {
      label: 'Brands',
      value: answers.makes.length ? answers.makes.join(', ') : 'Any brand',
      Icon: Heart,
      step: 'makes',
      ready: answers.makes.length > 0,
    },
    {
      label: 'Dealbreakers',
      value: [
        ...answers.avoid.map((k) => AVOID_OPTIONS.find((a) => a.key === k)?.label).filter(Boolean),
        answers.avoidNote.trim() ? `“${answers.avoidNote.trim()}”` : null,
      ].filter(Boolean).join(' · ') || 'None',
      Icon: ShieldCheck,
      step: 'avoid',
      ready: answers.avoid.length > 0 || Boolean(answers.avoidNote.trim()),
    },
    {
      label: 'Experience',
      value: EXPERIENCE_OPTIONS.find((e) => e.key === answers.experience)?.label ?? 'Not set',
      Icon: Gauge,
      step: 'experience',
      ready: Boolean(answers.experience),
    },
  ]

  return (
    <section aria-label="Review your radar">
      <PromptHeading
        icon={CheckCircle2}
        title="Your radar, dialled in"
        hint="One last look before we make it official. Tap any row to change the answer."
        aside={
          <span className="inline-flex items-center gap-1 rounded-full border border-emerald-500/25 bg-emerald-500/10 px-2.5 py-1 text-[10px] font-bold text-emerald-200">
            <Check className="h-3 w-3" strokeWidth={3} aria-hidden /> {readiness}% ready
          </span>
        }
      />

      <div className="rounded-2xl border border-white/[0.07] bg-white/[0.02] p-3.5">
        <div className="flex items-center justify-between gap-3">
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[.14em] text-muted-foreground">Radar readiness</p>
            <p className="mt-0.5 text-[12.5px] text-foreground/80">
              {optionalFilled >= 4 ? 'Everything important is covered.' : 'A few optional answers would sharpen the radar.'}
            </p>
          </div>
          <span className="text-lg font-bold tabular-nums text-primary">{readiness}%</span>
        </div>
        <Progress value={readiness} className="mt-2.5 h-1.5" />
      </div>

      <div className="mt-4 space-y-1.5">
        {rows.map(({ label, value, Icon, step, ready }) => (
          <button
            key={label}
            type="button"
            onClick={() => onEdit(step)}
            className="group flex w-full items-center gap-3 rounded-xl border border-white/[0.06] bg-white/[0.025] px-3.5 py-2.5 text-left transition-colors hover:border-primary/30 hover:bg-white/[0.04]"
          >
            <span className={cn('flex h-8 w-8 shrink-0 items-center justify-center rounded-lg', ready ? 'bg-primary/10 text-primary' : 'bg-white/[0.04] text-white/35')}>
              <Icon className="h-4 w-4" aria-hidden />
            </span>
            <span className="min-w-0 flex-1">
              <span className="block text-[9px] font-semibold uppercase tracking-[.12em] text-white/35">{label}</span>
              <span className={cn('mt-0.5 block truncate text-[12.5px] font-medium', ready ? 'text-white/85' : 'text-white/40')}>{value}</span>
            </span>
            <Pencil className="h-3.5 w-3.5 shrink-0 text-white/25 transition-colors group-hover:text-primary" aria-hidden />
          </button>
        ))}
      </div>

      <div className="mt-5 rounded-2xl border border-blue-400/15 bg-blue-400/[0.04] p-4">
        <p className="text-[11px] font-semibold uppercase tracking-[.14em] text-blue-200/80">What happens next</p>
        <ol className="mt-3 space-y-2.5">
          {[
            { n: '1', title: 'Create your account', text: 'Email or Google — no card required.' },
            { n: '2', title: 'Your radar goes live', text: 'The starter watchlist is built from these answers and scans immediately.' },
            { n: '3', title: 'First deals land', text: 'Good-ROI matches appear in your feed within minutes.' },
          ].map((item) => (
            <li key={item.n} className="flex items-start gap-2.5">
              <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full border border-blue-300/25 bg-blue-400/10 text-[9px] font-bold text-blue-200">
                {item.n}
              </span>
              <span>
                <span className="block text-[12.5px] font-semibold text-white/85">{item.title}</span>
                <span className="block text-[11px] leading-snug text-white/45">{item.text}</span>
              </span>
            </li>
          ))}
        </ol>
      </div>

      <div className="mt-4 flex items-center justify-between gap-3">
        <button
          type="button"
          onClick={onReset}
          className="text-[11px] font-medium text-muted-foreground transition-colors hover:text-foreground"
        >
          Start over
        </button>
        <span className="text-[10.5px] text-muted-foreground">Answers are saved on this device.</span>
      </div>
    </section>
  )
}

/* ------------------------------ account step ------------------------------ */

function AccountStep({ answers }: { answers: Answers }) {
  const [busy, setBusy] = useState(false)
  const profile = buildProfile(answers)
  const categories = answers.verticals.map((id) => getVertical(id))

  function continueToAccount() {
    if (busy) return
    setBusy(true)
    try {
      if (profile) window.localStorage.setItem(PENDING_PROFILE_KEY, JSON.stringify(profile))
      else window.localStorage.removeItem(PENDING_PROFILE_KEY)
      // The pending profile is now the canonical store; drop the draft so a
      // later visit to /personalise starts clean.
      window.localStorage.removeItem(DRAFT_KEY)
    } catch {
      // The auth screen still works; the in-app personalization remains a fallback.
    }
    window.location.assign('/signup?mode=signup&personalised=1')
  }

  return (
    <section aria-label="Create your account">
      <div className="relative">
        <motion.span
          aria-hidden
          className="absolute -right-2 -top-2 h-16 w-16 rounded-full bg-primary/15 blur-2xl"
          animate={{ scale: [1, 1.25, 1], opacity: [0.5, 0.9, 0.5] }}
          transition={{ duration: 3.2, repeat: Infinity, ease: 'easeInOut' }}
        />
        <PromptHeading
          icon={Sparkles}
          title="Your radar is ready"
          hint="One last step. Create your account to save your picks and start your personalised Pro trial."
          aside={
            <span className="inline-flex items-center gap-1 rounded-full border border-emerald-500/25 bg-emerald-500/10 px-2.5 py-1 text-[10px] font-bold text-emerald-200">
              <Check className="h-3 w-3" strokeWidth={3} aria-hidden /> Final step
            </span>
          }
        />
      </div>

      {/* recap chips */}
      <div className="flex flex-wrap gap-1.5">
        {[
          GOAL_OPTIONS.find((g) => g.key === answers.goal)?.label,
          categories.length ? `${categories.length} categor${categories.length === 1 ? 'y' : 'ies'}` : null,
          answers.budgetKey ? budgetText(answers) : null,
          answers.locationName ? `${answers.locationName} · ${answers.radiusKm} km` : 'Anywhere',
          answers.makes.length ? `${answers.makes.length} brand${answers.makes.length === 1 ? '' : 's'}` : null,
          answers.avoid.length ? `${answers.avoid.length} dealbreaker${answers.avoid.length === 1 ? '' : 's'}` : null,
        ]
          .filter(Boolean)
          .map((chip) => (
            <span
              key={chip}
              className="rounded-full border border-white/10 bg-white/[0.04] px-2.5 py-1 text-[11px] font-medium text-foreground/75"
            >
              {chip}
            </span>
          ))}
      </div>

      <div className="mt-5 rounded-2xl border border-primary/25 bg-gradient-to-br from-primary/[0.1] via-card/70 to-blue-500/[0.07] p-4 sm:p-5">
        <div className="flex items-center gap-2 text-[13px] font-semibold text-primary">
          <Sparkles className="h-4 w-4" aria-hidden />
          7-day free Pro trial · no card required
        </div>
        <p className="mt-2 text-[12px] leading-relaxed text-muted-foreground">
          {profile
            ? 'Your choices become a live radar the moment you sign up. Pick email or Google on the next screen; your wishlist setup follows your new account.'
            : 'You can create your account now and finish the optional personalisation in the app — nothing you picked is lost.'}
        </p>
        <ol className="mt-3 space-y-2 border-t border-white/[0.07] pt-3">
          {[
            { n: 'Today', text: 'Radar created and the first scan starts.' },
            { n: 'Day 7', text: 'Trial ends — choose Starter or Pro to keep the deals flowing.' },
            { n: 'Anytime', text: 'Change your answers in Settings.' },
          ].map((item) => (
            <li key={item.n} className="flex items-start gap-2.5 text-[11.5px]">
              <span className="w-12 shrink-0 text-[9px] font-bold uppercase tracking-wide text-primary/80">{item.n}</span>
              <span className="text-muted-foreground">{item.text}</span>
            </li>
          ))}
        </ol>
      </div>

      <div className="mt-4 grid gap-2 sm:grid-cols-2">
        {[
          'Every listing scored for profit & ROI',
          'Good-deal and price-drop alerts',
          'Up to 5 watchlists on Pro',
          'Cancel any time, no lock-in',
        ].map((line) => (
          <div key={line} className="flex items-center gap-2 text-[12px] text-foreground/75">
            <Check className="h-3.5 w-3.5 shrink-0 text-primary" aria-hidden />
            {line}
          </div>
        ))}
      </div>

      <Button type="button" size="lg" disabled={busy} onClick={continueToAccount} className="dealify-cta mt-5 h-12 w-full rounded-xl text-[15px] font-bold">
        {busy ? <><Loader2 className="mr-1.5 h-4 w-4 animate-spin" aria-hidden />Opening account setup…</> : <>Continue to create account <ChevronRight className="ml-1 h-4 w-4" aria-hidden /></>}
      </Button>
      <p className="mt-3 text-center text-[11px] text-muted-foreground">
        Already have an account? <a href="/signup?mode=login" className="font-medium text-primary hover:underline">Sign in</a>
      </p>
    </section>
  )
}

