// Walk the onboarding funnel and capture each step.
const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'
const { spawn } = require('node:child_process')
const fs = require('node:fs')
const path = require('node:path')

const width = Number(process.argv[2] ?? 1440)
const height = Number(process.argv[3] ?? 1000)
const prefix = process.argv[4] ?? '/tmp/funnel'
const mobile = process.argv[5] === 'mobile'
const port = 9600 + Math.floor(Math.random() * 200)
const profile = path.join('/tmp', `cdp-profile-${port}`)

const chrome = spawn(CHROME, [
  '--headless=new',
  '--disable-gpu',
  '--no-first-run',
  '--hide-scrollbars',
  `--remote-debugging-port=${port}`,
  `--user-data-dir=${profile}`,
  `--window-size=${width},${height}`,
  'about:blank',
], { stdio: 'ignore' })

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

async function main() {
  let targets
  for (let i = 0; i < 60; i++) {
    try {
      targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json()
      if (targets.length) break
    } catch {}
    await sleep(250)
  }
  const page = targets.find((t) => t.type === 'page')
  const ws = new WebSocket(page.webSocketDebuggerUrl)
  let id = 0
  const pending = new Map()
  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data)
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id)
      pending.delete(msg.id)
      msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result)
    }
  }
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const msgID = ++id
    pending.set(msgID, { resolve, reject })
    ws.send(JSON.stringify({ id: msgID, method, params }))
  })
  await new Promise((r) => { ws.onopen = r })

  await send('Page.enable')
  await send('Runtime.enable')
  await send('Emulation.setDeviceMetricsOverride', {
    width, height, deviceScaleFactor: mobile ? 2 : 1, mobile,
    screenWidth: width, screenHeight: height,
  })
  if (mobile) await send('Emulation.setTouchEmulationEnabled', { enabled: true })

  const evaluate = async (expression) => {
    const res = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true })
    if (res.exceptionDetails) throw new Error(res.exceptionDetails.text + ' :: ' + expression)
    return res.result?.value
  }
  const shot = async (name) => {
    await sleep(650)
    const { data } = await send('Page.captureScreenshot', { format: 'png' })
    const out = `${prefix}-${name}.png`
    fs.writeFileSync(out, Buffer.from(data, 'base64'))
    console.log('wrote', out)
  }
  const next = async () => {
    await evaluate(`(() => { const b=[...document.querySelectorAll('footer button')].filter(x=>!x.disabled); const el=b[b.length-1]; if(!el) return 'none'; el.click(); return el.textContent.trim() })()`)
    await sleep(700)
  }
  const click = async (sel, index = 0) => {
    const r = await evaluate(`(() => { const els=[...document.querySelectorAll(${JSON.stringify(sel)})]; const el=els[${index}]; if(!el) return 'missing:'+els.length; el.click(); return (el.textContent||'').trim().slice(0,40) })()`)
    await sleep(450)
    return r
  }
  const clickText = async (text) => {
    const r = await evaluate(`(() => { const el=[...document.querySelectorAll('button')].find(b=>(b.textContent||'').trim().includes(${JSON.stringify(text)})); if(!el) return 'missing'; el.click(); return 'ok' })()`)
    await sleep(450)
    return r
  }
  const title = async () => evaluate(`(document.querySelector('h1')?.textContent||'').trim()`)

  await send('Page.navigate', { url: 'http://localhost:3001/personalise' })
  await sleep(3200)
  await evaluate(`(() => { try { localStorage.clear() } catch {} ; return 'cleared' })()`)
  await send('Page.navigate', { url: 'http://localhost:3001/personalise' })
  await sleep(2800)

  const steps = []
  steps.push(await title())
  await shot('01-benefit-scan')
  await next()
  steps.push(await title())
  await shot('02-benefit-stories')
  await next()
  steps.push(await title())
  await shot('03-benefit-alerts')
  await next()
  steps.push(await title())
  await shot('04-goal')
  await click('[role="radio"]', 0)
  await shot('05-goal-picked')
  await next()
  steps.push(await title())
  await shot('06-categories')
  await click('[aria-pressed]', 0)
  await click('[aria-pressed]', 1)
  await shot('07-categories-picked')
  await next()
  steps.push(await title())
  await shot('08-budget')
  await click('[role="radio"]', 2)
  await shot('09-budget-picked')
  await next()
  steps.push(await title())
  await shot('10-styles')
  await next()
  steps.push(await title())
  await shot('11-makes')
  await next()
  steps.push(await title())
  await shot('12-location')
  await clickText('Sydney')
  await shot('13-location-picked')
  await next()
  steps.push(await title())
  await shot('14-avoid')
  await click('[role="switch"]', 0)
  await shot('15-avoid-picked')
  await next()
  steps.push(await title())
