  await shot('18-review')
  await next()
  steps.push(await title())
  await shot('19-account')

  console.log(JSON.stringify(steps, null, 2))
  ws.close()
  chrome.kill('SIGKILL')
  try { fs.rmSync(profile, { recursive: true, force: true }) } catch {}
  process.exit(0)
}

