.personalise-funnel {
  isolation: isolate;
  background:
    radial-gradient(ellipse at 50% 46%, rgb(20 50 111 / 14%), transparent 46%),
    linear-gradient(145deg, #090c13 0%, #08090c 54%, #0a0b10 100%);
}
.personalise-glow { z-index: -1; filter: blur(30px); }
.personalise-glow-blue { background: radial-gradient(circle, rgb(38 102 235 / 25%), rgb(20 60 145 / 8%) 48%, transparent 72%); }
.personalise-glow-orange { background: radial-gradient(circle, rgb(255 106 26 / 11%), rgb(255 106 26 / 3%) 50%, transparent 72%); }
.personalise-header { border-bottom: 1px solid rgb(255 255 255 / 5%); background: linear-gradient(180deg, rgb(8 10 15 / 64%), rgb(8 10 15 / 12%)); }
.personalise-header > a { border-color: rgb(255 255 255 / 8%); background: rgb(16 19 26 / 70%); }
.personalise-progress [data-slot="progress"] { background: rgb(255 255 255 / 8%); box-shadow: 0 0 18px -10px rgb(77 145 255 / 65%); }
.personalise-progress [data-slot="progress-indicator"] { background: linear-gradient(90deg, #ff6a1a 0%, #ff9a55 46%, #4d91ff 100%); border-radius: inherit; }
.personalise-step-shell {
  border-color: rgb(255 255 255 / 8%);
  background: radial-gradient(ellipse at 96% 0%, rgb(77 145 255 / 8%), transparent 42%), linear-gradient(145deg, rgb(17 20 28 / 94%), rgb(11 13 18 / 97%));
  box-shadow: 0 30px 90px -58px rgb(33 83 185 / 48%), inset 0 1px 0 rgb(255 255 255 / 5%);
}
.personalise-step-shell [role="radio"],
.personalise-step-shell [aria-pressed],
.personalise-step-shell [role="switch"] {
  border-color: rgb(255 255 255 / 8%);
  background: linear-gradient(145deg, rgb(255 255 255 / 3%), rgb(255 255 255 / 1%));
  transition: transform 180ms ease, border-color 180ms ease, background 180ms ease, box-shadow 180ms ease;
}
.personalise-step-shell [role="radio"]:hover,
.personalise-step-shell [aria-pressed]:hover,
.personalise-step-shell [role="switch"]:hover {
  transform: translateY(-1px);
  border-color: rgb(77 145 255 / 34%);
  background: linear-gradient(145deg, rgb(77 145 255 / 7%), rgb(255 255 255 / 2%));
}
.personalise-step-shell [role="radio"][aria-checked="true"],
.personalise-step-shell [aria-pressed="true"],
.personalise-step-shell [role="switch"][aria-checked="true"] {
  border-color: rgb(255 106 26 / 55%);
  background: linear-gradient(110deg, rgb(255 106 26 / 11%), rgb(77 145 255 / 7%));
  box-shadow: 0 12px 34px -26px rgb(255 106 26 / 80%), inset 0 1px 0 rgb(255 255 255 / 5%);
}
.personalise-footer { border-color: rgb(255 255 255 / 6%); background: linear-gradient(180deg, rgb(12 14 19 / 78%), rgb(8 9 12 / 96%)); backdrop-filter: blur(20px); }
@media (prefers-reduced-motion: reduce) {
  .personalise-step-shell [role="radio"], .personalise-step-shell [aria-pressed], .personalise-step-shell [role="switch"] { transition: none; }
  .personalise-step-shell [role="radio"]:hover, .personalise-step-shell [aria-pressed]:hover, .personalise-step-shell [role="switch"]:hover { transform: none; }
}

/* The onboarding flow: a wider desktop composition with a live profile preview. */
.personalise-layout { display: grid; grid-template-columns: minmax(0, 1fr); gap: 1rem; }
.personalise-preview { min-width: 0; }
.personalise-preview-card {
  position: relative;
  border-color: rgb(255 255 255 / 8%);
  background: radial-gradient(ellipse at 100% 0%, rgb(77 145 255 / 9%), transparent 42%), linear-gradient(150deg, rgb(17 20 28 / 96%), rgb(9 11 16 / 98%));
  box-shadow: 0 30px 90px -56px rgb(33 83 185 / 42%), inset 0 1px 0 rgb(255 255 255 / 5%);
}
.personalise-preview-orbit { border: 1px solid rgb(77 145 255 / 12%); background: radial-gradient(circle, rgb(77 145 255 / 12%), transparent 68%); filter: blur(4px); }
.personalise-radar-ring { border: 1px solid rgb(77 145 255 / 20%); box-shadow: inset 0 0 24px -19px rgb(77 145 255 / 45%); }
.personalise-radar-sweep {
  background: conic-gradient(from 0deg, transparent 0 72%, rgb(77 145 255 / 20%) 88%, transparent 100%);
  animation: personalise-radar-turn 10s linear infinite;
  mask-image: radial-gradient(circle, transparent 0 28%, #000 30% 100%);
}
@keyframes personalise-radar-turn { to { transform: rotate(360deg); } }
@media (min-width: 1024px) {
  .personalise-layout { grid-template-columns: minmax(0, 1fr) 300px; align-items: start; gap: 1.25rem; }
  .personalise-preview { position: sticky; top: 1.25rem; }
}
@media (min-width: 1280px) {
  .personalise-layout { grid-template-columns: minmax(0, 1fr) 320px; gap: 1.5rem; }
}
@media (prefers-reduced-motion: reduce) { .personalise-radar-sweep { animation: none; } }

