export function FlipStoriesPlayer({ stats }: { stats: LandingStats | null }) {
  const playerRef = useRef<PlayerRef>(null)
  const [paused, setPaused] = useState(false)
  const mounted = useMounted()
  const reducedMotion = useMediaQuery('(prefers-reduced-motion: reduce)')

  const stories = useMemo(() => buildStories(stats), [stats])
  const duration = stories.length * STORY_FRAMES

  // preload live listing photos so story transitions are seamless
  useEffect(() => {
    stories.forEach((s) => {
      if (s.photoUrl) {
        const img = new Image()
        img.referrerPolicy = 'no-referrer'
        img.src = s.photoUrl
      }
    })
  }, [stories])

  useEffect(() => {
    const p = playerRef.current
    if (!p) return
    const onPlay = () => setPaused(false)
    const onPause = () => setPaused(true)
    p.addEventListener('play', onPlay)
    p.addEventListener('pause', onPause)
    return () => {
      p.removeEventListener('play', onPlay)
      p.removeEventListener('pause', onPause)
    }
  }, [mounted])

  const seek = useCallback(
    (dir: 1 | -1) => {
      const p = playerRef.current
      if (!p) return
      const idx = Math.floor(p.getCurrentFrame() / STORY_FRAMES)
      const next = idx + dir
      p.seekTo(next < 0 || next >= stories.length ? 0 : next * STORY_FRAMES)
      p.play()
    },
    [stories.length]
  )

  const toggle = useCallback(() => {
    const p = playerRef.current
    if (!p) return
    if (p.isPlaying()) p.pause()
    else p.play()
  }, [])

  if (!mounted) {
    return (
      <div
        aria-hidden
        className="w-full animate-pulse rounded-[20px] border border-white/10"
        style={{ aspectRatio: '4 / 3', background: 'linear-gradient(160deg, #1c1a16, #141210)' }}
      />
    )
  }

  if (reducedMotion) {
    // static, no-motion collage of the first two stories
    const first = stories.slice(0, 2)
    return (
      <div className="grid gap-3 rounded-[20px] border border-white/10 p-3 sm:grid-cols-2" style={{ background: CARD_BG }}>
        {first.map((s) => (
          <div key={s.name} className="rounded-[14px] border border-white/10 p-4" style={{ background: 'rgba(245,244,240,0.04)' }}>
            <div className="text-[11px] font-bold uppercase tracking-widest" style={{ color: s.kind === 'live' ? '#fca5a5' : AMBER }}>
              {s.badge}
            </div>
            <div className="mt-1 truncate text-sm font-semibold text-[#f5f4f0]">{s.emoji} {s.meta}</div>
            <div className="text-[12px] text-white/50">{s.location}</div>
            <div className="mt-2 text-xl font-extrabold" style={{ color: AMBER }}>
              +{formatPrice(s.profit, s.currency)} <span className="text-xs font-semibold text-white/50">profit</span>
            </div>
          </div>
        ))}
      </div>
    )
  }

  return (
    <div
      className="group relative w-full overflow-hidden rounded-[20px] border border-white/10 shadow-2xl shadow-black/40"
      style={{ background: CARD_BG }}
      role="region"
      aria-label="Flip stories — real FlipRadar deals and profits"
    >
      <Player
        ref={playerRef}
        component={FlipStoriesComp}
        inputProps={{ stories }}
        durationInFrames={duration}
        fps={STORY_FPS}
        compositionWidth={600}
        compositionHeight={450}
        style={{ width: '100%' }}
        autoPlay
        loop
        controls={false}
        clickToPlay={false}
        doubleClickToFullscreen={false}
        spaceKeyToPlayOrPause={false}
        overflowVisible={false}
        acknowledgeRemotionLicense
      />

      {/* tap zones: prev · pause/play · next */}
      <div className="absolute inset-0 flex" style={{ zIndex: 30 }}>
        <button
          type="button"
          aria-label="Previous story"
          onClick={() => seek(-1)}
          className="h-full w-[26%] cursor-pointer bg-transparent focus-visible:outline-none"
        />
        <button
          type="button"
          aria-label={paused ? 'Play stories' : 'Pause stories'}
          onClick={toggle}
          className="h-full flex-1 cursor-pointer bg-transparent focus-visible:outline-none"
        />
        <button
          type="button"
          aria-label="Next story"
          onClick={() => seek(1)}
          className="h-full w-[26%] cursor-pointer bg-transparent focus-visible:outline-none"
        />
      </div>

      {/* pause indicator */}
      {paused && (
        <div className="pointer-events-none absolute inset-0 flex items-center justify-center" style={{ zIndex: 20 }}>
          <span className="flex h-14 w-14 items-center justify-center rounded-full border border-white/20 bg-black/55 backdrop-blur-sm">
            <Play className="ml-0.5 h-6 w-6 text-white" aria-hidden />
          </span>
        </div>
      )}

      {/* hint chip */}
      <div className="pointer-events-none absolute bottom-2.5 left-1/2 -translate-x-1/2 opacity-0 transition-opacity duration-200 group-hover:opacity-100" style={{ zIndex: 25 }}>
        <span className="inline-flex items-center gap-1.5 rounded-full bg-black/55 px-3 py-1 text-[10.5px] font-medium text-white/85 backdrop-blur-sm">
          <Pause className="h-3 w-3" aria-hidden /> tap to pause · sides to skip
        </span>
      </div>
    </div>
  )
}

const frame = useCurrentFrame()
const { fps } = useVideoConfig()
const card = spring({ frame, fps, config: { damping: 18, stiffness: 90, mass: 0.7 } })
const exitFade = interpolate(frame, [STORY_FRAMES - 7, STORY_FRAMES - 1], [1, 0], {
  extrapolateLeft: 'clamp',
  extrapolateRight: 'clamp',
})
const livePulse = story.kind === 'live' ? 0.45 + 0.55 * Math.abs(Math.sin(frame / 7)) : 1
const roiPop = spring({ frame: frame - 130, fps, config: { damping: 10, stiffness: 160, mass: 0.5 } })

return (
  <AbsoluteFill
    style={{
      backgroundColor: CARD_BG,
      opacity: Math.min(card, exitFade),
