const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'
const { spawn } = require('node:child_process')
const fs = require('node:fs')
const path = require('node:path')
const port = 9850 + Math.floor(Math.random() * 100)
const profile = path.join('/tmp', `cdp-profile-${port}`)
const chrome = spawn(CHROME, ['--headless=new','--disable-gpu','--no-first-run','--hide-scrollbars',`--remote-debugging-port=${port}`,`--user-data-dir=${profile}`,'--window-size=1440,1000','about:blank'], { stdio: 'ignore' })
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
async function main() {
  let targets
  for (let i = 0; i < 60; i++) { try { targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json(); if (targets.length) break } catch {} await sleep(250) }
  const page = targets.find((t) => t.type === 'page')
  const ws = new WebSocket(page.webSocketDebuggerUrl)
  let id = 0; const pending = new Map(); const logs = []
  ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.method === 'Runtime.consoleAPICalled') logs.push(m.params.args.map(a=>a.value??a.description).join(' ')); if (m.method === 'Runtime.exceptionThrown') logs.push('EXC ' + (m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text)); if (m.id && pending.has(m.id)) { const {resolve,reject}=pending.get(m.id); pending.delete(m.id); m.error?reject(new Error(JSON.stringify(m.error))):resolve(m.result) } }
  const send = (method, params={}) => new Promise((resolve,reject)=>{ const i=++id; pending.set(i,{resolve,reject}); ws.send(JSON.stringify({id:i,method,params})) })
  await new Promise((r) => { ws.onopen = r })
  await send('Page.enable'); await send('Runtime.enable')
  await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false })
  await send('Page.navigate', { url: 'http://localhost:3001/personalise' })
  await sleep(3000)
  const evaluate = async (expression) => { const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.text); return r.result?.value }
  await evaluate(`(() => { localStorage.clear(); return 1 })()`)
  await send('Page.navigate', { url: 'http://localhost:3001/personalise' })
  await sleep(2500)
  // advance to stories
  await evaluate(`(() => { const b=[...document.querySelectorAll('footer button')].filter(x=>!x.disabled); b[b.length-1].click(); return 1 })()`)
  await sleep(1000)
  // capture twice, 3s apart
  for (const wait of [0, 3000]) {
    if (wait) await sleep(wait)
    const { data } = await send('Page.captureScreenshot', { format: 'png' })
    fs.writeFileSync(`/tmp/stories-${wait}.png`, Buffer.from(data, 'base64'))
  }
  const info = await evaluate(`(() => { const p=[...document.querySelectorAll('div')].find(d=>d.getAttribute('aria-label')?.startsWith('Flip stories')); return { html: p? p.innerText.slice(0,400):'none', divs: document.querySelectorAll('div').length, imgs: [...document.images].map(i=>i.src).slice(0,5) } })()`)
  console.log(JSON.stringify(info, null, 2))
  console.log('LOGS:', logs.slice(-15).join('\n'))
  ws.close(); chrome.kill('SIGKILL'); try{fs.rmSync(profile,{recursive:true,force:true})}catch{}; process.exit(0)
}
main().catch(e=>{console.error(e);chrome.kill('SIGKILL');process.exit(1)})

