const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'
const { spawn } = require('node:child_process')
const fs = require('node:fs')
const path = require('node:path')
const port = 9900 + Math.floor(Math.random() * 90)
const profile = path.join('/tmp', `cdp-profile-${port}`)
const chrome = spawn(CHROME, ['--headless=new','--disable-gpu','--no-first-run','--hide-scrollbars',`--remote-debugging-port=${port}`,`--user-data-dir=${profile}`,'--window-size=1440,1000','about:blank'], { stdio: 'ignore' })
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
const results = []
const check = (name, ok, extra = '') => { results.push(`${ok ? 'PASS' : 'FAIL'} ${name}${extra ? ' :: ' + extra : ''}`) }

async function main() {
  let targets
  for (let i = 0; i < 60; i++) { try { targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json(); if (targets.length) break } catch {} await sleep(250) }
  const page = targets.find((t) => t.type === 'page')
  const ws = new WebSocket(page.webSocketDebuggerUrl)
  let id = 0; const pending = new Map()
  ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { const {resolve,reject}=pending.get(m.id); pending.delete(m.id); m.error?reject(new Error(JSON.stringify(m.error))):resolve(m.result) } }
  const send = (method, params={}) => new Promise((resolve,reject)=>{ const i=++id; pending.set(i,{resolve,reject}); ws.send(JSON.stringify({id:i,method,params})) })
  await new Promise((r) => { ws.onopen = r })
  await send('Page.enable'); await send('Runtime.enable')
  await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false })
  const evaluate = async (expression) => { const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.text + ' :: ' + expression); return r.result?.value }
  const nav = async (url) => { await send('Page.navigate', { url }); await sleep(2600) }
  const title = () => evaluate(`(document.querySelector('h1')?.textContent||'').trim()`)
  const clickLastFooter = () => evaluate(`(() => { const b=[...document.querySelectorAll('footer button')].filter(x=>!x.disabled); const el=b[b.length-1]; if(!el) return 'none'; el.click(); return 'ok' })()`)
  const clickText = (text) => evaluate(`(() => { const el=[...document.querySelectorAll('button,a')].find(b=>(b.textContent||'').trim().includes(${JSON.stringify(text)})); if(!el) return 'missing'; el.click(); return 'ok' })()`)
  const enter = () => send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13, nativeVirtualKeyCode: 13 }).then(() => send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13, nativeVirtualKeyCode: 13 }))
  const shot = async (name) => { const { data } = await send('Page.captureScreenshot', { format: 'png' }); fs.writeFileSync(`/tmp/beh-${name}.png`, Buffer.from(data, 'base64')) }

  await nav('http://localhost:3001/personalise')
  await evaluate(`(() => { try { localStorage.clear() } catch {} ; return 1 })()`)
  await nav('http://localhost:3001/personalise')
  check('starts on benefit screen', (await title()) === 'Deals find you.', await title())

  // advance to goal
  await clickLastFooter(); await sleep(700)
  await clickLastFooter(); await sleep(700)
  await clickLastFooter(); await sleep(800)
  check('reaches goal', (await title()) === 'What brings you to Dealify?', await title())

  // pick a goal then reload
  await evaluate(`(() => { document.querySelectorAll('[role="radio"]')[1].click(); return 1 })()`)
  await sleep(500)
  const beforeReload = await evaluate(`(() => { const raw=localStorage.getItem('dealify.personalise-draft.v2'); if(!raw) return null; const d=JSON.parse(raw); return { goal: d.answers.goal, step: d.step } })()`)
  check('draft persisted with goal', beforeReload?.goal === 'value_hunter', JSON.stringify(beforeReload))

  await nav('http://localhost:3001/personalise')
  check('restores on reload', (await title()) === 'What brings you to Dealify?', await title())
  const restored = await evaluate(`(() => { const el=document.querySelector('[role="radio"][aria-checked="true"]'); return el ? el.textContent.trim().slice(0,30) : null })()`)
  check('restored selection', Boolean(restored && restored.includes('Big-margin')), String(restored))
  const savedBadge = await evaluate(`(() => [...document.querySelectorAll('span')].some(s=>(s.textContent||'').trim()==='Progress saved'))()`)
  check('shows progress saved badge', savedBadge)
  await shot('restored')

  // Enter should advance from the goal step
  await enter(); await sleep(800)
  check('Enter advances', (await title()) === 'What do you flip?', await title())

  // Skip setup jumps to account from any prompt
  await clickText('Skip setup'); await sleep(800)
  check('skip setup reaches account', (await title()) === 'Your radar is ready', await title())
  const draftStillThere = await evaluate(`Boolean(localStorage.getItem('dealify.personalise-draft.v2'))`)
  check('draft kept until handoff', draftStillThere === true, String(draftStillThere))

  // back to review
  await clickText('Back to review'); await sleep(800)
  check('back to review works', (await title()) === 'Your radar, dialled in', await title())

  // hand off to account creation
  await clickLastFooter(); await sleep(800)
  await clickText('Continue to create account'); await sleep(2200)
  const url = await evaluate(`location.pathname + location.search`)
  check('handoff navigates to signup', String(url).startsWith('/signup') && String(url).includes('personalised=1'), String(url))
  const storage = await evaluate(`(() => { const p=localStorage.getItem('dealify.pending-signup-profile.v1'); const d=localStorage.getItem('dealify.personalise-draft.v2'); return { pending: p ? JSON.parse(p) : null, draft: d } })()`)
  check('pending profile stored', Boolean(storage.pending && storage.pending.goal), JSON.stringify(storage.pending))
  check('draft cleared on handoff', storage.draft === null, String(storage.draft))
  await shot('signup')

  console.log(results.join('\n'))
  ws.close(); chrome.kill('SIGKILL'); try{fs.rmSync(profile,{recursive:true,force:true})}catch{}; process.exit(0)
}
main().catch(e=>{console.error(e); console.log(results.join('\n')); chrome.kill('SIGKILL'); process.exit(1)})

