const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'
const { spawn } = require('node:child_process')
const fs = require('node:fs')
const path = require('node:path')
const port = 9690 + Math.floor(Math.random() * 90)
const profile = path.join('/tmp', `cdp-profile-${port}`)
const chrome = spawn(CHROME, ['--headless=new','--disable-gpu','--no-first-run','--hide-scrollbars',`--remote-debugging-port=${port}`,`--user-data-dir=${profile}`,'--window-size=1440,1000','about:blank'], { stdio: 'ignore' })
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
async function main() {
  let targets
  for (let i = 0; i < 60; i++) { try { targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json(); if (targets.length) break } catch {} await sleep(250) }
  const page = targets.find((t) => t.type === 'page')
  const ws = new WebSocket(page.webSocketDebuggerUrl)
  let id = 0; const pending = new Map()
  ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { const {resolve,reject}=pending.get(m.id); pending.delete(m.id); m.error?reject(new Error(JSON.stringify(m.error))):resolve(m.result) } }
  const send = (method, params={}) => new Promise((resolve,reject)=>{ const i=++id; pending.set(i,{resolve,reject}); ws.send(JSON.stringify({id:i,method,params})) })
  await new Promise((r) => { ws.onopen = r })
  await send('Page.enable'); await send('Runtime.enable')
  await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false })
  const evaluate = async (expression) => { const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.text); return r.result?.value }
  const nav = async (url) => { await send('Page.navigate', { url }); await sleep(2500) }
  const title = () => evaluate(`(document.querySelector('h1')?.textContent||'').trim()`)
  const next = async () => { await evaluate(`(() => { const b=[...document.querySelectorAll('footer button')].filter(x=>!x.disabled); b[b.length-1].click(); return 1 })()`); await sleep(700) }
  const click = async (sel, i=0) => { await evaluate(`(() => { document.querySelectorAll(${JSON.stringify(sel)})[${i}].click(); return 1 })()`); await sleep(450) }

  await nav('http://localhost:3001/personalise')
  await evaluate(`(() => { try { localStorage.clear() } catch {} ; return 1 })()`)
  await nav('http://localhost:3001/personalise')
  await next(); await next(); await next()          // benefits -> goal
  await click('[role="radio"]', 0)                   // quick flip
  await next()                                       // categories
  await click('[aria-pressed]', 0)                   // cars
  await next()                                       // budget
  await click('[role="radio"]', 2)                   // under 5k
  await next()                                       // styles (vehicles)
  await next()                                       // makes
  await next()                                       // location
  await next()                                       // avoid
  await next()                                       // experience
  await click('[role="radio"]', 1)                   // some experience
  await next()                                       // review
  console.log('at:', await title())
  await next()                                       // account
  console.log('at:', await title())
  await evaluate(`(() => { const el=[...document.querySelectorAll('button')].find(b=>(b.textContent||'').includes('Continue to create account')); el.click(); return 1 })()`)
  await sleep(2500)
  const out = await evaluate(`(() => ({ url: location.pathname + location.search, pending: (() => { try { return JSON.parse(localStorage.getItem('dealify.pending-signup-profile.v1')) } catch { return null } })(), draft: localStorage.getItem('dealify.personalise-draft.v2') }))()`)
  console.log(JSON.stringify(out, null, 2))
  ws.close(); chrome.kill('SIGKILL'); try{fs.rmSync(profile,{recursive:true,force:true})}catch{}; process.exit(0)
}
main().catch(e=>{console.error(e);chrome.kill('SIGKILL');process.exit(1)})

