import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  output: "standalone",
  turbopack: {
    root: process.cwd(),
  },
  /* Type errors now FAIL the build (they used to be masked by
   * ignoreBuildErrors — which let a broken /api/stats ship). Keep it that
   * way: `bunx tsc --noEmit` in CI/pre-deploy if you want a standalone check. */
  reactStrictMode: false,
  // Dev-only: the SQLite database lives inside the project tree
  // (db/custom.db) and the app writes to it constantly (session heartbeats,
  // scan telemetry). Those writes made the webpack dev watcher fire a Fast
  // Refresh full reload on every authenticated API call, wiping app state.
  // Exclude the database (and its journals) from the dev watcher.
  webpack: (config, { dev }) => {
    if (dev) {
      const prev = config.watchOptions?.ignored
      const existing = Array.isArray(prev)
        ? prev.filter((x): x is string => typeof x === "string" && x.length > 0)
        : typeof prev === "string" && prev
          ? [prev]
          : []
      config.watchOptions = {
        ...config.watchOptions,
        ignored: [
          ...existing,
          "**/node_modules/**",
          "**/db/**",
          "**/*.db",
          "**/*.db-journal",
          "**/*.db-wal",
          "**/*.db-shm",
        ],
      }
    }
    return config
  },
};

export default nextConfig;

