/** Plan pill copy: "2d 5h left" for trials, dates for subscriptions */
function trialLeftLabel(ms: number): string {
  const days = Math.floor(ms / 86_400_000)
  const hours = Math.floor((ms % 86_400_000) / 3_600_000)
  if (days >= 1) return `${days}d ${hours}h`
  if (hours >= 1) return `${hours}h`
  return `${Math.max(1, Math.round(ms / 60_000))}m`
}

function PlanPill({ plan }: { plan: NonNullable<SessionInfo['plan']> }) {
  const setView = useAppStore((s) => s.setView)
  const [tick, setTick] = useState(0)
  // keep the trial countdown honest between 30s session polls
  useEffect(() => {
    if (!plan.isTrial) return
    const t = setInterval(() => setTick((n) => n + 1), 60_000)
    return () => clearInterval(t)
  }, [plan.isTrial])

  const hasAccess = plan.tier !== 'locked'
  const locked = plan.tier === 'locked'
  const subLapsed =
    locked && (plan.subscriptionStatus === 'expired' || plan.subscriptionStatus === 'canceled')
  const label = hasAccess
    ? plan.isTrial
      ? `Trial · ${trialLeftLabel(plan.trialMsRemaining - tick * 60_000)} left`
      : plan.tier.toUpperCase()
    : subLapsed
      ? 'Subscription expired'
      : 'Trial ended'

  return (
    <button
      onClick={() => setView('billing')}
      className={cn(
        'hidden sm:flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-semibold transition-colors',
