            : 'Dealify subscription — manage in Billing'
          : subLapsed
            ? 'Your subscription has ended — subscribe in Billing to keep tracking.'
            : 'Your 7-day free trial has ended — subscribe in Billing to keep tracking.'
      }
    >
      {hasAccess ? (
