'use client'

import { useEffect, useState } from 'react'
import { Loader2, WifiOff, RefreshCw } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  api,
  authTokenPersisted,
  clearStoredAuthToken,
  hashSessionToken,
  setStoredAuthToken,
  stripHashSessionToken,
} from '@/lib/api'
import { AppShell } from '@/components/app/app-shell'
import { VerifyEmailGate } from '@/components/app/verify-email-gate'
import type { AuthUserView } from '@/lib/auth-view'

/** Client-side session gate for embedded-iframe contexts where the browser
 *  blocks the session cookie. The /app page tries the cookie fast-path first
 *  (server-side); when that finds nothing it renders this component, which
 *  authenticates via whichever fallback carrier is available:
 *
 *    1. #st=<token> URL fragment — login/signup appends it so even contexts
 *       with cookies AND storage both blocked (sandboxed iframes) get in;
 *    2. localStorage Bearer token (partitioned storage);
 *    3. nothing → redirect to the sign-up page.
 *
 *  Sign-out discipline: the gate only bounces to /signup when the server is
 *  REACHABLE and definitively answers "no session" (user: null). Network
 *  errors, 5xxs and gateway blips are transient — they retry with backoff and
 *  end on a reconnect screen that leaves every stored carrier untouched.
 *  Bouncing on a blip used to strand perfectly valid sessions on the login
 *  page and read as "the app signed me out". */
const MAX_ATTEMPTS = 5
const RETRY_BASE_MS = 1200

export function AppGate() {
  const [user, setUser] = useState<AuthUserView | null>(null)
  const [state, setState] = useState<'checking' | 'ok' | 'denied' | 'offline'>('checking')
  // Bump to re-run the gate check (Try again) with a fresh attempt budget.
  const [runId, setRunId] = useState(0)

  useEffect(() => {
    let cancelled = false
    let timer: ReturnType<typeof setTimeout> | null = null
    let attempts = 0

    const run = () => {
      // Hash-fragment handoff: adopt the token before any API call so every
      // request in this page lifetime carries it.
      const hashToken = hashSessionToken()
      if (hashToken) setStoredAuthToken(hashToken)

      api.auth
        .me()
        .then((r) => {
          if (cancelled) return
          if (r.user) {
            setUser(r.user)
            setState('ok')
            // The fragment is only needed where durable storage failed to
            // keep the token — drop it from the URL whenever anything else
            // carries the session so it never leaks into shared links.
            if (hashToken && authTokenPersisted(hashToken)) stripHashSessionToken()
          } else {
            // Stale fragment token (signed out elsewhere / expired) — clean
            // up so refreshes don't loop through a dead session. This is the
            // ONLY path that signs the gate: the server answered, the
            // session is definitively gone.
            if (hashToken) {
              clearStoredAuthToken()
              stripHashSessionToken()
            }
            setState('denied')
            window.location.replace('/signup')
          }
        })
        .catch(() => {
          // Unreachable server / 5xx / gateway hiccup — NOT a sign-out.
          // Retry with backoff, keeping every stored carrier intact; if the
          // server stays down, show the reconnect screen (never the login
          // page — the session itself is still valid server-side).
          if (cancelled) return
          attempts += 1
          if (attempts < MAX_ATTEMPTS) {
            timer = setTimeout(run, RETRY_BASE_MS * attempts)
          } else {
            setState('offline')
          }
        })
    }

    run()
    return () => {
      cancelled = true
      if (timer) clearTimeout(timer)
    }
  }, [runId])

  if (state === 'ok' && user) {
    // Same gate as the server fast-path in /app: unverified address → the
    // trial hasn't started, so the app renders the confirm-email card.
    if (!user.emailVerifiedAt) return <VerifyEmailGate email={user.email} />
    return <AppShell user={user} />
  }

  if (state === 'offline') {
    return (
      <div className="flex min-h-screen flex-col items-center justify-center gap-4 bg-background px-6 text-center">
        <span className="flex h-12 w-12 items-center justify-center rounded-xl bg-primary/10 text-primary">
          <WifiOff className="h-6 w-6" aria-hidden />
        </span>
        <div className="space-y-1.5">
          <p className="text-sm font-medium">Can&apos;t reach Dealify right now</p>
          <p className="max-w-xs text-sm text-muted-foreground">
            Your session is safe — the connection just dropped. Check your internet and try again.
          </p>
        </div>
        <Button
          variant="outline"
          size="sm"
          className="gap-1.5"
          onClick={() => {
            setState('checking')
            setRunId((id) => id + 1)
          }}
        >
          <RefreshCw className="h-3.5 w-3.5" aria-hidden />
          Try again
        </Button>
      </div>
    )
  }

  return (
    <div className="flex min-h-screen flex-col items-center justify-center gap-5 bg-background px-6">
      <img src="/logo-mark.png" alt="Dealify" className="h-14 w-14" />
      {state === 'checking' ? (
        <p className="flex items-center gap-2 text-sm text-muted-foreground">
          <Loader2 className="h-4 w-4 animate-spin" aria-hidden />
          Signing you in…
        </p>
      ) : (
        <p className="text-sm text-muted-foreground">
          Taking you to the sign-up page…
        </p>
      )}
    </div>
  )
}

