import { getLandingStats } from '@/lib/landing-stats'
import { OnboardingFunnel } from '@/components/landing/onboarding-funnel'

export const dynamic = 'force-dynamic'

/** Personalisation first; account creation is the final step of the flow.
 *
 *  `?start=1` is set by every public "Start free trial" CTA. It means "begin
 *  the onboarding from the top" even when this browser still has a saved
 *  draft sitting on the final create-account step — otherwise the CTA appears
 *  to jump straight to the sign-up form. A plain reload keeps the saved step. */
export default async function PersonalisePage({
  searchParams,
}: {
  searchParams: Promise<{ start?: string }>
}) {
  const [stats, params] = await Promise.all([
    getLandingStats().catch(() => null),
    searchParams,
  ])
  return (
    <OnboardingFunnel
      initialStats={stats}
      startAtPersonalisation
      startFresh={params.start === '1'}
    />
  )
}

