import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { requireUser } from '@/lib/auth'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const STATUSES = ['new', 'saved', 'hidden', 'dismissed']

/** Set the user's PERSONAL status on a listing: saved / hidden / dismissed.
 *
 *  Per-account feeds mean personal state lives on the UserListing edge row —
 *  hiding a car from my feed must not affect anyone else's. The listing must
 *  be in my own pool (matched by one of my watchlists). */
export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const auth = await requireUser()
  if (auth.response) return auth.response
  const me = auth.user.id
  const { id } = await params
  let body: any
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 })
  }
  const status = body.status
  if (!STATUSES.includes(status)) {
    return NextResponse.json({ error: `status must be one of ${STATUSES.join(', ')}` }, { status: 400 })
  }

  // Pool gate: only listings my own watchlists matched are addressable
  const mine = await db.watchlistListing.findFirst({
    where: { listingId: id, watchlist: { userId: me } },
    select: { listingId: true },
  })
  if (!mine) return NextResponse.json({ error: 'Listing not found' }, { status: 404 })

  if (status === 'new') {
    // "Un-save / reset" — the edge row's absence IS the new state
    await db.userListing
      .delete({ where: { userId_listingId: { userId: me, listingId: id } } })
      .catch(() => {})
    return NextResponse.json({ id, status: 'new' })
  }

  await db.userListing.upsert({
    where: { userId_listingId: { userId: me, listingId: id } },
    create: { userId: me, listingId: id, status },
    update: { status },
  })
  return NextResponse.json({ id, status })
}
