import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { requireUser } from '@/lib/auth'
import { scoreListing, isGoodRoi, persistScore } from '@/lib/scoring'
import { decodeVin, isPlaceholderPrice } from '@/lib/vehicle'
import { getSsrClient } from '@/lib/scanner'
import { getFleetCooldown } from '@/lib/facebook/guard'
import { formatMoneyCurrency } from '@/lib/currency'
import { upgradeEbayImageUrls, upgradeEbayImageUrl } from '@/lib/image-quality'
export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

/**
 * Re-enrich and re-score a listing:
 * 1. live detail fetch from FB (fills missing vehicle fields)
 * 2. VIN decode if missing
 * 3. recompute comps + deal rating
 */
export async function POST(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const auth = await requireUser()
  if (auth.response) return auth.response
  const { id } = await params
  const listing = await db.listing.findUnique({ where: { id } })
  if (!listing) return NextResponse.json({ error: 'Listing not found' }, { status: 404 })

  // Per-account gate: only my own watchlists' finds are re-analysable
  const mine = await db.watchlistListing.findFirst({
    where: { listingId: id, watchlist: { userId: auth.user.id } },
    select: { listingId: true },
  })
  if (!mine) return NextResponse.json({ error: 'Listing not found' }, { status: 404 })

  // Live detail refresh if we have a usable account — but NEVER while the
  // WHOLE fleet is resting (one detail-page hit during a rest would undo the
  // cooldown discipline; a single resting member is fine, rotation skips it).
  // PERSONAL ENGINES: the requester's own engines carry the fetch first.
  const cooldown = await getFleetCooldown(db)
  const client = cooldown.active ? null : await getSsrClient(db, undefined, auth.user.id)
  if (client) {
    try {
      const details = await client.getListingDetails(listing.fbListingId)
      const v = details.vehicleInfo
      if (details || v) {
        // A resolved detail page proves the listing is still live — un-stale
        const unStale =
          listing.status === 'stale'
            ? { status: 'new' as const, lastSeenAt: new Date() }
            : {}
        // Track price movement from the live page (drops re-score below)
        const livePrice = details.price ?? null
        // Live price became a "$1234"-style placeholder — the seller pulled
        // the real price to force enquiries. Retire the listing instead of
        // tracking the fake number (and no price-drop alert: it isn't a drop)
        const placeholderLive = isPlaceholderPrice(livePrice)
        const priceChange =
          livePrice != null && !placeholderLive && listing.price != null && livePrice !== listing.price
            ? { price: livePrice, previousPrice: listing.price, updatedPriceAt: new Date() }
            : {}
        if (livePrice != null && !placeholderLive && livePrice < (listing.price ?? Infinity)) {
          await db.alertEvent
            .create({
              data: {
                type: 'price_drop',
                userId: auth.user.id,
                title: `Price drop: ${listing.title}`,
                body: `Was $${listing.price!.toLocaleString()} now $${livePrice.toLocaleString()}`,
                listingId: listing.id,
              },
            })
            .catch(() => {})
        }
        await db.listing.update({
          where: { id },
          data: {
            description: details.description ?? listing.description,
            condition: details.condition ?? listing.condition,
            price: placeholderLive ? listing.price : (details.price ?? listing.price),
            city: details.city ?? listing.city,
            state: details.state ?? listing.state,
            ...unStale,
            ...priceChange,
            ...(placeholderLive ? { status: 'hidden' as const } : {}),
            make: listing.make ?? v?.make ?? null,
            model: listing.model ?? v?.model ?? null,
            trim: v?.trim ?? listing.trim,
            vin: v?.vin ?? listing.vin,
            odometer: v?.odometer ?? details.mileageSubtitle ?? listing.odometer,
            transmission: v?.transmission ?? listing.transmission,
            fuelType: v?.fuelType ?? listing.fuelType,
            exteriorColor: v?.exteriorColor ?? listing.exteriorColor,

// ---- budget-aware enrichment (the constant-scan mix) ----------------
// Searches are the only thing that DISCOVERS new listings, so when the
// carrier session's 24h headroom runs low, detail enrichment steps
// aside (a listing opened in the app enriches live on demand) and the
// remaining budget keeps feeding searches — right up to the cap —
// instead of letting enrichment spend the last requests and then
// hard-failing whole scans into budget rests.
if (scanClient && fbRequestsRemaining(scanClient.getCookieHeader()) < Math.round(FB_DAILY_REQUEST_BUDGET * 0.25)) {
  enrichBudget = 0
}

// ---- batch-load existing rows (kills the per-result findUnique N+1) ----
const summaries = listings
const existingRows = summaries.length
  ? await db.listing.findMany({
      where: { fbListingId: { in: summaries.map((l) => l.listingId) } },
    })
  : []
const existingByFbId = new Map(existingRows.map((r) => [r.fbListingId, r]))
const now = new Date()

const priceChanges: Array<{ existing: Listing; newPrice: number; dropped: boolean }> = []
/** tracked listings whose live price became a "$1234"-style placeholder —
 * the seller pulled the real price to force enquiries, so the listing
 * stops being trackable (hidden: out of the feed AND the comp pool) */
const placeholderPriced: Listing[] = []
const freshSummaries: RawSsrListing[] = []
for (const summary of summaries) {
  const existing = existingByFbId.get(summary.listingId)
  if (!existing) {
    freshSummaries.push(summary)
    continue
  }
  // Placeholder price on a tracked listing — skip the price-change path
  // entirely and retire the row instead of recording the fake price
  if (isPlaceholderPrice(summary.price)) {
    placeholderPriced.push(existing)
    continue
  }
  // Meaningful price change (≥1%): the search page exposes the CURRENT
  // price — the row must track it, and the score must be recomputed.
  // (Previously only previousPrice was written: the feed kept showing a
  // stale price forever and the rating never followed a drop.)
  const changed =
    summary.price != null &&
    existing.price != null &&
    summary.price !== existing.price &&
    Math.abs(summary.price - existing.price) / existing.price >= 0.01
  if (changed) {
    priceChanges.push({
      existing,
      newPrice: summary.price!,
      dropped: summary.price! < existing.price!,
    })
  }
}

// ---- retire placeholder re-pricings in bulk ----
if (placeholderPriced.length > 0) {
  await db.listing.updateMany({
    where: { id: { in: placeholderPriced.map((r) => r.id) } },
    data: { status: 'hidden' },
  })
}

// ---- refresh seen-state in bulk ----
if (existingRows.length > 0) {
  const existingIds = existingRows.map((r) => r.id)
  await db.listing.updateMany({
    where: { id: { in: existingIds } },
    data: { lastSeenAt: now },
  })
  await db.watchlistListing.updateMany({
    where: { watchlistId, listingId: { in: existingIds } },
    data: { lastMatchedAt: now },
  })
  // Link this watchlist to listings it re-surfaced but never linked.
  // (SQLite has no skipDuplicates — check which links exist, create the
  // missing ones; a concurrent scan racing us just trips the catch.)
  const linked = await db.watchlistListing.findMany({
    where: { watchlistId, listingId: { in: existingIds } },
    select: { listingId: true },
  })
  const linkedIds = new Set(linked.map((l) => l.listingId))
  const missing = existingIds.filter((id) => !linkedIds.has(id))
  if (missing.length > 0) {
    await db.watchlistListing
      .createMany({ data: missing.map((listingId) => ({ watchlistId, listingId })) })
      .catch(() => {})
  }

  // ---- relevance self-heal -------------------------------------------
  // Links that predate the relevance gate (or were created under a
  // query the user has since edited) get re-checked every scan and
  // unlinked when their titles no longer match. Listings the user
  // personally SAVED always stay, no matter what the gate says.
  const healVertical: VerticalId = isVerticalId(watchlist.vertical) ? watchlist.vertical : 'vehicles'
  const healQuery =
    watchlist.query?.trim() ||
    (healVertical !== 'vehicles' ? getVertical(healVertical).defaultQuery || null : null)
  if (healQuery && watchlist.userId && !marketIsDirectSearch) {
    const savedRows = await db.userListing.findMany({
      where: { userId: watchlist.userId, status: 'saved' },
      select: { listingId: true },
    })
    const savedIds = new Set(savedRows.map((r) => r.listingId))
    const offQueryIds = existingRows
      .filter(
        (r) =>
          !savedIds.has(r.id) &&
          !titleMatchesQuery(r.title, healQuery, { vertical: healVertical })
      )
      .map((r) => r.id)
    if (offQueryIds.length > 0) {
      await db.watchlistListing
        .deleteMany({ where: { watchlistId, listingId: { in: offQueryIds } } })
        .catch(() => {})
      console.info(
        `[scanner] relevance self-heal: unlinked ${offQueryIds.length} listing(s) no longer matching "${healQuery}"`
      )
    }
  }
}

// ---- price changes: store the new price, re-score, alert on drops ----
for (const change of priceChanges) {
  await db.listing.update({
    where: { id: change.existing.id },
    data: {
      price: change.newPrice,
      previousPrice: change.existing.price,
      updatedPriceAt: now,
      lastSeenAt: now,
    },
  })
  let rescored: ScoreResult | null = null
  try {
    const fresh = await db.listing.findUnique({ where: { id: change.existing.id } })
    if (fresh) {
      rescored = await scoreListing(db, toScorable(fresh))
      await persistScore(db, fresh.id, rescored)
    }
  } catch {
    // a failed re-score must not fail the scan — the price is already saved
  }
  if (change.dropped) {
    const isGoodRoiDrop = rescored ? isGoodRoi(rescored.dealRating, rescored.isScam) : false
    const note =
      rescored && isGoodRoiDrop
        ? ` — now a good-ROI deal (${rescored.roiPct ?? '?'}% ROI)`
        : rescored?.dealRating
          ? ` — rated ${rescored.dealRating}`
          : ''
    await db.alertEvent
      .create({
        data: {
          type: isGoodRoiDrop ? 'good_roi' : 'price_drop',
          // Per-account alerts: the owning watchlist's user is the recipient
          userId: watchlist.userId,
          title: `Price drop: ${change.existing.title}`,
          body: `Was ${formatMoneyCurrency(change.existing.price!, change.existing.currency)} now ${formatMoneyCurrency(change.newPrice, change.existing.currency)}${note}`,

