// Durable SALE OBSERVATION — the "previously sold" evidence layer.
//
// A Listing row disappears from its watchlist's search results (stale sweep)
// or is imported from a dealer/auction/private-sale CSV. The final asking
// price is the closest thing to a transaction record we can observe; it is
// converted to an expected SALE price with a measured asking→sale gap. These
// rows survive listing deletion and are the strongest evidence the valuation
// engine has: real prices for cars that actually left the market, not just
// asking prices for cars still sitting there.
//
// `soldPrice` is the value the estimator uses (actual when imported, gap-
// adjusted when inferred). `priceBasis` says which:
//   actual       — a real transaction price supplied by an import
//   asking-gap   — final asking price less the typical asking→sale gap
//   price-drop   — final asking price less a smaller gap because the seller
//                  had already moved off their original ask
model SaleObservation {
  id             String   @id @default(cuid())
  // Listing that produced this observation (null for CSV/import rows).
  // Unique so a relisted-then-sold car updates its one sale record instead
  // of piling up duplicates. SQLite allows many NULLs on a unique column.
  listingId      String?  @unique
  // Idempotent imports: source + externalId identifies one CSV row.
  externalId     String?
  // stale-sweep | import | manual
  source         String   @default("stale-sweep")
  vertical       String   @default("vehicles")
  marketplace    String   @default("FacebookMarketplace")
  title          String?
  make           String?
  model          String?
  year           Int?
  trim           String?
  bodyStyle      String?
  odometer       Int?
  condition      String?
  // analyzeCondition score (-1..1) captured at observation time
  conditionScore Float?
  transmission   String?
  state          String?
  currency       String   @default("AUD")
  // final advertised asking price (what the seller last wanted)
  askingPrice    Float?
  // expected / actual transaction price the estimator consumes
  soldPrice      Float?
  priceBasis     String   @default("asking-gap")
  // seller movement off the original ask, when we watched a price drop
  priceDropPct   Float?
  daysOnMarket   Int?
  listedAt       DateTime?
  observedAt     DateTime @default(now())
  confidence     String   @default("medium") // high | medium | low
  // small JSON blob: previousPrice, lastSeenAt, gapAppliedPct, titleStatus…
  evidence       String?
  createdAt      DateTime @default(now())
  updatedAt      DateTime @updatedAt

  @@unique([source, externalId])
  @@index([make, model, year])
  @@index([vertical, currency])
  @@index([observedAt])
  @@index([listingId])
}

// Per-account listing state — the deal feed is scoped to each account's own

input.content:
/**
 * Sold-comparable engine — the "previously sold" half of the valuation system.
 *
 * Live comps are asking prices: they tell you what sellers WANT. A sale
 * observation tells you what a car actually LEFT the market for. This module
 * turns those observations into a subject-specific expected sale value:
 *
 *   match     same make+model first (exact family), then same make + same
 *             body style, then same body style across makes when the family
 *             evidence is thin — every wider tier carries a much smaller weight
 *   adjust    model year (data-driven depreciation curve, fallback 7%/yr),
 *             odometer (data-driven $/km slope, fallback ~3%/10k km),
 *             condition (analyzeCondition score), transmission, state
 *   weight    similarity × year proximity × odometer proximity × recency
 *             (sold evidence has a 180-day half-life) × observation confidence
 *   estimate  robust weighted median (80%) + weighted mean (20%), outlier
 *             clipped, with an IQR-derived band and an effective-sample-size
 *             confidence grade
 *
 * The result is a SALE value. `askingEquivalent` converts it back into the
 * asking-price basis the deal room's "fair value" uses, so a sold-derived
 * value can be blended with live comps and the ML model without changing the
 * meaning of the headline number.
 *
 * Observations are durable: they survive listing deletion, can be imported
 * from dealer/auction CSVs, and are recorded automatically by the stale sweep
 * when a watched listing disappears from the market.
 */

import type { PrismaClient, SaleObservation } from '@prisma/client'
import { normalizeKey } from '../comps'
import { currencyFloor, formatMoneyCurrency } from '../currency'
import { analyzeCondition } from '../valuation'
import { isPartsOrWreckListing, parseVehicleTitle } from '../vehicle'
import { detectBodyStyles } from './features'
import { ASKING_TO_SALE_DISCOUNT_PCT } from './au-baseline'

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export type SalePriceBasis = 'actual' | 'asking-gap' | 'price-drop'
export type SaleConfidence = 'high' | 'medium' | 'low'

export interface SaleObservationRow {
  id: string
  listingId: string | null
  source: string
  vertical: string
  marketplace: string
  title: string | null
  make: string
  model: string
  year: number | null
  trim: string | null
  bodyStyle: string | null
  odometer: number | null
  condition: string | null
  conditionScore: number | null
  transmission: string | null
  state: string | null
  currency: string
  askingPrice: number | null
  soldPrice: number
  priceBasis: string
  priceDropPct: number | null
  daysOnMarket: number | null
  listedAt: Date | null
  observedAt: Date
  confidence: string
}

export interface SaleSubject {
  id?: string | null
  make: string | null
  model: string | null
  year: number | null
  odometer?: number | null
  condition?: string | null
  transmission?: string | null
  state?: string | null
  bodyStyle?: string | null
  title?: string | null
  currency?: string | null
}

export interface SaleCompFactor {
  label: string
  detail: string
  impactPct?: number
}

export interface SaleCompSample {
  title: string
  price: number
  daysOnMarket: number | null
  year: number | null
  odometer: number | null
  observedAt: string
  basis: string
}

export interface SaleCompEstimate {
  /** expected SALE value, adjusted to the subject */
  value: number
  low: number
  high: number
  /** the same value expressed on the asking-price basis used by fairValue */
  askingEquivalent: number
  compCount: number
  exactCount: number
  widerCount: number
  /** Kish effective sample size (sum(w)^2 / sum(w^2)) */
  effectiveCount: number
  confidence: SaleConfidence
  method: 'sold-comps' | 'sold-comps-wide'
  medianSoldPrice: number | null
  medianDaysToSell: number | null
  askingGapPct: number
  iqrPct: number | null
  bandPct: number
  yearRatePct: number
  odometerRatePerKm: number
  factors: SaleCompFactor[]
  sample: SaleCompSample[]
}

export interface RecordSaleInput {
  listingId?: string | null
  externalId?: string | null
  source?: string
  vertical?: string
  marketplace?: string
  title?: string | null
  make?: string | null
  model?: string | null
  year?: number | null
  trim?: string | null
  bodyStyle?: string | null
  odometer?: number | null
  condition?: string | null
  conditionScore?: number | null
  transmission?: string | null
  state?: string | null
  currency?: string | null
  askingPrice?: number | null
  soldPrice?: number | null
  priceBasis?: SalePriceBasis
  priceDropPct?: number | null
  daysOnMarket?: number | null
  listedAt?: Date | null
  observedAt?: Date | null
  confidence?: SaleConfidence
  evidence?: Record<string, unknown> | null
}

/** A Listing-shaped object accepted by recordSaleFromListing (full rows and
 *  the maintenance sweep's selected columns both fit). */
export interface SaleListingLike {
  id: string
  title: string
  price: number | null
  currency?: string | null
  description?: string | null
  condition?: string | null
  make?: string | null
  model?: string | null
  year?: number | null
  trim?: string | null
  bodyStyle?: string | null
  odometer?: number | null
  transmission?: string | null
  state?: string | null
  previousPrice?: number | null
  postedAt?: Date | null
  firstSeenAt?: Date | null
  lastSeenAt?: Date | null
  titleStatus?: string | null
  vertical?: string | null
  marketplace?: string | null
  isScam?: boolean | null
}

// ---------------------------------------------------------------------------
// Tuning constants
// ---------------------------------------------------------------------------

const SALE_POOL_TTL_MS = 60_000
const SALE_POOL_LOOKBACK_DAYS = 730
const SALE_POOL_MAX = 8_000

/** fallback depreciation when the local family does not have enough years */
const FALLBACK_YEAR_RATE = 0.07
const YEAR_RATE_MIN = 0.02
const YEAR_RATE_MAX = 0.18

/** fallback odometer slope: fraction of value per km (~3% per 10,000 km) */
const FALLBACK_KM_RATE = 3e-6
const KM_RATE_MIN = 5e-7
const KM_RATE_MAX = 8e-6

/** full condition-score swing (−1..1) moves value by ±8% */
const CONDITION_WEIGHT = 0.08
/** sold evidence ages more slowly than an asking price, but it still ages */
const SOLD_RECENCY_HALF_DAYS = 180

const TIER_WEIGHT = {
  exact: 1,
  sameMakeBody: 0.45,
  sameMakeUnknownBody: 0.25,
  sameBodyOtherMake: 0.12,
} as const

// ---------------------------------------------------------------------------
// Small numeric helpers
// ---------------------------------------------------------------------------

function clamp(v: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, v))
}

function median(values: number[]): number | null {
  if (values.length === 0) return null
  const sorted = [...values].sort((a, b) => a - b)
  const mid = Math.floor(sorted.length / 2)
  return sorted.length % 2 === 0 ? (sorted[mid - 1] + sorted[mid]) / 2 : sorted[mid]
}

function weightedMedian(entries: Array<{ value: number; weight: number }>): number | null {
  if (entries.length === 0) return null
  const sorted = [...entries].sort((a, b) => a.value - b.value)
  const total = sorted.reduce((s, e) => s + e.weight, 0)
  if (total <= 0) return sorted[Math.floor(sorted.length / 2)]?.value ?? null
  let acc = 0
  for (const e of sorted) {
    acc += e.weight
    if (acc >= total / 2) return e.value
  }
  return sorted[sorted.length - 1].value
}

function weightedMean(entries: Array<{ value: number; weight: number }>): number | null {
  const total = entries.reduce((s, e) => s + e.weight, 0)
  if (total <= 0) return null
  return entries.reduce((s, e) => s + e.value * e.weight, 0) / total
}

function weightedQuantile(entries: Array<{ value: number; weight: number }>, q: number): number | null {
  if (entries.length === 0) return null
  const sorted = [...entries].sort((a, b) => a.value - b.value)
  const total = sorted.reduce((s, e) => s + e.weight, 0)
  if (total <= 0) return null
  const target = total * clamp(q, 0, 1)
  let acc = 0
  for (const e of sorted) {
    acc += e.weight
    if (acc >= target) return e.value
  }
  return sorted[sorted.length - 1].value
}

function round50(n: number): number {
  return Math.max(0, Math.round(n / 50) * 50)
}

/** Robust Theil–Sen slope: median of pairwise slopes (one wreck can't bend it) */
function theilSenSlope(points: Array<{ x: number; y: number }>): number | null {
  if (points.length < 3) return null
  const slopes: number[] = []
  for (let i = 0; i < points.length; i++) {
    for (let j = i + 1; j < points.length; j++) {
      const dx = points[j].x - points[i].x
      if (Math.abs(dx) < 1e-9) continue
      slopes.push((points[j].y - points[i].y) / dx)
    }
  }
  return slopes.length >= 3 ? median(slopes) : null
}

/** Sold evidence recency: 1.0 for 90 days, then a 180-day half-life. */
function soldRecencyWeight(observedAt: Date): number {
  const days = Math.max(0, (Date.now() - observedAt.getTime()) / 86_400_000)
  if (days <= 90) return 1
  return Math.max(0.2, Math.pow(0.5, (days - 90) / SOLD_RECENCY_HALF_DAYS))
}

function bodyStyleKey(bodyStyle: string | null | undefined, title: string | null | undefined): string {
  const raw = normalizeKey(bodyStyle)
  if (raw) {
    if (/\b(ute|pickup|pick up|dual cab|single cab|extra cab|space cab|cab chassis|tray)\b/.test(raw)) return 'ute'
    if (/\b(suv|4wd|4x4|awd|crossover)\b/.test(raw)) return 'suv'
    if (/\b(hatch|hatchback)\b/.test(raw)) return 'hatch'
    if (/\b(wagon|estate|sport brake)\b/.test(raw)) return 'wagon'
    if (/\b(coupe|2 door)\b/.test(raw)) return 'coupe'
    if (/\b(convertible|cabrio|cabriolet|roadster|soft top)\b/.test(raw)) return 'convertible'
    if (/\b(van|minivan|mini van|people mover|peoplemover)\b/.test(raw)) return 'van'
    if (/\b(sedan|saloon|4 door)\b/.test(raw)) return 'sedan'
    return raw.split(' ')[0] ?? ''
  }
  const detected = detectBodyStyles(title ?? '')
  const key = Object.keys(detected)[0]
  return key ? key.replace('body_', '') : ''
}

/** Typical asking→sale gap, tightened for sellers who already moved and
 *  widened for cars that have been sitting a long time. */
export function askingToSaleGapPct(input: {
  priceDropPct?: number | null
  daysOnMarket?: number | null
}): number {
  const base = ASKING_TO_SALE_DISCOUNT_PCT
  const dropRelief =
    input.priceDropPct != null && input.priceDropPct > 0 ? Math.min(4, input.priceDropPct / 2) : 0
  const domPressure =
    input.daysOnMarket == null ? 0 : input.daysOnMarket > 60 ? 2 : input.daysOnMarket <= 7 ? -1 : 0
  return clamp(base - dropRelief + domPressure, 2, 15)
}

// ---------------------------------------------------------------------------
// Cached sale pool
// ---------------------------------------------------------------------------

let saleCache: { rowCount: number; loadedAt: number; rows: SaleObservationRow[] } | null = null

function mapRow(row: SaleObservation): SaleObservationRow | null {
  if (row.soldPrice == null || row.soldPrice <= 0) return null
  return {
    id: row.id,
    listingId: row.listingId,
    source: row.source,
    vertical: row.vertical,
    marketplace: row.marketplace,
    title: row.title,
    make: row.make ?? '',
    model: row.model ?? '',
    year: row.year,
    trim: row.trim,
    bodyStyle: row.bodyStyle,
    odometer: row.odometer != null && row.odometer > 0 ? row.odometer : null,
    condition: row.condition,
    conditionScore: row.conditionScore,
    transmission: row.transmission,
    state: row.state,
    currency: (row.currency ?? 'AUD').toUpperCase(),
    askingPrice: row.askingPrice,
    soldPrice: row.soldPrice,
    priceBasis: row.priceBasis,
    priceDropPct: row.priceDropPct,
    daysOnMarket: row.daysOnMarket,
    listedAt: row.listedAt,
    observedAt: row.observedAt,
    confidence: row.confidence,
  }
}

/** Cached sold pool — invalidated by the row count (cross-process writes from
 *  the scanner service) and a 60s TTL, same contract as the live comp pool. */
export async function getSaleObservationRows(db: PrismaClient): Promise<SaleObservationRow[]> {
  const since = new Date(Date.now() - SALE_POOL_LOOKBACK_DAYS * 86_400_000)
  const where = {
    vertical: 'vehicles',
    soldPrice: { not: null, gt: 20 },
    observedAt: { gte: since },
  } as const
  const rowCount = await db.saleObservation.count({ where })
  if (saleCache && saleCache.rowCount === rowCount && Date.now() - saleCache.loadedAt < SALE_POOL_TTL_MS) {
    return saleCache.rows
  }
  const rows = await db.saleObservation.findMany({
    where,
    orderBy: { observedAt: 'desc' },
    take: SALE_POOL_MAX,
  })
  const mapped = rows.flatMap((r) => {
    const m = mapRow(r)
    return m ? [m] : []
  })
  saleCache = { rowCount, loadedAt: Date.now(), rows: mapped }
  return mapped
}

export function invalidateSalePool(): void {
  saleCache = null
}

// ---------------------------------------------------------------------------
// Writing observations
// ---------------------------------------------------------------------------

function buildSaleData(input: RecordSaleInput): Record<string, unknown> | null {
  const currency = (input.currency ?? 'AUD').toUpperCase()
  const asking = input.askingPrice != null && input.askingPrice > 0 ? input.askingPrice : null
  const providedSold = input.soldPrice != null && input.soldPrice > 0 ? input.soldPrice : null
  const priceDropPct = input.priceDropPct != null ? input.priceDropPct : null

  let soldPrice = providedSold
  let priceBasis: SalePriceBasis = input.priceBasis ?? (providedSold != null ? 'actual' : 'asking-gap')
  if (soldPrice == null) {
    if (asking == null) return null
    const gap = askingToSaleGapPct({ priceDropPct, daysOnMarket: input.daysOnMarket ?? null })
    soldPrice = Math.round(asking * (1 - gap / 100))
    priceBasis = priceDropPct != null && priceDropPct > 0 ? 'price-drop' : 'asking-gap'
  }
  if (soldPrice == null || soldPrice <= 0) return null
  if (soldPrice < currencyFloor(currency)) return null

  const make = input.make?.trim() || null
  const model = input.model?.trim() || null
  if (!make || !model) return null

  const conditionScore =
    input.conditionScore != null
      ? input.conditionScore
      : analyzeCondition({
          title: input.title ?? '',
          description: null,
          condition: input.condition ?? null,
          odometer: input.odometer ?? null,
          year: input.year ?? null,
          titleStatus: null,
        }).score

  return {
    source: input.source ?? 'stale-sweep',
    vertical: input.vertical ?? 'vehicles',
    marketplace: input.marketplace ?? 'FacebookMarketplace',
    title: input.title ?? null,
    make,
    model,
    year: input.year != null ? Math.round(input.year) : null,
    trim: input.trim ?? null,
    bodyStyle: input.bodyStyle ?? null,
    odometer: input.odometer != null && input.odometer > 0 ? Math.round(input.odometer) : null,
    condition: input.condition ?? null,
    conditionScore,
    transmission: input.transmission ?? null,
    state: input.state ?? null,
    currency,
    askingPrice: asking,
    soldPrice: Math.round(soldPrice),
    priceBasis,
    priceDropPct,
    daysOnMarket: input.daysOnMarket != null ? Math.max(1, Math.round(input.daysOnMarket)) : null,
    listedAt: input.listedAt ?? null,
    observedAt: input.observedAt ?? new Date(),
    confidence: input.confidence ?? 'medium',
    evidence: input.evidence ? JSON.stringify(input.evidence) : null,
  }
}

/** Record one sale observation. Idempotent when `listingId` or
 *  `source + externalId` is supplied. */
export async function recordSaleObservation(
  db: PrismaClient,
  input: RecordSaleInput
): Promise<SaleObservation | null> {
  const data = buildSaleData(input)
  if (!data) return null

  if (input.listingId) {
    const existing = await db.saleObservation.findUnique({ where: { listingId: input.listingId } })
    const row = existing
      ? await db.saleObservation.update({ where: { id: existing.id }, data })
      : await db.saleObservation.create({ data: { ...data, listingId: input.listingId } })
    invalidateSalePool()
    return row
  }

  if (input.source && input.externalId) {
    const row = await db.saleObservation.upsert({
      where: { source_externalId: { source: input.source, externalId: input.externalId } },
      create: { ...data, source: input.source, externalId: input.externalId },
      update: data,
    })
    invalidateSalePool()
    return row
  }

  const row = await db.saleObservation.create({ data })
  invalidateSalePool()
  return row
}

/** Capture a listing that has left the market (the stale sweep's sale record). */
export async function recordSaleFromListing(
  db: PrismaClient,
  listing: SaleListingLike,
  opts: { source?: string; observedAt?: Date } = {}
): Promise<SaleObservation | null> {
  if (listing.isScam) return null
  if ((listing.vertical ?? 'vehicles') !== 'vehicles') return null
  if (listing.price == null || listing.price <= 0) return null
  if (isPartsOrWreckListing(listing.title, listing.description ?? null)) return null

  const parsed = parseVehicleTitle(listing.title)
  const make = listing.make ?? parsed.make ?? null
  const model = listing.model ?? parsed.model ?? null
  const year = listing.year ?? parsed.year ?? null
  if (!make || !model) return null

  const currency = (listing.currency ?? 'AUD').toUpperCase()
  if (listing.price < currencyFloor(currency)) return null

  const basisDate = listing.postedAt ?? listing.firstSeenAt ?? null
  const lastSeen = listing.lastSeenAt ?? opts.observedAt ?? new Date()
  const daysOnMarket =
    basisDate != null
      ? Math.max(1, Math.round((lastSeen.getTime() - basisDate.getTime()) / 86_400_000))
      : null

  const priceDropPct =
    listing.previousPrice != null && listing.previousPrice > listing.price
      ? ((listing.previousPrice - listing.price) / listing.previousPrice) * 100
      : null

  const gapAppliedPct = askingToSaleGapPct({ priceDropPct, daysOnMarket })
  const soldPrice = Math.round(listing.price * (1 - gapAppliedPct / 100))

  const { score: conditionScore } = analyzeCondition({
    title: listing.title,
    description: listing.description ?? null,
    condition: listing.condition ?? null,
    odometer: listing.odometer ?? null,
    year,
    titleStatus: listing.titleStatus ?? null,
  })

  return recordSaleObservation(db, {
    listingId: listing.id,
    source: opts.source ?? 'stale-sweep',
    vertical: 'vehicles',
    marketplace: listing.marketplace ?? 'FacebookMarketplace',
    title: listing.title,
    make,
    model,
    year,
    trim: listing.trim ?? null,
    bodyStyle: listing.bodyStyle ?? null,
    odometer: listing.odometer ?? null,
    condition: listing.condition ?? null,
    conditionScore,
    transmission: listing.transmission ?? null,
    state: listing.state ?? null,
    currency,
    askingPrice: listing.price,
    soldPrice,
    priceBasis: priceDropPct != null && priceDropPct > 0 ? 'price-drop' : 'asking-gap',
    priceDropPct,
    daysOnMarket,
    listedAt: basisDate,
    observedAt: opts.observedAt ?? new Date(),
    confidence: 'medium',
    evidence: {
      previousPrice: listing.previousPrice ?? null,
      lastSeenAt: lastSeen.getTime(),
      gapAppliedPct,
      titleStatus: listing.titleStatus ?? null,
      daysOnMarket,
    },
  })
}

/** A listing was re-surfaced after going stale — the "sale" never happened.
 *  Remove its inferred observation so it cannot poison the sold pool. */
export async function removeSaleObservationsForListings(
  db: PrismaClient,
  listingIds: string[]
): Promise<number> {
  if (listingIds.length === 0) return 0
  const res = await db.saleObservation
    .deleteMany({ where: { listingId: { in: listingIds } } })
    .catch(() => ({ count: 0 }))
  if (res.count > 0) invalidateSalePool()
  return res.count
}

// ---------------------------------------------------------------------------
// Estimation
// ---------------------------------------------------------------------------

interface Candidate {
  row: SaleObservationRow
  tier: 0 | 1 | 2
  weight: number
  adjusted: number
  yearFactor: number
  odoFactor: number
  condFactor: number
  bodyMatch: boolean | null
}

interface Rates {
  yearRate: number
  kmRate: number
}

function fitRates(rows: SaleObservationRow[], currency: string): Rates {
  const family = rows.filter(
    (r) => r.currency === currency && r.soldPrice >= currencyFloor(r.currency)
  )
  // Year curve: same family first; fall back to the whole same-make pool.
  const yearRows = family
    .filter((r) => r.year != null && r.year >= 1985)
    .map((r) => ({ x: r.year!, y: Math.log(r.soldPrice) }))
  const yearSpread =
    yearRows.length >= 3
      ? Math.max(...yearRows.map((r) => r.x)) - Math.min(...yearRows.map((r) => r.x))
      : 0
  let yearRate = FALLBACK_YEAR_RATE
  if (yearRows.length >= 5 && yearSpread >= 2) {
    const slope = theilSenSlope(yearRows)
    if (slope != null) yearRate = clamp(-slope, YEAR_RATE_MIN, YEAR_RATE_MAX)
  }

  // Odometer curve: needs real spread, otherwise the fallback is safer.
  const odoRows = family
    .filter((r) => r.odometer != null && r.odometer > 0)
    .map((r) => ({ x: r.odometer!, y: Math.log(r.soldPrice) }))
  const odoSpread =
    odoRows.length >= 3
      ? Math.max(...odoRows.map((r) => r.x)) - Math.min(...odoRows.map((r) => r.x))
      : 0
  let kmRate = FALLBACK_KM_RATE
  if (odoRows.length >= 5 && odoSpread >= 20_000) {
    const slope = theilSenSlope(odoRows)
    if (slope != null) kmRate = clamp(-slope, KM_RATE_MIN, KM_RATE_MAX)
  }

  return { yearRate, kmRate }
}

/**
 * Estimate the subject's expected SALE value from durable sale observations.
 * Returns null when there is no usable sold evidence in the subject's market.
 */
export async function estimateFromSaleComps(
  db: PrismaClient,
  subject: SaleSubject
): Promise<SaleCompEstimate | null> {
  const makeKey = normalizeKey(subject.make)
  const modelKey = normalizeKey(subject.model)
  if (!makeKey || !modelKey) return null

  const currency = (subject.currency ?? 'AUD').toUpperCase()
  const floor = currencyFloor(currency)
  const pool = await getSaleObservationRows(db)
  const marketRows = pool.filter((r) => r.currency === currency && r.soldPrice >= floor)
  if (marketRows.length === 0) return null

  const familyRows = marketRows.filter(
    (r) => normalizeKey(r.make) === makeKey && normalizeKey(r.model) === modelKey
  )
  const makeRows = marketRows.filter((r) => normalizeKey(r.make) === makeKey)
  const rateRows = familyRows.length >= 5 ? familyRows : makeRows
  const rates = fitRates(rateRows, currency)

  const subjectBody = bodyStyleKey(subject.bodyStyle, subject.title)
  const subjectCondition = analyzeCondition({
    title: subject.title ?? '',
    description: null,
    condition: subject.condition ?? null,
    odometer: subject.odometer ?? null,
    year: subject.year ?? null,
    titleStatus: null,
  }).score

  const candidates: Candidate[] = []
  for (const row of marketRows) {
    if (subject.id && row.listingId === subject.id) continue
    const rowMake = normalizeKey(row.make)
    const rowModel = normalizeKey(row.model)
    const sameMake = rowMake === makeKey
    const sameModel = rowModel === modelKey
    const rowBody = bodyStyleKey(row.bodyStyle, row.title)
    const bodyMatch =
      subjectBody && rowBody ? subjectBody === rowBody : subjectBody || rowBody ? null : null

    let tier: 0 | 1 | 2 | null = null
    if (sameMake && sameModel) tier = 0
    else if (sameMake && bodyMatch === true) tier = 1
    else if (sameMake && bodyMatch === null) tier = 1
    else if (bodyMatch === true && !sameMake) tier = 2
    if (tier == null) continue

    const yearDiff = subject.year != null && row.year != null ? row.year - subject.year : null
    const yearFactor =
      yearDiff != null ? clamp(Math.pow(1 - rates.yearRate, yearDiff), 0.55, 1.45) : 1

    const odoDiff =
      subject.odometer != null && row.odometer != null ? row.odometer - subject.odometer : null
    const odoFactor = odoDiff != null ? clamp(1 - rates.kmRate * odoDiff, 0.6, 1.4) : 1

    const compCondition = row.conditionScore ?? 0
    const condFactor = clamp(
      1 + CONDITION_WEIGHT * (subjectCondition - compCondition),
      0.85,
      1.15
    )

    const transmissionFactor =
      subject.transmission && row.transmission
        ? normalizeKey(subject.transmission) === normalizeKey(row.transmission)
          ? 1
          : 0.98
        : 1

    const adjusted = row.soldPrice * yearFactor * odoFactor * condFactor * transmissionFactor
    if (!(adjusted > 0)) continue

    const baseWeight =
      tier === 0
        ? TIER_WEIGHT.exact
        : tier === 1
          ? bodyMatch === true
            ? TIER_WEIGHT.sameMakeBody
            : TIER_WEIGHT.sameMakeUnknownBody
          : TIER_WEIGHT.sameBodyOtherMake

    const yearWeight =
      yearDiff != null ? Math.max(0.15, 1 - Math.min(1, Math.abs(yearDiff) / 12)) : 0.8
    const odoWeight =
      odoDiff != null ? Math.max(0.25, 1 - Math.min(1, Math.abs(odoDiff) / 180_000)) : 0.8
    const stateWeight =
      subject.state && row.state
        ? normalizeKey(subject.state) === normalizeKey(row.state)
          ? 1
          : 0.85
        : 0.95
    const confidenceWeight =
      row.confidence === 'high' ? 1.1 : row.confidence === 'low' ? 0.7 : 1
    const bodyWeight = tier === 0 && bodyMatch === false ? 0.85 : 1

    const weight =
      baseWeight *
      yearWeight *
      odoWeight *
      stateWeight *
      confidenceWeight *
      bodyWeight *
      soldRecencyWeight(row.observedAt)
    if (!(weight > 0)) continue

    candidates.push({
      row,
      tier,
      weight,
      adjusted,
      yearFactor,
      odoFactor,
      condFactor,
      bodyMatch,
    })
  }

  if (candidates.length === 0) return null

  // Wider (same-body, other-make) comps are a fallback, not a replacement for
  // exact-family evidence. Only keep the best handful when strong tiers are thin.
  const strongCount = candidates.filter((c) => c.tier <= 1).length
  let entries = candidates
  if (strongCount >= 2) entries = candidates.filter((c) => c.tier <= 1)
  else {
    const wide = candidates
      .filter((c) => c.tier === 2)
      .sort((a, b) => b.weight - a.weight)
      .slice(0, 8)
    entries = [...candidates.filter((c) => c.tier <= 1), ...wide]
  }

  // Outlier clip: one parts-grade sale must not reprice the family. The MAD
  // guard only engages with enough rows to have a meaningful centre.
  if (entries.length >= 5) {
    const centre = median(entries.map((e) => e.adjusted))
    if (centre != null && centre > 0) {
      const mad = median(entries.map((e) => Math.abs(e.adjusted - centre))) ?? 0
      const threshold = Math.max(centre * 0.4, mad * 3)
      entries = entries.filter((e) => Math.abs(e.adjusted - centre) <= threshold)
    }
  }
  if (entries.length === 0) return null

  const weighted = entries.map((e) => ({ value: e.adjusted, weight: e.weight }))
  const med = weightedMedian(weighted)
  const mean = weightedMean(weighted)
  if (med == null || mean == null || !(med > 0)) return null

  // Robust centre with a small mean nudge (median dominates; the mean keeps a
  // tight cluster from being dragged by a single middle observation).
  let value = med * 0.8 + mean * 0.2
  value = clamp(value, med * 0.75, med * 1.25)

  const q1 = weightedQuantile(weighted, 0.25)
  const q3 = weightedQuantile(weighted, 0.75)
  const iqrPct =
    q1 != null && q3 != null && value > 0
      ? Math.round(((q3 - q1) / value) * 100)
      : null

  const weightTotal = entries.reduce((s, e) => s + e.weight, 0)
  const weightSquares = entries.reduce((s, e) => s + e.weight * e.weight, 0)
  const effectiveCount = weightSquares > 0 ? weightTotal * weightTotal / weightSquares : entries.length
  const exactCount = entries.filter((e) => e.tier === 0).length
  const widerCount = entries.length - exactCount

  let confidence: SaleConfidence = 'low'
  if (exactCount >= 4 && effectiveCount >= 2.5 && (iqrPct == null || iqrPct <= 45)) {
    confidence = 'high'
  } else if (exactCount >= 2 || effectiveCount >= 2) {
    confidence = 'medium'
  }

  let bandPct = iqrPct != null ? clamp(iqrPct * 0.65, 8, 35) : 20
  if (effectiveCount < 2) bandPct = Math.max(bandPct, 25)
  if (confidence === 'high') bandPct = Math.min(bandPct, 18)
  if (confidence === 'low') bandPct = Math.max(bandPct, 25)
  bandPct = Math.round(bandPct)

  const medianSoldPrice = weightedMedian(
    entries.map((e) => ({ value: e.row.soldPrice, weight: e.weight }))
  )
  const medianDaysToSell = weightedMedian(
    entries
      .filter((e) => e.row.daysOnMarket != null)
      .map((e) => ({ value: e.row.daysOnMarket!, weight: e.weight }))
  )

  const measuredGaps = marketRows
    .filter((r) => r.askingPrice != null && r.askingPrice > 0 && r.soldPrice > 0)
    .map((r) => ((r.askingPrice! - r.soldPrice) / r.askingPrice!) * 100)
    .filter((g) => g >= -5 && g <= 30)
  const askingGapPct =
    measuredGaps.length >= 2
      ? clamp(median(measuredGaps) ?? ASKING_TO_SALE_DISCOUNT_PCT, 0, 20)
      : ASKING_TO_SALE_DISCOUNT_PCT

  const askingEquivalent = value / Math.max(0.05, 1 - askingGapPct / 100)

  // Weighted average of the adjustment factors, for the "why" panel.
  const avg = (pick: (e: Candidate) => number) =>
    weightTotal > 0 ? entries.reduce((s, e) => s + pick(e) * e.weight, 0) / weightTotal : 1
  const yearAdjPct = Math.round((avg((e) => e.yearFactor) - 1) * 100)
  const odoAdjPct = Math.round((avg((e) => e.odoFactor) - 1) * 100)
  const condAdjPct = Math.round((avg((e) => e.condFactor) - 1) * 100)

  const money = (n: number) => formatMoneyCurrency(n, currency)
  const factors: SaleCompFactor[] = [
    {
      label: `${entries.length} comparable ${entries.length === 1 ? 'sale' : 'sales'}`,
      detail:
        `${exactCount} exact ${subject.make} ${subject.model}${widerCount > 0 ? ` + ${widerCount} wider ${subjectBody || 'body-style'} comps` : ''}` +
        (medianSoldPrice != null ? `; median sold price ${money(medianSoldPrice)}` : ''),
      impactPct: yearAdjPct !== 0 ? yearAdjPct : undefined,
    },
  ]
  if (yearAdjPct !== 0 || odoAdjPct !== 0 || condAdjPct !== 0) {
    factors.push({
      label: 'Sold prices adjusted to this car',
      detail: `Year ${yearAdjPct >= 0 ? '+' : ''}${yearAdjPct}%, odometer ${odoAdjPct >= 0 ? '+' : ''}${odoAdjPct}%, condition ${condAdjPct >= 0 ? '+' : ''}${condAdjPct}%`,
      impactPct: yearAdjPct + odoAdjPct + condAdjPct,
    })
  }
  if (medianDaysToSell != null) {
    factors.push({
      label: `Sells in ~${Math.round(medianDaysToSell)} days`,
      detail: `Median time-on-market across the sold evidence for this ${subjectBody || 'segment'}`,
    })
  }
  factors.push({
    label: `Asking→sale gap ${Math.round(askingGapPct)}%`,
    detail:
      measuredGaps.length >= 2
        ? `Measured across ${measuredGaps.length} sales where both the asking and transaction price are known`
        : `Typical private-sale discount applied to final asking prices`,
  })

  const sample = [...entries]
    .sort((a, b) => b.weight - a.weight)
    .slice(0, 3)
    .map((e) => ({
      title:
        e.row.title ??
        `${e.row.year ?? ''} ${e.row.make} ${e.row.model}`.replace(/\s+/g, ' ').trim(),
      price: Math.round(e.row.soldPrice),
      daysOnMarket: e.row.daysOnMarket,
      year: e.row.year,
      odometer: e.row.odometer,
      observedAt: e.row.observedAt.toISOString(),
      basis: e.row.priceBasis,
    }))

  return {
    value: round50(value),
    low: round50(value * (1 - bandPct / 100)),
    high: round50(value * (1 + bandPct / 100)),
    askingEquivalent: round50(askingEquivalent),
    compCount: entries.length,
    exactCount,
    widerCount,
    effectiveCount: Math.round(effectiveCount * 10) / 10,
    confidence,
    method: exactCount > 0 ? 'sold-comps' : 'sold-comps-wide',
    medianSoldPrice: medianSoldPrice != null ? round50(medianSoldPrice) : null,
    medianDaysToSell: medianDaysToSell != null ? Math.round(medianDaysToSell) : null,
    askingGapPct: Math.round(askingGapPct * 10) / 10,
    iqrPct,
    bandPct,
    yearRatePct: Math.round(rates.yearRate * 1000) / 10,
    odometerRatePerKm: rates.kmRate,
    factors,
    sample,
  }
}

