/** per-run cap for the vehicle-type sweep (rows are re-checked every pass) */
const VEHICLE_SWEEP_BATCH = 500
/** per-run cap for the stale sweep — each row is also written to the durable
 *  sale-observation store, so the batch keeps a pass light */
const SALE_SWEEP_BATCH = 500

// 2. stale sweep — active listings whose watchlists haven't re-surfaced
//    them for days. Comp-scoped: only listings the comp pool would
//    otherwise still count and the feed still shows.
//
//    Every row that leaves the market is also written to SaleObservation:
//    the final asking price (less the asking→sale gap) becomes durable sold
//    evidence that survives the listing itself. That is the strongest input
//    the valuation engine has — real prices for cars that actually sold,
//    not just asking prices for cars still sitting there.
const staleBefore = new Date(now.getTime() - STALE_AFTER_DAYS * 86_400_000)
const staleCandidates = await db.listing
  .findMany({
    where: {
      status: { in: ['new', 'saved'] },
      lastSeenAt: { lt: staleBefore },
    },
    select: {
      id: true,
      title: true,
      price: true,
      currency: true,
      description: true,
      condition: true,
      make: true,
      model: true,
      year: true,
      trim: true,
      bodyStyle: true,
      odometer: true,
      transmission: true,
      state: true,
      previousPrice: true,
      postedAt: true,
      firstSeenAt: true,
      lastSeenAt: true,
      titleStatus: true,
      vertical: true,
      marketplace: true,
      isScam: true,
    },
    take: SALE_SWEEP_BATCH,
  })
  .catch(() => [] as Array<any>)

let markedStale = 0
let recordedSales = 0
if (staleCandidates.length > 0) {
  const stale = await db.listing
    .updateMany({
      where: { id: { in: staleCandidates.map((r) => r.id) } },
      data: { status: 'stale' },
    })
    .catch(() => ({ count: 0 }))
  markedStale = stale.count
  if (markedStale > 0) {
    for (const row of staleCandidates) {
      try {
        const sale = await recordSaleFromListing(db, row)
        if (sale) recordedSales++
      } catch {
        // one bad observation must not stop the sweep
      }
    }
  }
}

