export interface SoldRow {
  id: string
  make: string
  model: string
  year: number | null
  price: number
  currency: string
  /** final asking price's predecessor — rows where the seller moved */
  previousPrice: number | null
  firstSeenAt: Date
  lastSeenAt: Date
  postedAt: Date | null
  /** full days the listing was on the market (approximation of time-to-sell) */
  daysOnMarket: number
  odometer?: number | null
  condition?: string | null
  bodyStyle?: string | null
  priceBasis?: string
}

let soldCache: { rowCount: number; loadedAt: number; rows: SoldRow[] } | null = null
const SOLD_POOL_TTL_MS = 60_000

/** Durable sale observations are the primary sold pool. The old stale-listing
 *  fallback stays for databases that predate SaleObservation (or a fresh
 *  install before its first sale is observed). */
export async function getSoldPool(db: PrismaClient): Promise<SoldRow[]> {
  const observations = await getSaleObservationRows(db)
  if (observations.length > 0) {
    return observations.map((o) => ({
      id: o.id,
      make: o.make,
      model: o.model,
      year: o.year,
      // market-intel's SoldRow.price is the SALE price (what the estimator
      // consumes), not the final asking price
      price: o.soldPrice,
      currency: o.currency,
      previousPrice:
        o.askingPrice != null && o.askingPrice > o.soldPrice ? o.askingPrice : null,
      firstSeenAt: o.listedAt ?? o.observedAt,
      lastSeenAt: o.observedAt,
      postedAt: o.listedAt,
      daysOnMarket:
        o.daysOnMarket ??
        Math.max(
          1,
          Math.round(
            (o.observedAt.getTime() - (o.listedAt ?? o.observedAt).getTime()) / 86_400_000
          )
        ),
      odometer: o.odometer,
      condition: o.condition,
      bodyStyle: o.bodyStyle,
      priceBasis: o.priceBasis,
    }))
  }

  const rowCount = await db.listing.count({ where: { status: 'stale', isScam: false, price: { gt: 500 } } })
  if (soldCache && soldCache.rowCount === rowCount && Date.now() - soldCache.loadedAt < SOLD_POOL_TTL_MS) {
    return soldCache.rows
  }
  const rows = await loadSoldPool(db)
  soldCache = { rowCount, loadedAt: Date.now(), rows }
  return rows
}

