  daysOnMarket: number
}

let soldCache: { rowCount: number; loadedAt: number; rows: SoldRow[] } | null = null
const SOLD_POOL_TTL_MS = 60_000

async function loadSoldPool(db: PrismaClient): Promise<SoldRow[]> {
  const rows = await db.listing.findMany({
    where: {
      status: 'stale',
      isScam: false,
      price: { not: null, gt: 500 },
    },
    select: {
      id: true,
      make: true,
      model: true,
      year: true,
      price: true,
      currency: true,
      previousPrice: true,
      firstSeenAt: true,
      lastSeenAt: true,
      postedAt: true,
    },
  })
  return rows.flatMap((r) => {
    if (r.price == null) return []
    const basis = r.postedAt ?? r.firstSeenAt
    const days = Math.max(1, Math.round((r.lastSeenAt.getTime() - basis.getTime()) / 86_400_000))
    return [{
      id: r.id,
      make: r.make ?? '',
      model: r.model ?? '',
      year: r.year,
      price: r.price,
      currency: r.currency ?? 'AUD',
      previousPrice: r.previousPrice,
      firstSeenAt: r.firstSeenAt,
      lastSeenAt: r.lastSeenAt,
      postedAt: r.postedAt,
      daysOnMarket: days,
    }]
  })
}

/** Cached sold pool — invalidated when the stale-listing count changes. */
export async function getSoldPool(db: PrismaClient): Promise<SoldRow[]> {
  const rowCount = await db.listing.count({ where: { status: 'stale', isScam: false, price: { gt: 500 } } })
  if (soldCache && soldCache.rowCount === rowCount && Date.now() - soldCache.loadedAt < SOLD_POOL_TTL_MS) {
    return soldCache.rows
  }
  const rows = await loadSoldPool(db)
  soldCache = { rowCount, loadedAt: Date.now(), rows }
  return rows
}

