// ---- durable sold evidence (cars that left the market) ---------------
// This is the strongest input: a real sale price adjusted to this exact
// car's year / odometer / condition beats any asking price still sitting
// on the market. The estimator returns a SALE value; askingEquivalent puts
// it back on the asking-price basis the fairValue blend uses.
const soldEstimate =
  make && model
    ? await estimateFromSaleComps(db, {
        id: listing.id,
        make,
        model,
        year,
        odometer: listing.odometer,
        condition: listing.condition,
        transmission: listing.transmission,
        state: listing.state,
        bodyStyle: listing.bodyStyle ?? null,
        title: listing.title,
        currency: listing.currency ?? null,
      })
    : null
const soldCount = soldEstimate?.compCount ?? 0
const soldSaleValue = soldEstimate?.value ?? null
const soldAskingEquivalent = soldEstimate?.askingEquivalent ?? null

// ---- blended fair value ----
const compFair =
  valuation && valuation.confidence !== 'low'
    ? valuation.estimatedValue
    : valuation?.baseMedian ?? null
const compCount = valuation?.compCount ?? 0
let baseFair: number | null = null
if (modelPred && compFair != null && compCount >= 3) {
  // comps get up to 65% weight as the sample grows; the model carries the
  // rest (and 100% when there are no same-family comps at all)
  const wComp = Math.min(0.65, compCount / 14)
  baseFair = wComp * compFair + (1 - wComp) * modelPred.fairValue
} else if (compFair != null && compCount >= 3) {
  baseFair = compFair
} else if (modelPred) {
  baseFair = modelPred.fairValue
}

// Sold evidence weight: more observations → more weight, but never let a
// single inferred sale outshout a full live comp set. Wider (same-body,
// other-make) comps and low-confidence observations are discounted.
let soldWeight = 0
let fairValue: number | null = baseFair
if (soldAskingEquivalent != null) {
  const countWeight =
    soldCount >= 5 ? 0.65 : soldCount >= 3 ? 0.55 : soldCount >= 2 ? 0.45 : 0.25
  const confidenceMult =
    soldEstimate?.confidence === 'high' ? 1 : soldEstimate?.confidence === 'low' ? 0.6 : 0.85
  const methodMult = soldEstimate?.method === 'sold-comps-wide' ? 0.6 : 1
  soldWeight = countWeight * confidenceMult * methodMult
  fairValue =
    baseFair != null
      ? soldWeight * soldAskingEquivalent + (1 - soldWeight) * baseFair
      : soldAskingEquivalent
}
fairValue = fairValue != null ? round50(fairValue) : null

// ---- confidence + band ----
const errorBandPct = modelPred?.errorBandPct ?? modelMeta?.report.errorBandPct ?? 20
let confidence: ConfidenceGrade = 'low'
if (fairValue != null) {
  if (modelPred && compCount >= 6 && valuation?.confidence === 'high') confidence = 'high'
  else if ((modelPred && compCount >= 2) || compCount >= 5) confidence = 'medium'
}
if (soldEstimate && soldWeight >= 0.4) {
  if (soldEstimate.confidence === 'high') confidence = 'high'
  else if (soldEstimate.confidence === 'medium' && confidence === 'low') confidence = 'medium'
}
let bandPct =
  confidence === 'high' ? errorBandPct * 0.7 : confidence === 'medium' ? errorBandPct : errorBandPct * 1.25
// Real transaction evidence usually narrows the band — never widen it.
if (soldEstimate && soldWeight >= 0.4) {
  bandPct = Math.min(bandPct, soldEstimate.bandPct)
}
bandPct = Math.max(8, bandPct)
const fairValueLow = fairValue != null ? round50(fairValue * (1 - bandPct / 100)) : null
const fairValueHigh = fairValue != null ? round50(fairValue * (1 + bandPct / 100)) : null

