input.content:
/**
 * Import real sale observations from a CSV — the fastest way to give the
 * valuation engine genuine transaction evidence before the scanner has watched
 * enough listings sell.
 *
 * Usage:
 *   bun scripts/import-sales.ts path/to/sales.csv
 *   bun scripts/import-sales.ts --from-stale          # backfill from stale listings
 *   bun scripts/import-sales.ts sales.csv --from-stale
 *
 * CSV headers are flexible (case/spacing-insensitive). Recognised fields:
 *   make/brand, model, year, odometer/kms, soldPrice/price, askingPrice,
 *   currency, state, condition, transmission, bodyStyle, trim, daysOnMarket,
 *   date/soldDate, source, title, listingId, externalId
 *
 * Rows are idempotent: the same sale imported twice updates its one
 * SaleObservation (source='import' + a deterministic externalId).
 */

import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { PrismaClient } from '@prisma/client'
import {
  recordSaleFromListing,
  recordSaleObservation,
} from '../src/lib/pricing/sale-comps'
import { parseVehicleTitle } from '../src/lib/vehicle'

const db = new PrismaClient()
const args = process.argv.slice(2)
const fromStale = args.includes('--from-stale')
const csvPath = args.find((a) => !a.startsWith('--'))

function parseCsv(text: string): string[][] {
  const rows: string[][] = []
  let row: string[] = []
  let field = ''
  let inQuotes = false
  const src = text.replace(/^\uFEFF/, '')
  for (let i = 0; i < src.length; i++) {
    const ch = src[i]
    if (inQuotes) {
      if (ch === '"') {
        if (src[i + 1] === '"') {
          field += '"'
          i++
        } else {
          inQuotes = false
        }
      } else {
        field += ch
      }
      continue
    }
    if (ch === '"') {
      inQuotes = true
    } else if (ch === ',') {
      row.push(field)
      field = ''
    } else if (ch === '\n') {
      row.push(field)
      if (row.some((v) => v.trim() !== '')) rows.push(row)
      row = []
      field = ''
    } else if (ch !== '\r') {
      field += ch
    }
  }
  row.push(field)
  if (row.some((v) => v.trim() !== '')) rows.push(row)
  return rows
}

function normHeader(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '')
}

function makePicker(headers: string[]) {
  const index = new Map<string, number>()
  headers.forEach((h, i) => index.set(normHeader(h), i))
  return (row: string[], aliases: string[]): string | null => {
    for (const alias of aliases) {
      const i = index.get(normHeader(alias))
      if (i != null) {
        const v = row[i]
        if (v != null && v.trim() !== '') return v.trim()
      }
    }
    return null
  }
}

function parseNumber(raw: string | null): number | null {
  if (!raw) return null
  const cleaned = raw.replace(/[^0-9.\-kKmM]/g, '')
  if (!cleaned) return null
  let multiplier = 1
  let body = cleaned
  if (/k$/i.test(body)) {
    multiplier = 1_000
    body = body.slice(0, -1)
  } else if (/m$/i.test(body)) {
    multiplier = 1_000_000
    body = body.slice(0, -1)
  }
  const n = Number.parseFloat(body)
  return Number.isFinite(n) ? n * multiplier : null
}

function parseDate(raw: string | null): Date | null {
  if (!raw) return null
  const d = new Date(raw)
  return Number.isFinite(d.getTime()) ? d : null
}

function externalIdFor(parts: Array<string | number | null | undefined>): string {
  return createHash('sha1').update(parts.map((p) => String(p ?? '')).join('|')).digest('hex').slice(0, 24)
}

async function importCsv(path: string): Promise<{ ok: number; skipped: number }> {
  const text = readFileSync(path, 'utf8')
  const rows = parseCsv(text)
  if (rows.length < 2) {
    console.log('[import-sales] CSV has no data rows')
    return { ok: 0, skipped: 0 }
  }
  const headers = rows[0]
  const pick = makePicker(headers)
  let ok = 0
  let skipped = 0

  for (let r = 1; r < rows.length; r++) {
    const row = rows[r]
    const title = pick(row, ['title', 'description', 'name'])
    const parsed = title ? parseVehicleTitle(title) : null
    const make = pick(row, ['make', 'brand', 'manufacturer']) ?? parsed?.make ?? null
    const model = pick(row, ['model']) ?? parsed?.model ?? null
    const year = parseNumber(pick(row, ['year', 'modelyear'])) ?? parsed?.year ?? null
    const odometer = parseNumber(pick(row, ['odometer', 'odo', 'kms', 'km', 'kilometres', 'kilometers', 'mileage']))
    const soldPrice = parseNumber(
      pick(row, ['soldprice', 'saleprice', 'finalprice', 'transactionprice', 'price', 'sold'])
    )
    const askingPrice = parseNumber(
      pick(row, ['askingprice', 'listprice', 'advertisedprice', 'askprice', 'asking'])
    )
    const currency = (pick(row, ['currency', 'ccy']) ?? 'AUD').toUpperCase()
    const state = pick(row, ['state', 'region'])
    const condition = pick(row, ['condition'])
    const transmission = pick(row, ['transmission', 'gearbox'])
    const bodyStyle = pick(row, ['bodystyle', 'body', 'style'])
    const trim = pick(row, ['trim', 'variant', 'badge'])
    const daysOnMarket = parseNumber(pick(row, ['daysonmarket', 'dom', 'daystosell', 'daystosell']))
    const observedAt =
      parseDate(pick(row, ['date', 'solddate', 'saledate', 'observedat', 'transactiondate'])) ??
      new Date()
    const source = pick(row, ['source', 'channel']) ?? 'csv'
    const listingId = pick(row, ['listingid', 'fblistingid'])
    const externalId =
      pick(row, ['externalid', 'saleid', 'transactionid']) ??
      externalIdFor([
        make,
        model,
        year,
        odometer,
        soldPrice ?? askingPrice,
        observedAt.toISOString().slice(0, 10),
        source,
      ])

    if ((!make || !model) && !title) {
      skipped++
      continue
    }
    if (soldPrice == null && askingPrice == null) {
      skipped++
      continue
    }

    try {
      const sale = await recordSaleObservation(db, {
        listingId: listingId ?? null,
        externalId,
        source: 'import',
        vertical: 'vehicles',
        marketplace: 'Import',
        title: title ?? null,
        make,
        model,
        year,
        trim,
        bodyStyle,
        odometer,
        condition,
        transmission,
        state,
        currency,
        askingPrice,
        soldPrice,
        priceBasis: soldPrice != null ? 'actual' : 'asking-gap',
        daysOnMarket,
        observedAt,
        confidence: soldPrice != null ? 'high' : 'medium',
        evidence: {
          originalSource: source,
          importedFrom: path,
          row: r + 1,
        },
      })
      if (sale) ok++
      else skipped++
    } catch (e) {
      skipped++
      console.warn(`[import-sales] row ${r + 1} failed:`, e instanceof Error ? e.message : e)
    }
  }
  return { ok, skipped }
}

async function backfillFromStale(): Promise<number> {
  const rows = await db.listing.findMany({
    where: { status: 'stale', isScam: false, price: { not: null, gt: 500 } },
    select: {
      id: true,
      title: true,
      price: true,
      currency: true,
      description: true,
      condition: true,
      make: true,
      model: true,
      year: true,
      trim: true,
      bodyStyle: true,
      odometer: true,
      transmission: true,
      state: true,
      previousPrice: true,
      postedAt: true,
      firstSeenAt: true,
      lastSeenAt: true,
      titleStatus: true,
      vertical: true,
      marketplace: true,
      isScam: true,
    },
  })
  let ok = 0
  for (const row of rows) {
    try {
      const sale = await recordSaleFromListing(db, row, { source: 'stale-sweep' })
      if (sale) ok++
    } catch {
      // one bad row must not stop the backfill
    }
  }
  return ok
}

try {
  if (fromStale) {
    const n = await backfillFromStale()
    console.log(`[import-sales] backfilled ${n} sale observation(s) from stale listings`)
  }
  if (csvPath) {
    const { ok, skipped } = await importCsv(csvPath)
    console.log(`[import-sales] imported ${ok} sale observation(s), skipped ${skipped} row(s)`)
  }
  if (!fromStale && !csvPath) {
    console.log(
      'Usage: bun scripts/import-sales.ts path/to/sales.csv [--from-stale]\n' +
        '       bun scripts/import-sales.ts --from-stale'
    )
  }
} finally {
  await db.$disconnect()
}

