/**
 * End-to-end check: does durable sold evidence actually reach the deal-room
 * payload?
 *
 * Picks a real listing from the dev DB, inserts a temporary same-family sold
 * set, runs the full analyzePricing pipeline, asserts the sold block and
 * expected-resale basis are wired through, then removes every temporary row.
 *
 *   bun scripts/check-valuation-integration.ts
 */

import { PrismaClient } from '@prisma/client'
import { analyzePricing } from '../src/lib/pricing/analyze'
import { invalidateSalePool } from '../src/lib/pricing/sale-comps'
import { invalidateCompPool } from '../src/lib/comps'

const db = new PrismaClient()
const SOURCE = 'integration-check'
const now = Date.now()

async function main() {
  const listing = await db.listing.findFirst({
    where: {
      vertical: 'vehicles',
      status: { in: ['new', 'saved'] },
      make: { not: null },
      model: { not: null },
      price: { gt: 2000 },
      year: { not: null },
      odometer: { gt: 0 },
      currency: 'AUD',
    },
    orderBy: { price: 'desc' },
  })
  if (!listing) {
    console.log('[integration] no suitable listing in the DB — skipped')
    return
  }
  console.log(
    `[integration] subject: ${listing.title} — ${listing.year} ${listing.make} ${listing.model}, ` +
      `${listing.odometer} km, ${listing.price} ${listing.currency}`
  )

  // Six plausible sales around the subject's year/odometer, ±1 year and
  // ±30,000 km, all priced near the subject's asking band.
  const basePrice = listing.price ?? 15_000
  const rows = [
    { dy: -2, dkm: 30_000, price: 0.86, dom: 52 },
    { dy: -1, dkm: 15_000, price: 0.93, dom: 38 },
    { dy: 0, dkm: 8_000, price: 0.97, dom: 27 },
    { dy: 0, dkm: -12_000, price: 1.04, dom: 21 },
    { dy: 1, dkm: -25_000, price: 1.1, dom: 18 },
    { dy: 1, dkm: 22_000, price: 1.02, dom: 33 },
  ]
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i]
    const year = (listing.year ?? 2015) + r.dy
    const odometer = Math.max(5_000, (listing.odometer ?? 120_000) + r.dkm)
    const soldPrice = Math.round(basePrice * r.price)
    await db.saleObservation.create({
      data: {
        source: SOURCE,
        externalId: `integration-${i}`,
        vertical: 'vehicles',
        marketplace: 'IntegrationCheck',
        title: `${year} ${listing.make} ${listing.model}`,
        make: listing.make,
        model: listing.model,
        year,
        bodyStyle: listing.bodyStyle,
        odometer,
        condition: listing.condition,
        conditionScore: 0,
        transmission: listing.transmission,
        state: listing.state,
        currency: listing.currency ?? 'AUD',
        askingPrice: Math.round(soldPrice * 1.06),
        soldPrice,
        priceBasis: 'actual',
        daysOnMarket: r.dom,
        listedAt: new Date(now - r.dom * 86_400_000),
        observedAt: new Date(now - (i + 1) * 5 * 86_400_000),
        confidence: 'high',
        evidence: JSON.stringify({ integration: true }),
      },
    })
  }
  invalidateSalePool()
  invalidateCompPool()

  const { analysis } = await analyzePricing(db, listing)
  console.log('[integration] soldValuation:', analysis.soldValuation)
  console.log('[integration] fairValue:', analysis.fairValue, analysis.fairValueLow, analysis.fairValueHigh)
  console.log('[integration] valuationSource:', analysis.valuationSource)
  console.log('[integration] expectedResale:', analysis.flipEconomics)

  const sold = analysis.soldValuation
  if (!sold) throw new Error('soldValuation missing from PricingAnalysis')
  if (sold.compCount < 5) throw new Error(`expected >=5 sold comps, got ${sold.compCount}`)
  if (sold.estimatedValue == null || sold.askingEquivalent == null) {
    throw new Error('soldValuation is missing its value/askingEquivalent')
  }
  if (sold.askingEquivalent <= sold.estimatedValue) {
    throw new Error('askingEquivalent must exceed the expected sale value')
  }
  if (analysis.fairValue == null) throw new Error('fairValue missing')
  if (analysis.flipEconomics?.expectedResaleBasis !== 'sold-comps') {
    throw new Error(
      `expected resale should be sold-backed, got ${analysis.flipEconomics?.expectedResaleBasis ?? 'none'}`
    )
  }
  if (!analysis.valuationFactors?.some((f) => /comparable sale/i.test(f.label))) {
    throw new Error('valuationFactors should describe the sold evidence')
  }
  console.log('✓ sold evidence flows through analyzePricing')
}

try {
  await main()
} finally {
  await db.saleObservation.deleteMany({ where: { source: SOURCE } }).catch(() => ({ count: 0 }))
  invalidateSalePool()
  await db.$disconnect()
}

