/* -------------------------------- sessions ------------------------------- */

function hashToken(token: string): string {
  return createHash('sha256').update(token).digest('hex')
}

/** Create a DB session row and return the raw token for the cookie. */
export async function createAuthSession(userId: string): Promise<{ token: string; expiresAt: Date }> {
  // opportunistically sweep expired sessions (cheap, indexed)
  await db.authSession.deleteMany({ where: { expiresAt: { lt: new Date() } } }).catch(() => {})

  const token = randomBytes(32).toString('hex')
  const expiresAt = new Date(Date.now() + SESSION_TTL_DAYS * 24 * 60 * 60 * 1000)
  await db.authSession.create({
    data: { tokenHash: hashToken(token), userId, expiresAt },
  })
  return { token, expiresAt }
}

export function sessionCookieOptions(expiresAt: Date, https = false) {
  // HTTPS (preview panel / production): SameSite=None + Secure so embedded
  // iframe contexts are allowed to store the cookie. Plain-HTTP local dev
  // keeps Lax — the browser refuses Secure cookies over http.
  return {
    httpOnly: true,
    sameSite: (https ? 'none' : 'lax') as 'none' | 'lax',
    secure: https,
    path: '/',
    expires: expiresAt,
  }
}

/** Serialize + attach the session cookie with FULL attribute control.
