let valueBasis = analysis.fairValue ?? stats.median
let estimate: EstimateResult | null = null
let intel: MarketIntel | null = null
// A fair value already backed by >=2 durable sale observations is NOT a
// weak analysis — the external web/model ladder must not overwrite real
// transaction evidence just because the live comp count is thin.
const soldBacked =
  analysis.valuationSource === 'sold-comps' &&
  (analysis.soldValuation?.compCount ?? 0) >= 2
if (
  !soldBacked &&
  (valueBasis == null || (stats.count < 3 && !analysis.modelAvailable)) &&
  listing.price !== null
) {

  if (!analysis.valuationFactors?.some((f) => /comparable sale/i.test(f.label))) {
    throw new Error('valuationFactors should describe the sold evidence')
  }
  console.log('✓ sold evidence flows through analyzePricing')

  // ---- scanner / maintenance path: scoreListing → persistScore ----------
  // Snapshot the score columns so the dev DB is left exactly as it was.
  const before = await db.listing.findUniqueOrThrow({ where: { id: listing.id } })
  try {
    const score = await scoreListing(db, listing)
    await persistScore(db, listing.id, score)
    const stored = await db.listing.findUniqueOrThrow({ where: { id: listing.id } })
    const storedPricing = stored.pricingJson ? JSON.parse(stored.pricingJson) : null
    if (!storedPricing) throw new Error('pricingJson missing after persistScore')
    console.log('[integration] stored valuationSource:', storedPricing.valuationSource)
    console.log('[integration] stored soldValuation compCount:', storedPricing.soldValuation?.compCount)
    if (storedPricing.valuationSource !== 'sold-comps') {
      throw new Error(`stored valuationSource should be sold-comps, got ${storedPricing.valuationSource}`)
    }
    if ((storedPricing.soldValuation?.compCount ?? 0) < 5) {
      throw new Error('stored pricingJson should carry the sold evidence')
    }
    if (storedPricing.flipEconomics?.expectedResaleBasis !== 'sold-comps') {
      throw new Error('stored expectedResaleBasis should be sold-comps')
    }
    console.log('✓ scanner scoring path stores sold evidence')
  } finally {
    await db.listing.update({
      where: { id: listing.id },
      data: {
        vertical: before.vertical,
        make: before.make,
        model: before.model,
        year: before.year,
        dealRating: before.dealRating,
        isScam: before.isScam,
        scamFlags: before.scamFlags,
        marketAvg: before.marketAvg,
        marketMedian: before.marketMedian,
        marketLow: before.marketLow,
        marketHigh: before.marketHigh,
        compCount: before.compCount,
        potentialProfit: before.potentialProfit,
        savingsPct: before.savingsPct,
        roiPct: before.roiPct,
        estimatedValue: before.estimatedValue,
        valueLow: before.valueLow,
        valueHigh: before.valueHigh,
        valuationConfidence: before.valuationConfidence,
        valuationJson: before.valuationJson,
        pricingJson: before.pricingJson,
        scoredAt: before.scoredAt,
      },
    })
    invalidateCompPool()
  }
}

