```ts
import { filterComps, filterGenericComps, type CompRow } from './comps'
import { currencyFloor } from './currency'
import { extractItemIdentity } from './item-identity'
import { auBaselineValue } from './pricing/au-baseline'
import { analyzeCondition } from './valuation'
import {
  isLikelyPartsListing, isPartsOrWreckListing, isPlaceholderPrice,
  isRoadVehicleListing, parseVehicleTitle,
} from './vehicle'

export interface ScanCandidate {
  listingId: string
  title: string
  price: number | null
  currency?: string | null
  strikethroughPrice?: number | null
  postedAt?: Date | null
  categoryId?: string | null
  /** watchlist vertical (or the classifier's fallback) */
  vertical: string
}

export interface RankedScanCandidate extends ScanCandidate {
  rankScore: number
  /** estimated discount vs the local live market, % (positive = below market) */
  estimatedDiscountPct: number | null
  /** how many live comps anchored the discount (0 = no anchor) */
  anchorCount: number
  /** one-line human explanation for scan logs */
  rankReason: string
}

export interface RankContext {
  pool: CompRow[]
  /** market currency for the scan (candidate.currency wins when present) */
  currency: string
  /** reference time for freshness (tests can pin it) */
  now?: number
}

function median(values: number[]): number | null { ... }

function clamp(v,min,max) {...}

export function rankScanCandidates(candidates: ScanCandidate[], ctx: RankContext): RankedScanCandidate[] {
  const out: RankedScanCandidate[] = []
  for (const c of candidates) {
    // never spend one of the 5 slots on something the pipeline will hide
    if (isPlaceholderPrice(c.price)) continue
    if (isPartsOrWreckListing(c.title)) continue
    const vertical = c.vertical || 'vehicles'
    if (vertical === 'vehicles' && !isRoadVehicleListing({ title: c.title, categoryId: c.categoryId ?? null })) continue

    const currency = (c.currency ?? ctx.currency ?? 'AUD').toUpperCase()
    const floor = currencyFloor(currency)
    const price = c.price != null && c.price > 0 ? c.price : null

    let discount: number | null = null
    let anchorCount = 0
    let reason = 'no local comps yet'
    let anchorWeight = 0

    if (price != null) {
      if (vertical === 'vehicles') {
        const parsed = parseVehicleTitle(c.title)
        const year = parsed.year
        const family = parsed.make && parsed.model
          ? filterComps(ctx.pool, { id: '', make: parsed.make, model: parsed.model, year, currency }, 4, { currencyFloor })
          : []
        if (family.length >= 2) {
          const med = median(family.map(x => x.price))
          if (med && med > 0) {
            discount = (med - price) / med
            anchorCount = family.length
            anchorWeight = 1
            reason = `${family.length} live ${parsed.make} ${parsed.model} comps @ ${Math.round(med).toLocaleString()}`
          }
        }
        if (discount == null && parsed.make) {
          const makeRows = ctx.pool.filter(row => {
            if (normalizeKey(row.make) !== normalizeKey(parsed.make)) return false
            if ((row.currency ?? 'AUD').toUpperCase() !== currency) return false
            if (row.price < floor) return false
            if (row.year != null && year != null && Math.abs(row.year - year) > 4) return false
            return true
          })
          if (makeRows.length >= 4) {
            const med = median(makeRows.map(x => x.price))
            if (med && med > 0) {
              discount = (med - price) / med
              anchorCount = makeRows.length
              anchorWeight = 0.45
              reason = `${makeRows.length} live ${parsed.make} comps (model-level evidence thin)`
            }
          }
        }
        if (discount == null && currency === 'AUD' && parsed.make && year != null) {
          const baseline = auBaselineValue(parsed.make, new Date(ctx.now ?? Date.now()).getFullYear() - year)
          if (baseline) {
            discount = (baseline.value - price) / baseline.value
            anchorCount = 1
            anchorWeight = 0.3
            reason = `AU baseline for a ${...}-year-old ${parsed.make}`
          }
        }
      } else {
        const identity = extractItemIdentity(vertical, c.title)
        const comps = filterGenericComps(ctx.pool, {
          id: '', vertical, brand: identity.brand, tokens: identity.tokens,
          currency, role: identity.role, title: c.title,
        }, { currencyFloor })
        if (comps.length >= 2) {
          const med = median(comps.map(x => x.price))
          if (med && med > 0) {
            discount = (med - price) / med
            anchorCount = comps.length
            anchorWeight = 1
            reason = `${comps.length} live ${identity.brand ?? 'same-product'} comps`
          }
        }
      }
    }

    const condition = analyzeCondition({
      title: c.title, description: null, condition: null,
      odometer: null, year: parseVehicleTitle(c.title).year ?? null, titleStatus: null,
    }).score

    const dropPct = c.strikethroughPrice != null && price != null && c.strikethroughPrice > price
      ? clamp((c.strikethroughPrice - price) / c.strikethroughPrice, 0, 0.25)
      : 0

    const ageDays = c.postedAt ? Math.max(0, ((ctx.now ?? Date.now()) - c.postedAt.getTime()) / 86_400_000) : null
    const freshness = ageDays == null ? 0 : ageDays <= 2 ? 0.03 : ageDays <= 7 ? 0.02 : ageDays <= 30 ? 0.01 : 0

    const rankScore =
      price == null
        ? -1
        : clamp(discount ?? 0, -0.6, 0.6) * anchorWeight +
          dropPct * 0.3 +
          clamp(condition, -1, 1) * 0.02 +
          freshness

    out.push({
      ...c,
      rankScore: Math.round(rankScore * 10000) / 10000,
      estimatedDiscountPct: discount != null ? Math.round(discount * 1000) / 10 : null,
      anchorCount,
      rankReason: price == null ? 'no price in search results' : reason,
    })
  }

  out.sort((a,b) =>
    b.rankScore - a.rankScore ||
    b.anchorCount - a.anchorCount ||
    (b.postedAt?.getTime() ?? 0) - (a.postedAt?.getTime() ?? 0) ||
    a.listingId.localeCompare(b.listingId)
  )
  return out
}
