/**
 * Per-scan candidate ranking — the "keep the 5 best new listings" gate.
 *
 * A marketplace search routinely returns dozens of listings the scanner has
 * never seen. Ingesting every one of them floods the feed, spends the scan's
 * request/time budget on cars the user never opens, and pushes the scan past
 * its cadence. This module ranks the fresh candidates BEFORE any write or
 * detail fetch, so a scan only pulls the best N:
 *
 *   1. discount vs same make+model live comps (the strongest signal)
 *   2. fallback: same-make comps, then the curated AU baseline (weaker anchor)
 *   3. advertised price drop (strikethrough → current price)
 *   4. title condition signals (service history, damage words, …)
 *   5. freshness (a just-posted listing is more likely still available)
 *
 * Junk is dropped outright: placeholder prices, explicit parts/wrecks and
 * non-road vehicles — exactly what the post-enrichment pipeline would hide.
 * Unpicked candidates stay undiscovered; the next scan sees them again and
 * gives the next-best batch its turn.
 *
 * The function is pure (pool passed in) so it can be tested without touching
 * the database.
 */

import { filterComps, filterGenericComps, normalizeKey, type CompRow } from './comps'
import { currencyFloor } from './currency'
import { extractItemIdentity } from './item-identity'
import { auBaselineValue } from './pricing/au-baseline'
import { analyzeCondition } from './valuation'
import {
  isPartsOrWreckListing,
  isPlaceholderPrice,
  isRoadVehicleListing,
  parseVehicleTitle,
} from './vehicle'

export interface ScanCandidate {
  listingId: string
  title: string
  price: number | null
  /** marketplace currency when the search row exposes one */
  currency?: string | null
  /** original (crossed-out) price — a real seller markdown */
  strikethroughPrice?: number | null
  postedAt?: Date | null
  categoryId?: string | null
  /** watchlist vertical (or the classifier's fallback) */
  vertical: string
}

export interface RankedScanCandidate extends ScanCandidate {
  rankScore: number
  /** estimated discount vs the local live market, % (positive = below market) */
  estimatedDiscountPct: number | null
  /** how many live comps anchored the discount (0 = no anchor) */
  anchorCount: number
  /** one-line explanation for scan logs */
  rankReason: string
}

export interface RankContext {
  pool: CompRow[]
  /** scan market currency (candidate.currency wins when present) */
  currency: string
  /** reference time for freshness (tests can pin it) */
  now?: number
}

function median(values: number[]): number | null {
  if (values.length === 0) return null
  const sorted = [...values].sort((a, b) => a - b)
  const mid = Math.floor(sorted.length / 2)
  return sorted.length % 2 === 0 ? (sorted[mid - 1] + sorted[mid]) / 2 : sorted[mid]
}

function clamp(v: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, v))
}

/** A candidate the pipeline would hide anyway must never consume one of the
 *  N slots (parts listings, placeholder "$1234" prices, motorbikes/boats). */
function isJunk(candidate: ScanCandidate, vertical: string): boolean {
  if (isPlaceholderPrice(candidate.price)) return true
  if (isPartsOrWreckListing(candidate.title)) return true
  if (vertical === 'vehicles') {
    return !isRoadVehicleListing({
      title: candidate.title,
      categoryId: candidate.categoryId ?? null,
    })
  }
  return false
}

/** Discount vs the local live market. Returns the anchor count + weight so a
 *  weak fallback (make-level median, AU baseline) can't outrank a real
 *  same-model comp set. */
function marketDiscount(
  candidate: ScanCandidate,
  vertical: string,
  currency: string,
  pool: CompRow[],
  now: number
): { discount: number | null; anchorCount: number; weight: number; reason: string } {
  const price = candidate.price
  if (price == null || price <= 0) {
    return { discount: null, anchorCount: 0, weight: 0, reason: 'no price in search results' }
  }
  const floor = currencyFloor(currency)

  if (vertical !== 'vehicles') {
    const identity = extractItemIdentity(vertical, candidate.title)
    const comps = filterGenericComps(
      pool,
      {
        id: '',
        vertical,
        brand: identity.brand,
        tokens: identity.tokens,
        currency,
        role: identity.role,
        title: candidate.title,
      },
      { currencyFloor }
    )
    if (comps.length >= 2) {
      const med = median(comps.map((c) => c.price))
      if (med != null && med > 0) {
        return {
          discount: (med - price) / med,
          anchorCount: comps.length,
          weight: 1,
          reason: `${comps.length} live ${identity.brand ?? 'same-product'} comps`,
        }
      }
    }
    return { discount: null, anchorCount: 0, weight: 0, reason: 'no local product comps yet' }
  }

  const parsed = parseVehicleTitle(candidate.title)
  const year = parsed.year

  if (parsed.make && parsed.model) {
    const family = filterComps(
      pool,
      { id: '', make: parsed.make, model: parsed.model, year, currency },
      4,
      { currencyFloor }
    )
    if (family.length >= 2) {
      const med = median(family.map((c) => c.price))
      if (med != null && med > 0) {
        return {
          discount: (med - price) / med,
          anchorCount: family.length,
          weight: 1,
          reason: `${family.length} live ${parsed.make} ${parsed.model} comps @ ${Math.round(med).toLocaleString()}`,
        }
      }
    }
  }

  if (parsed.make) {
    const makeKey = normalizeKey(parsed.make)
    const makeRows = pool.filter((row) => {
      if (normalizeKey(row.make) !== makeKey) return false
      if ((row.currency ?? 'AUD').toUpperCase() !== currency) return false
      if (row.price < floor) return false
      if (row.year != null && year != null && Math.abs(row.year - year) > 4) return false
      return true
    })
    if (makeRows.length >= 4) {
      const med = median(makeRows.map((c) => c.price))
      if (med != null && med > 0) {
        return {
          discount: (med - price) / med,
          anchorCount: makeRows.length,
          weight: 0.45,
          reason: `${makeRows.length} live ${parsed.make} comps (model-level evidence thin)`,
        }
      }
    }
  }

  if (currency === 'AUD' && parsed.make && year != null) {
    const age = new Date(now).getFullYear() - year
    const baseline = auBaselineValue(parsed.make, age)
    if (baseline && baseline.value > 0) {
      return {
        discount: (baseline.value - price) / baseline.value,
        anchorCount: 1,
        weight: 0.3,
        reason: `AU baseline for a ${age}-year-old ${parsed.make}`,
      }
    }
  }

  return { discount: null, anchorCount: 0, weight: 0, reason: 'no local comps yet' }
}

/**
 * Rank fresh scan candidates best-first. Junk is omitted entirely; unpriced
 * rows are kept but sink below every priced candidate.
 */
export function rankScanCandidates(
  candidates: ScanCandidate[],
  ctx: RankContext
): RankedScanCandidate[] {
  const now = ctx.now ?? Date.now()
  const ranked: RankedScanCandidate[] = []

  for (const candidate of candidates) {
    const vertical = candidate.vertical || 'vehicles'
    if (isJunk(candidate, vertical)) continue

    const currency = (candidate.currency ?? ctx.currency ?? 'AUD').toUpperCase()
    const market = marketDiscount(candidate, vertical, currency, ctx.pool, now)
    const price = candidate.price != null && candidate.price > 0 ? candidate.price : null

    // Title-only condition signals (no description yet) — a light nudge, not
    // a valuation input.
    const condition = analyzeCondition({
      title: candidate.title,
      description: null,
      condition: null,
      odometer: null,
      year: parseVehicleTitle(candidate.title).year ?? null,
      titleStatus: null,
    }).score

    const dropPct =
      candidate.strikethroughPrice != null &&
      price != null &&
      candidate.strikethroughPrice > price
        ? clamp((candidate.strikethroughPrice - price) / candidate.strikethroughPrice, 0, 0.25)
        : 0

    const ageDays =
      candidate.postedAt != null
        ? Math.max(0, (now - candidate.postedAt.getTime()) / 86_400_000)
        : null
    const freshness =
      ageDays == null ? 0 : ageDays <= 2 ? 0.03 : ageDays <= 7 ? 0.02 : ageDays <= 30 ? 0.01 : 0

    const rankScore =
      price == null
        ? -1
        : clamp(market.discount ?? 0, -0.6, 0.6) * market.weight +
          dropPct * 0.3 +
          clamp(condition, -1, 1) * 0.02 +
          freshness

    ranked.push({
      ...candidate,
      rankScore: Math.round(rankScore * 10_000) / 10_000,
      estimatedDiscountPct:
        market.discount != null ? Math.round(market.discount * 1000) / 10 : null,
      anchorCount: market.anchorCount,
      rankReason: market.reason,
    })
  }

  ranked.sort(
    (a, b) =>
      b.rankScore - a.rankScore ||
      b.anchorCount - a.anchorCount ||
      (b.postedAt?.getTime() ?? 0) - (a.postedAt?.getTime() ?? 0) ||
      a.listingId.localeCompare(b.listingId)
  )
  return ranked
}

/** Rank + keep the best `limit` candidates. `skipped` counts everything not
 *  pulled this scan (including junk the ranker dropped). */
export function pickBestCandidates(
  candidates: ScanCandidate[],
  ctx: RankContext,
  limit: number
): { selected: RankedScanCandidate[]; ranked: RankedScanCandidate[]; skipped: number } {
  const ranked = rankScanCandidates(candidates, ctx)
  const max = Math.max(0, Math.floor(limit))
  return {
    selected: ranked.slice(0, max),
    ranked,
    skipped: Math.max(0, candidates.length - Math.min(max, ranked.length)),
  }
}

