/**
 * Check the per-scan "5 best" ranking without touching the database.
 *
 *   bun scripts/check-scan-ranking.ts
 */

import { pickBestCandidates, type ScanCandidate } from '../src/lib/scan-ranking'
import { extractItemIdentity } from '../src/lib/item-identity'
import type { CompRow } from '../src/lib/comps'

const now = new Date('2026-11-12T09:00:00Z').getTime()

function comp(partial: Partial<CompRow> & Pick<CompRow, 'id' | 'title' | 'price'>): CompRow {
  return {
    make: 'Toyota',
    model: 'Camry',
    year: 2019,
    currency: 'AUD',
    odometer: 100_000,
    sellerType: 'private',
    postedAt: null,
    firstSeenAt: new Date(now - 10 * 86_400_000),
    vertical: 'vehicles',
    ...partial,
  }
}

function candidate(
  partial: Partial<ScanCandidate> & Pick<ScanCandidate, 'listingId' | 'title' | 'price'>
): ScanCandidate {
  return { vertical: 'vehicles', ...partial }
}

// Ten live Camry asks → median 20,000.
const pool: CompRow[] = Array.from({ length: 10 }, (_, i) =>
  comp({
    id: `comp-${i}`,
    title: `${2017 + (i % 3)} Toyota Camry Ascent`,
    year: 2017 + (i % 3),
    price: 18_000 + (i % 5) * 1_000,
  })
)

const candidates: ScanCandidate[] = [
  candidate({ listingId: 'big-discount', title: '2019 Toyota Camry Ascent', price: 12_000 }),
  candidate({ listingId: 'good-discount', title: '2019 Toyota Camry Ascent', price: 15_000 }),
  candidate({
    listingId: 'price-drop',
    title: '2019 Toyota Camry Ascent',
    price: 19_000,
    strikethroughPrice: 22_000,
  }),
  candidate({ listingId: 'mild-discount', title: '2019 Toyota Camry Ascent', price: 18_500 }),
  candidate({ listingId: 'above-market', title: '2019 Toyota Camry Ascent', price: 21_000 }),
  candidate({ listingId: 'way-above', title: '2019 Toyota Camry Ascent', price: 22_000 }),
  candidate({ listingId: 'no-price', title: '2019 Toyota Camry Ascent', price: null }),
  // junk — the pipeline would hide these; they must not take a slot
  candidate({ listingId: 'placeholder', title: '2019 Toyota Camry Ascent', price: 1234 }),
  candidate({ listingId: 'wrecking', title: 'Toyota Camry wrecking', price: 5_000 }),
  candidate({ listingId: 'motorbike', title: '2018 Honda CBR300R', price: 3_000 }),
]

const ctx = { pool, currency: 'AUD', now }
const first = pickBestCandidates(candidates, ctx, 5)
const ids = first.selected.map((c) => c.listingId)

console.log('[ranking] selected:', ids)
console.log(
  '[ranking] scores:',
  first.selected.map((c) => `${c.listingId}=${c.rankScore} (${c.estimatedDiscountPct}%)`)
)
console.log('[ranking] skipped:', first.skipped)

if (first.selected.length !== 5) throw new Error(`expected 5 selected, got ${first.selected.length}`)
if (first.selected[0].listingId !== 'big-discount') {
  throw new Error(`expected the biggest discount first, got ${first.selected[0].listingId}`)
}
for (const junk of ['placeholder', 'wrecking', 'motorbike']) {
  if (ids.includes(junk)) throw new Error(`junk candidate ${junk} must not be selected`)
}
if (ids.includes('no-price')) throw new Error('unpriced candidate must not outrank priced rows')
if (ids.indexOf('price-drop') > ids.indexOf('mild-discount')) {
  throw new Error('advertised price drop should lift a candidate above a slightly smaller discount')
}
if (first.skipped !== 5) throw new Error(`expected 5 skipped, got ${first.skipped}`)

const second = pickBestCandidates(candidates, ctx, 5)
if (second.selected.map((c) => c.listingId).join() !== ids.join()) {
  throw new Error('ranking must be deterministic')
}

const limited = pickBestCandidates(candidates, ctx, 2)
if (limited.selected.length !== 2) throw new Error('limit must be honoured')
if (limited.selected[0].listingId !== 'big-discount') {
  throw new Error('limited selection must keep the best candidate')
}
console.log('✓ vehicle ranking passed')

// ---- generic (non-vehicle) path -----------------------------------------
const headphones = 'Sony WH-1000XM5 headphones'
const identity = extractItemIdentity('electronics', headphones)
const goodsPool: CompRow[] = [360, 400, 440].map((price, i) => ({
  id: `goods-${i}`,
  title: 'Sony WH-1000XM5 headphones',
  make: 'Sony',
  model: 'WH-1000XM5',
  year: null,
  price,
  currency: 'AUD',
  odometer: null,
  sellerType: null,
  postedAt: null,
  firstSeenAt: new Date(now - 5 * 86_400_000),
  vertical: 'electronics',
  tokens: identity.tokens,
}))
const goods = pickBestCandidates(
  [
    candidate({ listingId: 'headphones-cheap', title: headphones, price: 300, vertical: 'electronics' }),
    candidate({ listingId: 'headphones-fair', title: headphones, price: 380, vertical: 'electronics' }),
    candidate({ listingId: 'headphones-high', title: headphones, price: 450, vertical: 'electronics' }),
  ],
  { pool: goodsPool, currency: 'AUD', now },
  2
)
console.log('[ranking] goods selected:', goods.selected.map((c) => `${c.listingId}=${c.estimatedDiscountPct}%`))
if (goods.selected[0]?.listingId !== 'headphones-cheap') {
  throw new Error('generic ranking should keep the biggest discount first')
}
if (goods.selected.length !== 2) throw new Error('generic cap not honoured')
console.log('✓ generic ranking passed')

