/** FB structured body styles that are definitely not road vehicles */
const NON_ROAD_BODY_RE = /motor ?cycle|scooter|moped|quad|atv|side ?by ?side|trailer|boat|caravan|camper|tractor|mower|golf ?cart/i
/** FB structured body styles that are road vehicles */
const ROAD_BODY_RE = /sedan|hatch|wagon|coupe|convertible|suv|crossover|ute|pickup|pick-?up|van\b|vans|truck|bus|minivan|cab ?chass|motorhome|chassis|liftback|fastback|roadster/i

export interface RoadVehicleSignal {
  title: string
  /** structured body style from FB vehicle data, e.g. "SUV" / "Sedan" */
  bodyStyle?: string | null
  /** FB marketplace category id of the listing */
  categoryId?: string | null
}

/**
 * Only road vehicles (cars, utes, vans, trucks, buses) belong in the deal
 * feed. Bikes, trailers, boats, caravans, farm gear and random Marketplace
 * clutter are rejected here — deterministically, from the listing's own
 * title / body style / category.
 */
export function isRoadVehicleListing(s: RoadVehicleSignal): boolean {
  const title = String(s.title ?? '')

  // 1. explicit non-road term in the title beats everything
  if (NON_ROAD_RE.test(title)) return false

  const saysRoad = ROAD_RE.test(title)

  // 2. FB category is vehicles-but-not-road → reject unless title says road
  if (s.categoryId && NON_ROAD_CATEGORY_IDS.has(s.categoryId) && !saysRoad) return false

  // 3. positive road signal (body word / brand / model)
  if (saysRoad) return true

  // 4. FB category positively says road vehicle (Cars / SUVs / Trucks /
  //    Vans / Commercial) — non-road title terms were already vetoed in 1
  if (s.categoryId && ROAD_CATEGORY_IDS.has(s.categoryId)) return true

  // 5. structured body style decides the ambiguous cases
  if (s.bodyStyle) {
    if (NON_ROAD_BODY_RE.test(s.bodyStyle)) return false
    if (ROAD_BODY_RE.test(s.bodyStyle)) return true
  }

  // 5. no car signal at all — not something this app flips
  return false
}

export interface VinDecodeResult {
  make?: string
  model?: string
  year?: number
  bodyStyle?: string
  fuelType?: string
  transmission?: string
  drivetrain?: string
  engineCylinders?: string
  decoded: boolean
  error?: string
}

/**
 * Decode a VIN using the free NHTSA vPIC API (no key required).
 */
export async function decodeVin(vin: string, fetchImpl: typeof fetch = globalThis.fetch): Promise<VinDecodeResult> {
  const clean = vin.replace(/[^A-HJ-NPR-Z0-9]/gi, '').toUpperCase()
  if (clean.length !== 17) {
    return { decoded: false, error: `VIN must be 17 characters (got ${clean.length})` }
  }
  try {
    const res = await fetchImpl(
      `https://vpic.nhtsa.dot.gov/api/vehicles/DecodeVinValues/${clean}?format=json`,
      { headers: { Accept: 'application/json' } }
    )
    if (!res.ok) return { decoded: false, error: `NHTSA returned HTTP ${res.status}` }
    const json: any = await res.json()
    const r = json?.Results?.[0]
    if (!r) return { decoded: false, error: 'No results from NHTSA' }
    if (r.ErrorText && !/^0\s*-?\s*$/.test(String(r.ErrorText))) {
      // still return what we have
    }
    const year = r.ModelYear ? parseInt(r.ModelYear, 10) : undefined
    return {
      make: r.Make && r.Make !== '' ? String(r.Make).toLowerCase().replace(/\b\w/g, (c: string) => c.toUpperCase()) : undefined,
      model: r.Model && r.Model !== '' ? String(r.Model) : undefined,
      year: year && isFinite(year) ? year : undefined,
      bodyStyle: r.BodyClass && r.BodyClass !== '' ? String(r.BodyClass) : undefined,
      fuelType: r.FuelTypePrimary && r.FuelTypePrimary !== '' ? String(r.FuelTypePrimary) : undefined,
      transmission: r.TransmissionStyle && r.TransmissionStyle !== '' ? String(r.TransmissionStyle) : undefined,
      drivetrain: r.DriveType && r.DriveType !== '' ? String(r.DriveType) : undefined,
      engineCylinders: r.EngineCylinders && r.EngineCylinders !== '' ? String(r.EngineCylinders) : undefined,

