 *
 *  CONDITION-AWARE: when the subject is a used item, comps whose title
 *  signals NEW condition (BNIB / sealed / deadstock / with tags…) are
 *  dropped from the value set — new-condition asks carry a 1.5–3× premium
 *  and medianing a worn $30 sneaker against them reads $80+. Only skipped
 *  when enough used comps remain (≥3, the rating floor); a starving set
 *  keeps everything (an imperfect estimate beats no estimate). */
export function filterGenericComps(
  pool: CompRow[],
  subject: {
    id: string
    vertical: string
    brand: string | null
    tokens: string[]
    currency?: string | null
    role?: string | null
    /** subject's structured condition (null on most marketplace rows) */
    condition?: string | null
    /** raw subject title — checked for new-condition signals too */
    title?: string | null
  },
  opts: { currencyFloor?: (currency: string) => number } = {}
): CompRow[] {
  const floorFor = opts.currencyFloor ?? (() => GENERIC_COMP_PRICE_FLOOR)
  const matched: CompRow[] = []
  for (const c of pool) {
    if (c.price < floorFor(c.currency ?? 'AUD')) continue
    if (
      !genericCompMatch(
        {
          id: subject.id,
          vertical: subject.vertical,
          brand: subject.brand,
          tokens: subject.tokens,
          currency: subject.currency ?? null,
          role: subject.role ?? null,
        },
        {
          id: c.id,
          vertical: c.vertical ?? 'vehicles',
          brand: c.make || null,
          tokens: c.tokens ?? [],
          currency: c.currency,
          role: productRole(c.vertical, c.title),
        },
      )
    ) {
      continue
    }
    matched.push(c)
  }
  // new-condition filter for used subjects (see doc above)
  if (!subjectIsNewCondition(subject.condition ?? null, subject.title ?? '')) {
    const used = matched.filter((c) => !isNewConditionTitle(c.title))
    if (used.length >= 3) return used
  }
  return matched
}
