'use client'

import { useEffect } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { toast } from 'sonner'
import { api, stripHashSessionToken } from '@/lib/api'
import { useAppStore } from '@/lib/store'
import { useRealtime } from '@/lib/realtime'
import { AppHeader } from '@/components/app/header'
import { AppFooter } from '@/components/app/footer'
import { DealFeed } from '@/components/app/feed'
import { WatchlistManager } from '@/components/app/watchlists'
import { AlertsPanel } from '@/components/app/alerts'
import { ListingDetail } from '@/components/app/listing-detail'
import { BillingPanel } from '@/components/app/billing'
import { SettingsPanel } from '@/components/app/settings'
import { Paywall } from '@/components/app/paywall'
import { OnboardingQuiz, type OnboardingResult } from '@/components/app/onboarding'
import type { AuthUserView } from '@/lib/auth-view'

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: false,
      staleTime: 5000,
      retry: 1,
    },
  },
})

function AppInner({ user }: { user: AuthUserView }) {
  const view = useAppStore((s) => s.view)
  const selectedListingId = useAppStore((s) => s.selectedListingId)
  useRealtime()

  const { data: session } = useQuery({
    queryKey: ['session'],
    queryFn: api.session.get,
    refetchInterval: 30000,
  })

  // Poll scanner status for the footer + header pills
  const { data: scanner } = useQuery({
    queryKey: ['scanner'],
    queryFn: api.scanner.status,
    refetchInterval: 10000,
  })

  // Billing gate — Dealify has NO free plan: when the 7-day trial ends (or
  // a paid period lapses) without an active subscription the whole app is
  // replaced by the paywall. Shares the ['billing'] cache with the
  // paywall/billing panel so a subscribe unlocks instantly.
  const { data: billing } = useQuery({
    queryKey: ['billing'],
    queryFn: api.billing.get,
    refetchInterval: 30000,
  })
  const locked = billing?.plan?.tier === 'locked'

  // Personalisation profile — drives the first-run questionnaire gate:
  // onboardedAt === null means the account has never been through the quiz.
  const { data: profileData, isLoading: profileLoading } = useQuery({
    queryKey: ['profile'],
    queryFn: api.profile.get,
  })

  const quizOpen = useAppStore((s) => s.quizOpen)
  const setQuizOpen = useAppStore((s) => s.setQuizOpen)
  const queryClient = useQueryClient()

  // First-run gate: show the quiz the moment a fresh account enters (and
  // billing has resolved, so the paywall always wins over the quiz).
  const needsQuiz =
    !profileLoading &&
    profileData?.onboardedAt === null &&
    billing !== undefined &&
    !locked
  const showQuiz = quizOpen || needsQuiz

  const handleQuizDone = (result: OnboardingResult) => {
    setQuizOpen(false)
    // Feed (for-you scores), watchlists (starter radar) + profile state all
    // depend on the answers — refresh them together.
    queryClient.invalidateQueries({ queryKey: ['profile'] })
    queryClient.invalidateQueries({ queryKey: ['listings'] })
    queryClient.invalidateQueries({ queryKey: ['watchlists'] })
    if (result.profile) {
      toast.success(
        result.starterWatchlist
          ? `Personalised — “${result.starterWatchlist.name}” watchlist created`
          : 'Personalisation saved — your feed is now For you first'
      )
    }
  }

  useEffect(() => {
    // The server-side cookie fast-path authenticated us (AppShell is only
    // server-rendered with a live session cookie), so the #st= fragment the
    // sign-in page appended is redundant — scrub it from the address bar.
    if (window.location.hash.includes('st=')) stripHashSessionToken()

  }, [])

  return (
    <div className="min-h-screen flex flex-col bg-background">
      <AppHeader session={session ?? undefined} scanner={scanner ?? undefined} user={user} />

      <main className="flex-1 w-full max-w-[1440px] mx-auto px-4 sm:px-6 lg:px-8 py-6 w-full">
        {locked ? (
          <Paywall user={user} />
        ) : (
          <>
            {view === 'feed' && <DealFeed />}
            {view === 'watchlists' && <WatchlistManager />}
            {view === 'alerts' && <AlertsPanel />}
            {view === 'billing' && <BillingPanel user={user} />}
            {view === 'settings' && <SettingsPanel user={user} />}
          </>
        )}
      </main>

      <AppFooter scanner={scanner ?? undefined} />

      {selectedListingId && <ListingDetail id={selectedListingId} />}

      {/* Personalisation questionnaire — first-run gate + re-take overlay */}
      {showQuiz && (
        <OnboardingQuiz
          initialProfile={profileData?.profile ?? null}
          retune={Boolean(profileData?.profile) || quizOpen}
          onDone={handleQuizDone}
        />
      )}
    </div>
  )
}

/** The full Dealify app (feed / watchlists / alerts / billing).
 *  Server-side gated: only rendered for signed-in users (see src/app/app/page.tsx). */
export function AppShell({ user }: { user: AuthUserView }) {
  return (
    <QueryClientProvider client={queryClient}>
      <AppInner user={user} />
    </QueryClientProvider>
  )
}
