import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { requireUser } from '@/lib/auth'
import { getSsrClient } from '@/lib/scanner'
import { analyzePricing } from '@/lib/pricing/analyze'
import { removeSaleObservationsForListings } from '@/lib/pricing/sale-comps'
import { getFleetCooldown } from '@/lib/facebook/guard'
import { withFacebookRateLimitFallback } from '@/lib/facebook/retry'
import { upgradeEbayImageUrl, upgradeEbayImageUrls } from '@/lib/image-quality'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

/** Parse a stored valuationJson without letting one malformed row 500 the page. */
function safeParseValuation(raw: string): import('@/lib/valuation').ValuationResult | null {
  try {
    return JSON.parse(raw) as import('@/lib/valuation').ValuationResult
  } catch {
    return null
  }
}

/** Listing detail: full record, the 6-step pricing analysis (fair value,
 *  comparables, repair estimate, flip economics), and a live photo refresh
 *  if needed.
 *
 *  PER-ACCOUNT: only listings matched by the signed-in user's own watchlists
 *  are reachable — another account's find (even a valid listing id) 404s. */
export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const auth = await requireUser()
  if (auth.response) return auth.response
  const me = auth.user.id
  const { id } = await params
  const listing = await db.listing.findUnique({
    where: { id },
    include: {
      watchlists: {
        select: { watchlistId: true, isNew: true, watchlist: { select: { name: true, userId: true } } },
      },
    },
  })
  if (!listing) return NextResponse.json({ error: 'Listing not found' }, { status: 404 })

  // Feed membership gate: the listing must be matched by one of MY watchlists.
  // (isNew on that link drives the feed's "New" badge, so keep the link too.)
  const myLink = listing.watchlists.find((wl) => wl.watchlist.userId === me)
  if (!myLink) return NextResponse.json({ error: 'Listing not found' }, { status: 404 })

  // If we have no stored photos, try a live fetch — first via the requester's
  // own engines / a managed session's SSR client (never while the fleet is
  // resting: a detail-page hit during a rest would undo the cooldown
  // discipline). Never a 500. Only Facebook rows can live-fetch — the SSR
  // client speaks Facebook detail pages, not eBay/Vinted/… ones.
  let photoUrls: string[] = listing.photoUrls ? (JSON.parse(listing.photoUrls) as string[]) : []
  if (photoUrls.length === 0 && listing.photoUrl) photoUrls = [listing.photoUrl]
  // serving-path upgrade: stored galleries can predate the ingest upgrade
  // (and eBay placeholders resolve to the app's no-image state)
  photoUrls = upgradeEbayImageUrls(photoUrls)
  const isFacebookRow = (listing.marketplace ?? 'FacebookMarketplace') === 'FacebookMarketplace'
  if (photoUrls.length === 0 && isFacebookRow) {
    const cooldown = await getFleetCooldown(db)
    const client = cooldown.active ? null : await getSsrClient(db, undefined, me)
    if (client) {
      // Flipify's loadFacebookListingDetails pattern, verbatim:
      // withFacebookRateLimitFallback(directFetch, cachedCopy) — on a
      // Facebook rate-limit error don't rethrow and don't hammer; serve
      // the stored data instead (here: keep whatever photos we have).
      photoUrls = await withFacebookRateLimitFallback(
        async () => {
          const details = await client.getListingDetails(listing.fbListingId)
          const urls = details.photos.map((p) => p.uri).filter(Boolean)
          if (urls.length > 0) {
            // A resolved detail page proves the listing is still live —
            // un-stale it while persisting the photos. The inferred sale
            // observation (if the stale sweep already wrote one) must go:
            // this car did not sell, it just fell off the search page.
            const wasStale = listing.status === 'stale'
            await db.listing
              .update({
                where: { id: listing.id },
                data: {
                  photoUrls: JSON.stringify(urls),
                  photoUrl: urls[0],
                  ...(wasStale
                    ? { status: 'new' as const, lastSeenAt: new Date() }
                    : {}),
                },
              })
              .catch(() => {})
            if (wasStale) {
              await removeSaleObservationsForListings(db, [listing.id]).catch(() => 0)
            }
          }
          return urls
        },
        // cached fallback — stored photos (possibly empty), never a 500
        async () => []
      ).catch(() => [])
    }
  }

  const specs = listing.specifications ? JSON.parse(listing.specifications) : null

  // Personal state (saved/hidden/dismissed) lives on the UserListing edge —
  // two accounts can each shortlist the same car independently.
  const personal = await db.userListing.findUnique({
    where: { userId_listingId: { userId: me, listingId: listing.id } },
    select: { status: true },
  }).catch(() => null)

  // The pricing-intelligence pipeline: comparables (generation/variant/
  // transmission/mileage/local) → fair value (ML model + comps) → repair
  // estimate from the ad's own words → flip economics with contingency →
  // reasons underpriced + confidence. It also returns the flip plan and the
