/**
 * Web server supervisor — mirrors mini-services/scanner-service/supervisor.ts.
 *
 * The sandbox reaps long-lived node processes launched mid-session; bun
 * supervisors survive. This keeps the site up by respawning it whenever it
 * exits, with a short cool-down to avoid hot-looping.
 *
 * PRODUCTION MODE (launch cutover): serves the standalone build
 * (.next/standalone/server.js) when present, and falls back to `next dev`
 * only when the build is missing (e.g. a sandbox rollback restored sources
 * without .next) — degraded, never dead.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs'

const PORT = 3000
const STANDALONE_SERVER = '/home/z/my-project/.next/standalone/server.js'

let child: ReturnType<Bun.spawn> | null = null

/**
 * Env for the spawned server.
 *
 * The standalone server.js does NOT load .env (no @next/env in that entry)
 * and `process.chdir(__dirname)`s into .next/standalone — so without an
 * explicit injection the app would boot with no DATABASE_URL, and a relative
 * sqlite path would resolve against the BUNDLE copy, silently forking an
 * empty database. Parse .env here on EVERY spawn (fresh snapshot per respawn
 * — a later .env edit always applies on the next restart), overlay it over
 * the inherited environment, and pin the DB to the absolute live path.
 */
function childEnv(): Record<string, string> {
  const dotenv: Record<string, string> = {}
  try {
    const raw = readFileSync('/home/z/my-project/.env', 'utf8')
    for (const line of raw.split('\n')) {
      const match = /^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/.exec(line.trim())
      if (!match) continue
      let value = match[2].trim()
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1)
      }
      dotenv[match[1]] = value
    }
  } catch {
    // no .env readable — inherit the environment as-is
  }
  const env: Record<string, string> = { ...process.env, ...dotenv }
  const dbUrl = env.DATABASE_URL
  if (dbUrl && dbUrl.startsWith('file:') && !dbUrl.startsWith('file:/')) {
    env.DATABASE_URL = 'file:/home/z/my-project/' + dbUrl.slice(5).replace(/^\.\//, '')
  }
  env.NODE_OPTIONS = '--max-old-space-size=1536'
  return env
}

function spawnServer(): ReturnType<typeof Bun.spawn> {
  const prod = existsSync(STANDALONE_SERVER)
  const proc = Bun.spawn({
    cmd: prod
      ? ['node', STANDALONE_SERVER]
      : ['node_modules/.bin/next', 'dev', '--webpack', '-p', String(PORT)],
    cwd: '/home/z/my-project',
    env: childEnv(),
    stdout: 'inherit',
    stderr: 'inherit',
    stdin: 'ignore',
  })
  console.log(
    `[web-supervisor] ${new Date().toISOString()} spawned ${
      prod ? 'PROD standalone server' : 'next dev (fallback — standalone build missing)'
    } pid=${proc.pid}`
  )
  return proc
}

/**
 * Watchdog contract (ensure-stack.sh lock_owner_ok): the supervisor publishes
 * its pid so the 10-minute watchdog can tell "healthy and supervised" from
 * "orphaned server". Without this file every watchdog tick treats the chain
 * as unsupervised and KILLS + rebuilds it — a self-inflicted restart every
 * 10 minutes (2026-10-31). Written once, on startup, by the live supervisor.
 */
function publishLock() {
  try {
    writeFileSync('/tmp/dealify-web-supervisor.lock', String(process.pid))
  } catch (e) {
    console.error(`[web-supervisor] could not publish lock: ${String(e?.message ?? e)}`)
  }
}

async function main() {
  // publish the watchdog lock BEFORE anything else — even when a healthy
  // server already answers (we adopt it below instead of exiting, so the
  // chain is always supervised after ensure-stack rebuilds it)
  publishLock()

  // A healthy server already answering on the port is ADOPTED, not abandoned:
  // exiting here (the old behavior) left it orphaned — no crash respawn, and
  // every later ensure-stack tick rebuilt the chain because lock_owner_ok
  // kept failing. The loop below supervises whatever is (or comes) up.
  process.on('SIGTERM', () => child?.kill())
  process.on('SIGINT', () => child?.kill())

  while (true) {
    let serving = false
    try {
      const res = await fetch(`http://localhost:${PORT}/`, { signal: AbortSignal.timeout(2500) })
      serving = res.status < 500
    } catch {
      // nothing on the port — fall through and spawn
    }
    if (serving) {
      // adopt + wait: re-check every 5s, spawn only when the port goes quiet
      await new Promise((r) => setTimeout(r, 5000))
      continue
    }
    child = spawnServer()

