/**
 * Backfill valuations — rescore listings that have no pricing basis through
 * the valuation engine v2 (web evidence → LLM knowledge → factor model).
 *
 * Usage:
 *   bun scripts/backfill-valuations.ts [limit] [concurrency]
 *
 * Orders by newest first, skips anything that already has a fair value,
 * reuses the ValuationCache (same sneaker model = one lookup), and stops
 * cleanly on SIGINT.
 */

import { PrismaClient } from '@prisma/client'
import { scoreListing, persistScore, type ScorableListing } from '../src/lib/scoring'

const db = new PrismaClient()

const LIMIT = Number(process.argv[2] ?? '120') || 120
const CONCURRENCY = Math.max(1, Math.min(8, Number(process.argv[3] ?? '4') || 4))

let processed = 0
let priced = 0
let rated = 0
let stopped = false

process.on('SIGINT', () => {
  console.log('\n[sigint] stopping after current batch…')
  stopped = true
})

async function scoreOne(id: string): Promise<void> {
  const row = await db.listing.findUnique({ where: { id } })
  if (!row || row.price == null) return
  const scorable: ScorableListing = {
    id: row.id,
    fbListingId: row.fbListingId,
    title: row.title,
    price: row.price,
    currency: row.currency,
    vertical: row.vertical,
    year: row.year,
    make: row.make,
    model: row.model,
    description: row.description,
    odometer: row.odometer,
    titleStatus: row.titleStatus,
    sellerType: row.sellerType,
    condition: row.condition,
    postedAt: row.postedAt,
    transmission: row.transmission,
    fuelType: row.fuelType,
    state: row.state,
    previousPrice: row.previousPrice,
    firstSeenAt: row.firstSeenAt,
  }
  try {
    const score = await scoreListing(db, scorable)
    await persistScore(db, row.id, score)
    processed++
    if (score.pricing?.fairValue != null || score.valuation?.estimatedValue != null) priced++
    if (score.dealRating) rated++
    if (processed % 10 === 0) {
      console.log(`[backfill] ${processed} scored · ${priced} priced · ${rated} rated`)
    }
  } catch (err) {
    processed++
    console.warn(`[backfill] failed ${row.id}: ${String((err as Error)?.message ?? err).slice(0, 120)}`)
  }
}

async function main() {
  const candidates = await db.listing.findMany({
    where: {
      price: { not: null },
      status: { in: ['new', 'saved'] },
      OR: [{ estimatedValue: null }, { marketMedian: null }],
    },
    orderBy: { firstSeenAt: 'desc' },
    take: LIMIT,
    select: { id: true },
  })
  console.log(`[backfill] ${candidates.length} listings to price (limit ${LIMIT}, concurrency ${CONCURRENCY})`)

  const queue = candidates.map((c) => c.id)
  const workers = Array.from({ length: CONCURRENCY }, async () => {
    while (!stopped) {
      const id = queue.shift()
      if (!id) return
      await scoreOne(id)
    }
  })
  await Promise.all(workers)
  console.log(`[backfill] DONE: ${processed} scored · ${priced} priced · ${rated} rated`)
}

main()
  .catch((err) => {
    console.error('[backfill] fatal:', err)
    process.exitCode = 1
  })
  .finally(() => db.$disconnect())

