/** Cached comp pool — safe to call from any request path, cheap when warm */
export async function getCompPool(db: PrismaClient): Promise<CompRow[]> {
  const rowCount = await db.listing.count({
    where: { price: { not: null, gt: 20 }, isScam: false, status: { in: [...COMP_STATUSES] } },
  })
  if (cache && cache.rowCount === rowCount && Date.now() - cache.loadedAt < POOL_TTL_MS) {
    return cache.rows
  }
  const rows = await loadPool(db)
  cache = { rowCount, loadedAt: Date.now(), rows }
  return rows
}

/** Force the next getCompPool call to reload (after direct listing writes) */
export function invalidateCompPool(): void {
  cache = null
}

/** Comps for one subject: same make+model, within the year window, same
 *  currency (worldwide support — comps never cross markets), priced above
 *  the per-currency parts floor. */
export function filterComps(
  pool: CompRow[],
  subject: {
    id: string
    make: string | null
    model: string | null
    year: number | null
    currency?: string | null
  },
  yearWindow: number,
  opts: { currencyFloor?: (currency: string) => number } = {}
): CompRow[] {
  const make = normalizeKey(subject.make)
  const model = normalizeKey(subject.model)
  if (!make || !model) return []
  const cur = (subject.currency ?? 'AUD').toUpperCase()
  const floorFor = opts.currencyFloor ?? (() => 500)
  const out: CompRow[] = []
  for (const c of pool) {
    if (c.id === subject.id) continue
    // worldwide: comps are same-market only — mixing an AUD pool with USD/
    // GBP listings would price everything wrong in both directions
    if ((c.currency ?? 'AUD').toUpperCase() !== cur) continue
    if (c.price < floorFor(c.currency ?? 'AUD')) continue
    if (normalizeKey(c.make) !== make || normalizeKey(c.model) !== model) continue
    if (c.year != null && subject.year != null && Math.abs(c.year - subject.year) > yearWindow) continue
    out.push(c)
  }
  return out
}

/** Generic (non-vehicle) comps: same vertical + same brand (or both
 *  brand-less) + identity-token evidence of the same product, same currency,
 *  same product role (a "case for iPhone" never comps a bare iPhone). The
 *  subject's tokens come from extractItemIdentity; pool rows carry
 *  precomputed tokens for their stored vertical.
 *
export async function findComparables(
  db: import('@prisma/client').PrismaClient,
  subject: ComparableSubject
): Promise<ComparableReport> {
  const pool = await getCompPool(db)
  return rankComparables(pool, subject)
}

/** Pure function so the training/eval path can reuse it without a DB. */
export function rankComparables(pool: CompRow[], subject: ComparableSubject): ComparableReport {
  const make = normalizeKey(subject.make)
  const model = normalizeKey(subject.model)
  if (!make || !model) return { comps: [], stats: emptyStats() }

  const subjectTokens = [...titleTokens(subject.title, subject.make, subject.model)]
  const subjectAuto = autoFlag(subject.transmission)
  const subjectState = (subject.state ?? '').toUpperCase() || null
  // worldwide: the comparable set lives in the subject's own market —
  // currency is the hard boundary (dollars never comp against pounds)
  const subjectCurrency = (subject.currency ?? 'AUD').toUpperCase()

  const scored: ComparableListing[] = []

  for (const c of pool) {
    if (c.id === subject.id) continue
    if (normalizeKey(c.make) !== make || normalizeKey(c.model) !== model) continue
    if ((c.currency ?? 'AUD').toUpperCase() !== subjectCurrency) continue
    if (c.price < currencyFloor(c.currency ?? 'AUD')) continue

    const notes: string[] = []
    let score = 0.34 // same model family — the entry ticket

    // generation
    if (c.year != null && subject.year != null) {
      const dy = Math.abs(c.year - subject.year)
      if (dy <= GENERATION_WINDOW) {
        score += 0.2 * (1 - dy / (GENERATION_WINDOW + 1))
        notes.push(dy === 0 ? 'Same model year' : `±${dy}yr generation match`)
      } else if (dy <= GENERATION_WINDOW * 2) {
        score += 0.05
        notes.push(`${dy}yrs apart — same family, different generation`)
      } else {
        // far generation: weak comp
        score += 0
        notes.push(`${dy}yrs apart`)
      }
    }

    // variant / trim overlap
    if (subjectTokens.length > 0) {
      const compTokens = titleTokens(c.title, c.make, c.model)
      if (compTokens.size > 0) {
        let shared = 0
        for (const t of subjectTokens) if (compTokens.has(t)) shared++
        const overlap = Math.min(1, shared / Math.min(subjectTokens.length, compTokens.size))
        if (overlap > 0) {
          score += 0.14 * overlap
          notes.push(overlap >= 0.6 ? 'Same variant/trim' : 'Similar spec')
        }
      }
    }

    // transmission
    const compAuto = autoFlag(c.transmission ?? null)
    if (subjectAuto !== null && compAuto !== null) {
      if (subjectAuto === compAuto) {
        score += 0.1
        notes.push(subjectAuto ? 'Both automatic' : 'Both manual')
      } else {
        notes.push('Different transmission')
      }
    }

    // mileage band
    if (subject.odometer != null && c.odometer != null) {
      const band = subject.odometer * MILEAGE_BAND
      const diff = Math.abs(c.odometer - subject.odometer)
      if (diff <= band) {
        score += 0.12 * (1 - diff / Math.max(1, band))
        notes.push(
          diff < 8_000 ? 'Near-identical kms' : `${(c.odometer / 1000).toFixed(0)}k km — within band`
        )
      } else {
        notes.push(`${(c.odometer / 1000).toFixed(0)}k km — outside mileage band`)
      }
    }

    // local market
    const compState = (c.state ?? '').toUpperCase() || null
    if (subjectState && compState) {
      if (compState === subjectState) {
        score += 0.08
        notes.push(c.city ? `${c.city}, ${compState} — local market` : `${compState} — local market`)
      } else {
        notes.push(`${compState} — interstate comp`)
      }
    }

    // recency
    const rec = recencyScore(c.postedAt ?? c.firstSeenAt)
    score += 0.06 * rec

    scored.push({
      id: c.id,
      title: c.title,
      make: c.make,
      model: c.model,
      year: c.year,
      price: c.price,
      odometer: c.odometer,
      transmission: c.transmission ?? null,
      sellerType: c.sellerType ?? null,
      city: c.city ?? null,
      state: c.state ?? null,
      photoUrl: c.photoUrl ?? null,
      distanceKm: c.distanceKm ?? null,
      postedAt: c.postedAt ?? c.firstSeenAt,
      similarity: Math.max(0, Math.min(1, score)),
      matchNotes: notes.slice(0, 4),
    })
  }

