      label: 'Kilometres',
      detail: `${(subjectOdo / 1000).toFixed(0)}k km vs ${(compsAvgOdometer / 1000).toFixed(0)}k km comps avg · $${odometerRatePerKm.toFixed(3)}/km`,
      amount: Math.round((compsAvgOdometer - subjectOdo) * odometerRatePerKm),
    })
  }
  if (subjectYear != null && compsAvgYear != null && Math.abs(subjectYear - compsAvgYear) >= 1) {
    adjustments.push({
      label: 'Model year',
      detail: `${subjectYear} vs ${compsAvgYear.toFixed(1)} comps avg · ${(YEAR_RATE * 100).toFixed(1)}%/yr`,
      amount: Math.round((subjectYear - compsAvgYear) * YEAR_RATE * wMedian),
    })
  }
  if (Math.abs(conditionModifierPct) > 0.001) {
    adjustments.push({
      label: 'Condition & history',
      detail:
        signals.length > 0
          ? signals
              .slice(0, 3)
              .map((s) => s.label)
              .join(' · ')
          : 'listing description signals',
      amount: Math.round(estimatedValue - baseEstimate),
    })
  }

  return {
    method,
    confidence,
    compCount: comps.length,
    compsWithOdometer,
    dealerComps,
    privateComps,
    baseMedian: Math.round(wMedian),
    rawAvg: Math.round(rawAvg),
    rawLow,
    rawHigh,
    odometerRatePerKm,
    yearRatePct: YEAR_RATE,
    subjectOdometer: subjectOdo,
    compsAvgOdometer,
    subjectYear,
    compsAvgYear,
    baseEstimate: Math.round(baseEstimate),
    conditionModifierPct,
    estimatedValue,
    low: Math.round(estimatedValue * (1 - uncertainty)),
    high: Math.round(estimatedValue * (1 + uncertainty)),
    conditionScore,
    conditionSignals: signals.slice(0, 8),
    adjustments,
  }
}

/** Human label for the valuation method (UI) */
export function valuationMethodLabel(v: ValuationResult): string {
  switch (v.method) {
    case 'regression':
      return `Regression on ${v.compCount} live comps (km + year)`
    case 'weighted-comps':
      return `km/year-adjusted median of ${v.compCount} live comps`
    default:
      return `Market median of ${v.compCount} live comps`
  }
}

