export function hasAccountMarker(): boolean {
  try {
    return window.localStorage.getItem(HAS_ACCOUNT_KEY) === '1'
  } catch {
    return false
  }
}

/** Session token carried in the URL fragment (`/app#st=…`) — the ONLY channel
 *  that survives a full page navigation when both cookies and storage are
 *  blocked (sandboxed preview iframe). Fragments never reach the server. */
export function hashSessionToken(): string | null {
  if (typeof window === 'undefined') return null
  const m = /(?:^|[#&])st=([^&]+)/.exec(window.location.hash)
  if (!m) return null
  try {
    return decodeURIComponent(m[1])
  } catch {
    return null
  }
}

/** Remove the #st= fragment from the address bar without reloading. */
export function stripHashSessionToken(): void {
  if (typeof window === 'undefined' || !window.location.hash) return
  window.history.replaceState(null, '', window.location.pathname + window.location.search)
}

/** Build the /app URL with the session token attached as a fragment. */
export function appUrlWithSession(token: string | null | undefined): string {
  return token ? `/app#st=${encodeURIComponent(token)}` : '/app'
}

async function jsonFetch<T>(url: string, init?: RequestInit): Promise<T> {
  const token = typeof window !== 'undefined' ? storedAuthToken() : null
  const res = await fetch(url, {
    ...init,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...(init?.headers ?? {}),
    },
  })
  // Session expired / signed out elsewhere — back through the sign-in gate
  // (NOT the marketing landing: the user has an account, the session just died)
  // ONLY when the 401 provably came from our own API (it always answers with a
  // JSON body). The sandbox gateway / proxy chain can emit its own HTML 401s
  // while restarting — treating those as session death wiped perfectly valid
  // tokens and signed people out for no reason. A non-JSON 401 is transient:
  // keep the stored token, let the caller's retry logic ride it out.
  if (res.status === 401) {
    const fromOurApi = (res.headers.get('content-type') ?? '').includes('application/json')
    if (fromOurApi && typeof window !== 'undefined' && !window.location.pathname.startsWith('/api')) {
      clearStoredAuthToken()
      stripHashSessionToken()
      window.location.assign('/signup?mode=login')
    }
    throw new Error('Sign in required')
  }
  const data = await res.json().catch(() => ({}))
  if (!res.ok) {
    throw new Error((data as any).error ?? `Request failed: ${res.status}`)
  }
  return data as T
}

