const PROFIT_GRADIENT =
  // Loss zone stays red to just past break-even; the orange band is a short
  // "modest return" strip; green owns the final 40% (>= 20% ROI), so a strong
  // return reads green at a glance instead of only at the very end.
  'linear-gradient(90deg, #ff5b67 0%, #ff5b67 32%, #ff7b38 36%, #ff9a4a 50%, #ff9a4a 56%, #34d399 60%, #34d399 100%)'

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

function roiColor(roi: number) {
  if (roi <= 0) return '#ff5b67'
  if (roi < 10) return '#ff7b38'
  if (roi < 20) return '#ff9a4a'
  return '#34d399'
}

