'use client'

import { TrendingUp, TrendingDown, Minus } from 'lucide-react'
import { cn } from '@/lib/utils'
import { formatPrice } from '@/lib/api'

/**
 * Smooth red → orange → yellow → lime → green track, matching the reference
 * scale: deep red on the left, orange through the low-return zone, yellow
 * around break-even/mid, and a broad green sweep for the final third.
 * Stops are percentages along the bar, not ROI values.
 */
const PROFIT_STOPS: Array<{ at: number; hex: string }> = [
  { at: 0, hex: '#c0392b' },
  { at: 14, hex: '#d35400' },
  { at: 30, hex: '#e67e22' },
  { at: 44, hex: '#edb32c' },
  { at: 54, hex: '#f1c40f' },
  { at: 64, hex: '#c3d63b' },
  { at: 76, hex: '#9bd142' },
  { at: 88, hex: '#6fc24a' },
  { at: 100, hex: '#56b947' },
]

const PROFIT_GRADIENT = `linear-gradient(90deg, ${PROFIT_STOPS.map(
  (s) => `${s.hex} ${s.at}%`
).join(', ')})`

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

function hexToRgb(hex: string): [number, number, number] {
  const n = parseInt(hex.slice(1), 16)
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255]
}

function rgbToHex(rgb: [number, number, number]): string {
  return `#${rgb.map((v) => v.toString(16).padStart(2, '0')).join('')}`
}

/** Sample the marker colour from the same track so the dot never disagrees
 *  with the gradient underneath it. */
function roiColor(roi: number) {
  const pos = clamp(((roi + 25) / 75) * 100, 0, 100)
  for (let i = 0; i < PROFIT_STOPS.length - 1; i++) {
    const a = PROFIT_STOPS[i]
    const b = PROFIT_STOPS[i + 1]
    if (pos >= a.at && pos <= b.at) {
      const t = (pos - a.at) / (b.at - a.at)
      const ca = hexToRgb(a.hex)
      const cb = hexToRgb(b.hex)
      return rgbToHex([
        Math.round(ca[0] + t * (cb[0] - ca[0])),
        Math.round(ca[1] + t * (cb[1] - ca[1])),
        Math.round(ca[2] + t * (cb[2] - ca[2])),
      ])
    }
  }
  return PROFIT_STOPS[PROFIT_STOPS.length - 1].hex

/**
 * Factor extraction — the REAL, human-legible factors that drive a used item's
 * value, pulled deterministically out of the listing text:
 *
 *   condition (new / like-new / good / worn / parts-grade)
 *   completeness (boxed / sealed / accessories / missing parts)
 *   defects (cracked / torn / dents / water damage…)
 *   age (posted recency where the vertical depreciates with age)
 *   size/spec tokens (256GB, size US 9, model number) — passed to the LLM
 *
 * PURE module (no imports beyond the SDK-free std lib) so both the web app
 * and the scanner mini-service can use it.
 */

import type { EstimateFactor } from './types'

export type ConditionGrade = 'new' | 'like-new' | 'good' | 'worn' | 'parts'

const CONDITION_TITLE_PATTERNS: Array<[RegExp, ConditionGrade, string]> = [
  [/\b(brand[- ]new|bnib|sealed|unopened|never used|unworn|deadstock|ds)\b/i, 'new', 'listed as brand new'],
  [/\b(like new|as new|excellent condition|near new|barely used|pristine|mint)\b/i, 'like-new', 'listed as like-new'],
  [/\b(new with (tags|box)|nwt|nib)\b/i, 'new', 'new with tags/box'],
  [/\b(good condition|great condition|well kept|lightly used|gently used)\b/i, 'good', 'listed as good condition'],
  [/\b(used|pre[- ]?owned|second[- ]?hand)\b/i, 'good', 'used'],
  [/\b(worn|faded|scuffed|heavily used|well used|loved)\b/i, 'worn', 'visible wear'],
  [/\b(broken|cracked|for parts|not working|faulty|damaged|torn|ripped|stained|water damage|snapped)\b/i, 'parts', 'defects / parts-grade'],
]

const FB_CONDITION_MAP: Record<string, ConditionGrade> = {
  NEW: 'new',
  LIKE_NEW: 'like-new',
  GOOD: 'good',
  FAIR: 'worn',
}

/** Completeness / bonus-value keywords (box, tags, receipts boost resale) */
const COMPLETENESS_PATTERNS: Array<[RegExp, string, number]> = [
  [/\b(with box|in box|original box|boxed)\b/i, 'original box included', 5],
  [/\b(with (receipt|proof of purchase)|receipts?)\b/i, 'receipt included', 4],
  [/\b(with tags|tags (attached|on)|nwt)\b/i, 'tags attached', 4],
  [/\b(complete|all (accessories|pieces)|incl(uding)? (box|charger|cables))\b/i, 'complete set', 3],
  [/\b(no box|without box|missing (box|parts|charger|cable))\b/i, 'missing parts/box', -8],
]

/** Brand tier — the market pays structurally different multiples per tier.
 *  Multiplier vs a category-typical baseline for the same vertical. */
const BRAND_TIERS: Record<string, number> = {
  // tier 1 — premium / collector brands (hold or gain value)
  'rolex': 12, 'omega': 6, 'louis vuitton': 8, 'gucci': 5, 'prada': 5, 'chanel': 8,
  'hermes': 12, 'dior': 5, 'balenciaga': 4, 'moncler': 3.5, 'canada goose': 3.5,
  // tier 1.5 — strong resale verticals
  'nike': 1.6, 'jordan': 2.2, 'adidas': 1.4, 'new balance': 1.4, 'yeezy': 2.5,
  'apple': 2.0, 'macbook': 2.2, 'iphone': 2.0, 'sony': 1.5, 'playstation': 1.6,
  'nintendo': 1.6, 'nvidia': 2.2, 'leica': 6, ' canon': 1.4, 'nikon': 1.4,
  'lego': 1.8, 'funko': 1.2, 'thermomix': 3, 'dyson': 1.8, 'stanley': 1.6,
  'carhartt': 1.6, 'the north face': 1.5, 'arc': 2.5, 'patagonia': 1.5,
  'specialized': 1.8, 'trek': 1.7, 'giant': 1.4, 'mongoose': 1.2, 'shimano': 1.3,
  'makita': 1.5, 'milwaukee': 1.6, 'dewalt': 1.5, 'bosch': 1.4, 'hilti': 2,
  'vintage': 1.8, 'retro': 1.4,
  // budget / commodity
  'kmart': 0.5, 'target': 0.5, 'big w': 0.5, 'aliexpress': 0.4, 'temu': 0.35,
  'shein': 0.35, 'generic': 0.5, 'no brand': 0.5, 'replica': 0.3,
}

export interface ItemFactors {
  condition: ConditionGrade
  /** how the condition was determined (for the UI) */
  conditionEvidence: string
  completeness: Array<{ detail: string; impactPct: number }>
  /** normalized identity key for caching: vertical + brand + core title */
  identityKey: string
  brandTier: { brand: string; multiplier: number } | null
  /** extraction quality — below this the factor model refuses to estimate */
  specificity: number
}

const FILLER_WORDS = new Set([
  'the', 'a', 'an', 'and', 'or', 'for', 'with', 'in', 'on', 'of', 'to', 'at',
  'new', 'used', 'sale', 'sell', 'selling', 'cheap', 'price', 'pickup', 'pick',
  'up', 'post', 'posting', 'express', 'genuine', 'authentic', 'condition',
  'excellent', 'great', 'good', 'very', 'really', 'bundled', 'bundle', 'x',
  'au', 'brand', 'size', 'mens', 'womens', 'kids', 'unisex',
])

/** Normalize a title into a stable identity core: lowercase, strip noise,
 *  keep brand + model + spec tokens. This is the cache key — two listings of
 *  the same item share one external valuation. */
export function identityKeyFor(item: {
  title: string
  vertical: string
  brand?: string | null
  currency?: string | null
  year?: number | null
  condition?: string | null
}): string {
  const brand = item.brand?.toLowerCase().replace(/[^a-z0-9 ]/g, '').trim() ?? ''
  const condition = item.condition?.toLowerCase().replace(/[^a-z0-9]+/g, '').trim() || 'unspecified'
  const words = item.title
    .toLowerCase()
    .replace(/[^a-z0-9. ]/g, ' ')
    .split(/\s+/)
    .filter((w) => w.length > 1 && !FILLER_WORDS.has(w))
    // Sort tokens so seller wording/order does not create duplicate cache
    // entries, while retaining model and size numbers that distinguish SKUs.
    .sort()
  return [
    'v2',
    item.vertical.toLowerCase(),
    (item.currency ?? 'AUD').toUpperCase(),
    item.year ?? '',
    condition,
    brand,
    ...words,
  ].filter(Boolean).join('|')
}

export function extractItemFactors(item: {
  title: string
  // feeds identityKeyFor — the vertical is part of the cache identity, so
  // callers (estimate engine) always know and pass it
  vertical: string
  description?: string | null
  condition?: string | null
  brand?: string | null
  postedAt?: Date | null
  currency?: string | null
  year?: number | null
}): ItemFactors {
  const haystack = `${item.title}\n${item.description ?? ''}`

  // ---- condition: FB structured condition first, then title/desc keywords
  let condition: ConditionGrade | null = null
  let conditionEvidence = ''
  if (item.condition && FB_CONDITION_MAP[item.condition.toUpperCase()]) {
    condition = FB_CONDITION_MAP[item.condition.toUpperCase()]
    conditionEvidence = `marketplace condition: ${item.condition.toLowerCase().replace('_', ' ')}`
  }
  if (!condition) {
    // strongest (most specific) match wins — defects/grades before generic "used"
    for (const [re, grade, evidence] of CONDITION_TITLE_PATTERNS) {
      if (re.test(haystack)) {
        condition = grade
        conditionEvidence = evidence
        break
      }
    }
  }
  if (!condition) {
    condition = 'good'
    conditionEvidence = 'no condition signals — assumed typical used'
  }

  // ---- completeness / bonus-value keywords
  const completeness: Array<{ detail: string; impactPct: number }> = []
  for (const [re, detail, impact] of COMPLETENESS_PATTERNS) {
    if (re.test(haystack)) completeness.push({ detail, impactPct: impact })
  }

  // ---- brand tier (longest alias match wins — "the north face" over "north")
  let brandTier: { brand: string; multiplier: number } | null = null
  const hayLower = haystack.toLowerCase()
  for (const [brand, mult] of Object.entries(BRAND_TIERS)) {
    if (hayLower.includes(brand.trim())) {
      if (!brandTier || brand.trim().length > brandTier.brand.length) {
        brandTier = { brand: brand.trim(), multiplier: mult }
      }
    }
  }

  // ---- specificity: how much identity evidence the title actually carries
  const contentWords = item.title
    .toLowerCase()
    .replace(/[^a-z0-9. ]/g, ' ')
    .split(/\s+/)
    .filter((w) => w.length > 1 && !FILLER_WORDS.has(w))
  const specificity =
    Math.min(1, contentWords.length / 6) * 0.6 +
    (item.brand ? 0.2 : 0) +
    (/\d/.test(item.title) ? 0.2 : 0)

  return {
    condition,
    conditionEvidence,
    completeness,
    identityKey: identityKeyFor(item),
    brandTier,
    specificity,
  }
}

/** Human-readable factor list for the estimate (UI renders these). */
export function describeFactors(f: ItemFactors, opts: { ageMonths?: number | null } = {}): EstimateFactor[] {
  const out: EstimateFactor[] = [
    {
      label: 'Condition',
      detail: f.conditionEvidence,
      impactPct:
        f.condition === 'new' ? 12
          : f.condition === 'like-new' ? 6
            : f.condition === 'good' ? 0
              : f.condition === 'worn' ? -18
                : -55,
    },
  ]
  for (const c of f.completeness) {
    out.push({ label: 'Completeness', detail: c.detail, impactPct: c.impactPct })
  }
  if (f.brandTier) {
    out.push({
      label: 'Brand',
      detail: `${f.brandTier.brand} — ${f.brandTier.multiplier >= 1.5 ? 'strong resale demand' : f.brandTier.multiplier >= 0.9 ? 'mid-tier resale' : 'low resale demand'}`,
      impactPct: Math.round((f.brandTier.multiplier - 1) * 100),
    })
  }
  if (opts.ageMonths != null && opts.ageMonths >= 6) {
    const dep = Math.min(25, Math.round(opts.ageMonths * 1.5))
    out.push({ label: 'Listing age', detail: `posted ${Math.round(opts.ageMonths)} months ago — older ads price lower`, impactPct: -dep })
  }
  return out
}

/** CONDITION multiplier for the factor model (vs a typical-used baseline). */
export function conditionMultiplier(condition: ConditionGrade): number {
  switch (condition) {
    case 'new': return 1.15
    case 'like-new': return 1.05
    case 'good': return 1
    case 'worn': return 0.78
    case 'parts': return 0.4
  }
}

/**
 * Factor-model tier — the deterministic floor of the valuation engine.
 *
 * When the web and LLM tiers both decline (offline, timeout, unrecognizable
 * item), a fully transparent multiplicative model produces a
 * "category-typical" estimate:
 *
 *   baseline(vertical)  — what a typical used item in the category goes for
 *   × brand tier        — premium brands resell higher, commodity lower
 *   × condition         — new 1.15 … worn 0.78 … parts 0.4
 *   × completeness      — boxed/receipted bumps, missing parts dips
 *
 * Confidence is always 'low' and the method never produces deal ratings —
 * it exists so the deal room can show an honest, explained number instead
 * of nothing. PURE of Prisma and of the SDK.
 */

import type { EstimateFactor } from './types'
import { conditionMultiplier, type ItemFactors } from './item-factors'

/** Typical private-sale used price per vertical, in the listing's own
 *  currency units (rough but honest category medians across AU/US/EU markets).
 *
 *  NOTE: no `vehicles` entry, deliberately. A used car spans $500 wreck to
 *  $200k sports car — one flat "typical vehicle" number manufactured $12,000
 *  estimates for every sparse-comp $3–5k car (the sanity clamp only fires
 *  past 4× asking, so they all sailed through at exactly 12k). Vehicles are
 *  priced by the comp/ML pipeline and, when that finds nothing, by the
 *  market-intel evidence ladder (lib/pricing/market-intel.ts) — never by
 *  this goods-scale model. */
const CATEGORY_BASELINE: Record<string, number> = {
  electronics: 160,
  fashion: 45,
  furniture: 120,
  collectibles: 60,
  bikes: 350,
  gaming: 140,
  appliances: 130,
  tools: 90,
  other: 60,
}

export interface FactorModelResult {
  value: number
  low: number
  high: number
  factors: EstimateFactor[]
}

export function factorModelEstimate(opts: {
  vertical: string
  factors: ItemFactors
  price?: number | null
  currency: string
}): FactorModelResult | null {
  // Vehicles never price off a goods category baseline — the vehicle path
  // falls back to the market-intel evidence ladder instead (see note above).
  if (opts.vertical === 'vehicles') return null

  const base = CATEGORY_BASELINE[opts.vertical] ?? CATEGORY_BASELINE.other
  if (!base || base <= 0) return null

  // ---- refuse items with no identity (a bare "couch" gets no estimate)
  if (opts.factors.specificity < 0.25) return null

  const brandMult = opts.factors.brandTier?.multiplier ?? 1
  const condMult = conditionMultiplier(opts.factors.condition)
  const completenessMult = opts.factors.completeness.reduce(
    (acc, c) => acc * (1 + c.impactPct / 100),
    1
  )

  const raw = base * brandMult * condMult * Math.max(0.5, completenessMult)
  // Keep this generic category prior independent of the seller's asking
  // price. It is display-only (low confidence, never deal-rated), and using
  // the ask here would make overpriced and underpriced items self-validating.
  const value = raw

  const factors: EstimateFactor[] = [
    {
      label: 'Category baseline',
      detail: `typical used ${opts.vertical} item sells around ${Math.round(base)} ${opts.currency}`,
    },
  ]
  if (opts.factors.brandTier) {
    factors.push({
      label: 'Brand tier',
      detail: `${opts.factors.brandTier.brand} — ${brandMult >= 1.5 ? 'strong resale demand' : brandMult >= 0.9 ? 'mid-tier resale' : 'low resale demand'} (×${brandMult})`,
      impactPct: Math.round((brandMult - 1) * 100),
    })
  }
  factors.push({
    label: 'Condition',
    detail: opts.factors.conditionEvidence,
    impactPct: Math.round((condMult - 1) * 100),
  })
  for (const c of opts.factors.completeness) {
    factors.push({ label: 'Completeness', detail: c.detail, impactPct: c.impactPct })
  }

  return {
    value: Math.round(value),
    low: Math.round(value * 0.6),
    high: Math.round(value * 1.5),
    factors,
  }
}

/**
 * Estimate engine orchestrator — prices an item through the external tiers
 * (web evidence → LLM market knowledge → deterministic factor model), with a
 * DB cache keyed by NORMALIZED ITEM IDENTITY so the same sneaker model across
 * fifty listings costs one lookup.
 *
 * Tier policy:
 *   web-evidence       ≥3 real price candidates → done (confidence by count)
 *   market-knowledge   LLM JSON validated → display-only estimate
 *   category-typical   factor model — only when the item has enough identity
 *
 * Prisma handles persistence; the SDK imports are lazy and every failure
 * degrades to the next tier (never throws into the scan path).
 */

import type { PrismaClient } from '@prisma/client'
import type { EstimateResult, EstimableItem } from './types'
import { extractItemFactors, describeFactors, type ItemFactors } from './item-factors'
import { fetchWebEvidence } from './web-evidence'
import { fetchLlmEstimate } from './llm-value'
import { factorModelEstimate } from './factor-model'

const CACHE_TTL_MS = 14 * 24 * 3600_000 // two weeks — used markets move slowly
const FALLBACK_TTL_MS = 3 * 24 * 3600_000 // negative/weak results retry sooner

// ---- global spacing for external calls ------------------------------------
// The valuation LLM and the search function both rate-limit aggressively
// (46× 429 in a 5-worker backfill). A process-wide minimum spacing keeps the
// scan path, the rescore pass and backfills inside the quota.
let lastExternalCallAt = 0
/** Per-process spacing — env-overridable so backfills can run gentler than
 *  the live scan path (the valuation LLM throttles around 10–20 calls/min). */
const EXTERNAL_SPACING_MS = Math.max(1500, Number(process.env.ESTIMATE_SPACING_MS ?? '2500'))
async function externalSpacing(): Promise<void> {
  const wait = lastExternalCallAt + EXTERNAL_SPACING_MS - Date.now()
  if (wait > 0) await new Promise((r) => setTimeout(r, wait))
  lastExternalCallAt = Date.now()
}

interface CachePayload {
  result: EstimateResult | null
  negative?: boolean
}

async function readCache(db: PrismaClient, key: string): Promise<CachePayload | null> {
  const row = await db.valuationCache.findUnique({ where: { cacheKey: key } }).catch(() => null)
  if (!row) return null
  if (row.expiresAt.getTime() < Date.now()) return null
  try {
    return JSON.parse(row.payload) as CachePayload
  } catch {
    return null
  }
}

async function writeCache(
  db: PrismaClient,
  key: string,
  vertical: string,
  source: string,
  payload: CachePayload,
  ttlMs: number
): Promise<void> {
  await db.valuationCache
    .upsert({
      where: { cacheKey: key },
      create: {
        cacheKey: key,
        vertical,
        source,
        payload: JSON.stringify(payload),
        expiresAt: new Date(Date.now() + ttlMs),
      },
      update: {
        source,
        payload: JSON.stringify(payload),
        expiresAt: new Date(Date.now() + ttlMs),
      },
    })
    .catch(() => {})
}

/**
 * Estimate the market value of an item. `compsCount` is the LOCAL comp count —
 * the caller skips this engine entirely when comps already priced the item.
 * Returns null only when every tier declines (the caller then prices nothing,
 * exactly as before — but that is now the rare case).
 */
export async function estimateMarketValue(
  db: PrismaClient,
  item: EstimableItem,
  opts: { skipCache?: boolean } = {}
): Promise<{ estimate: EstimateResult; factors: ItemFactors } | null> {
  const currency = (item.currency ?? 'AUD').toUpperCase()
  const factors = extractItemFactors(item)
  if (item.price == null || item.price <= 0) return null

  // ---- cache (per item, year, currency and condition). Asking price is not
  // part of fair value, so a genuinely cheap listing can reuse the same
  // independent estimate as a normally priced listing of the same item.
  if (!opts.skipCache) {
    const cached = await readCache(db, factors.identityKey)
    if (cached) {
      if (cached.result) {
        return {
          estimate: { ...cached.result, currency, estimatedAt: new Date().toISOString() },
          factors,
        }
      } else if (cached.negative) {
        // negative cache — recent failed lookups retry on their shorter TTL only
        return null
      }
    }
  }

  // ---- tier 2: LLM market knowledge (fast, grounded, retry-backed) — tried
  // FIRST: the web-search function rate-limits harder than the LLM, so the
  // knowledge tier is the workhorse and web prices upgrade weak cases.
  const llm = await (async () => {
    await externalSpacing()
    try {
      return await fetchLlmEstimate({
        title: item.title,
        vertical: item.vertical,
        brand: item.brand ?? null,
        model: item.model ?? null,
        condition: item.condition ?? null,
        description: item.description ?? null,
        price: item.price ?? null,
        currency,
        year: item.year ?? null,
        factorContext: [
          `condition: ${factors.condition} (${factors.conditionEvidence})`,
          ...factors.completeness.map((c) => c.detail),
          factors.brandTier ? `brand tier: ${factors.brandTier.brand} ×${factors.brandTier.multiplier}` : '',
        ].filter(Boolean),
      })
    } catch {
      return null
    }
  })()

  // ---- tier 3: web evidence (real observed prices) — upgrades the estimate
  // when the LLM declined or answered with low confidence
  let web: Awaited<ReturnType<typeof fetchWebEvidence>> = null
  if (!llm || llm.confidence === 'low') {
    await externalSpacing()
    try {
      web = await fetchWebEvidence({
        item: { title: item.title, brand: item.brand ?? null, vertical: item.vertical, price: item.price },
        currency,
      })
    } catch {
      web = null
    }
  }

  if (web && (!llm || llm.confidence !== 'high')) {
    const confidence = web.candidates >= 6 ? 'medium' : 'low'
    const estimate: EstimateResult = {
      value: web.value,
      low: web.low,
      high: web.high,
      method: 'web-evidence',
      confidence,
      currency,
      evidenceCount: web.candidates,
      factors: describeFactors(factors),
      sources: web.sources,
      queries: web.queries,
      estimatedAt: new Date().toISOString(),
    }
    await writeCache(db, factors.identityKey, item.vertical, 'web-evidence', { result: estimate }, CACHE_TTL_MS)
    return { estimate, factors }
  }

  if (llm) {
    const estimate: EstimateResult = {
      value: llm.value,
      low: llm.low,
      high: llm.high,
      method: 'market-knowledge',
      confidence: llm.confidence,
      currency,
      evidenceCount: 1,
      factors: llm.factors.length > 0 ? llm.factors : describeFactors(factors),
      sources: [],
      queries: [],
      estimatedAt: new Date().toISOString(),
    }
    await writeCache(db, factors.identityKey, item.vertical, 'market-knowledge', { result: estimate }, CACHE_TTL_MS)
    return { estimate, factors }
  }

  // ---- tier 4: deterministic factor model (always available, never rates)
  const modeled = factorModelEstimate({
    vertical: item.vertical,
    factors,
    price: item.price ?? null,
    currency,
  })

  if (modeled) {
    const estimate: EstimateResult = {
      value: modeled.value,
      low: modeled.low,
      high: modeled.high,
      method: 'category-typical',
      confidence: 'low',
      currency,
      evidenceCount: 0,
      factors: modeled.factors,
      sources: [],
      queries: [],
      estimatedAt: new Date().toISOString(),
    }
    await writeCache(db, factors.identityKey, item.vertical, 'category-typical', { result: estimate }, FALLBACK_TTL_MS)
    return { estimate, factors }
  }

  // nothing worked — negative-cache briefly so a scan loop doesn't re-burn
  // the web+LLM budget on the same unidentifiable item
  await writeCache(db, factors.identityKey, item.vertical, 'failed', { result: null, negative: true }, FALLBACK_TTL_MS)
  return null
}

function median(values: number[]): number | null {
  if (values.length === 0) return null
  const sorted = [...values].sort((a, b) => a - b)
  const mid = Math.floor(sorted.length / 2)
  return sorted.length % 2 === 0 ? (sorted[mid - 1] + sorted[mid]) / 2 : sorted[mid]
}

/** Weighted median: accumulate weights until half the total is crossed */
function weightedMedian(entries: Array<{ value: number; weight: number }>): number | null {
  if (entries.length === 0) return null
  const sorted = [...entries].sort((a, b) => a.value - b.value)
  const total = sorted.reduce((s, e) => s + e.weight, 0)
  let acc = 0
  for (const e of sorted) {
    acc += e.weight
    if (acc >= total / 2) return e.value
  }
  return sorted[sorted.length - 1].value
}

/** Recency weight — current market data counts more than stale listings */
function recencyWeight(date: Date | null | undefined): number {
  if (!date) return 0.7
  const days = (Date.now() - date.getTime()) / 86_400_000
  if (days <= 30) return 1
  return Math.max(0.35, Math.pow(0.5, Math.max(0, days - 30) / RECENCY_HALF_DAYS))
}

