/** True when the matched phrase is preceded by a negation ("has had no
 *  mechanical issues", "never had any accident damage" must NOT count as
 *  negative signals). Allows up to two filler words in between. */
function isNegated(haystack: string, m: RegExpMatchArray): boolean {
  if (m.index == null) return false
  const before = haystack.slice(Math.max(0, m.index - 24), m.index)
  return /\b(no|never|zero|without|hasn'?t|haven'?t|don'?t|doesn'?t|didn'?t|isn'?t|aren'?t)\s+(?:\w+\s+){0,2}$/i.test(before)
}

/** Short context snippet around a regex hit — the seller's own words */
function snippet(haystack: string, m: RegExpMatchArray): string {
  if (m.index == null) return m[0]
  const start = Math.max(0, m.index - 34)
  const end = Math.min(haystack.length, m.index + m[0].length + 34)
  let s = haystack.slice(start, end).replace(/\s+/g, ' ').trim()
  if (start > 0) s = '…' + s
  if (end < haystack.length) s += '…'
  return s.length > 96 ? s.slice(0, 96) + '…' : s
}

