  if (a.id === b.id) return false
  if (a.vertical !== b.vertical) return false
  if ((b.currency ?? 'AUD').toUpperCase() !== (a.currency ?? 'AUD').toUpperCase()) return false
  // product-role gate — an accessory never comps the host product (either
  // direction) and different accessory classes never comp each other
  if ((a.role ?? null) !== (b.role ?? null)) return false
